{
  "name": "LyricLens: Video Storyboarder",
  "description": "Transform song lyrics into detailed cinematic storyboards with automated visual descriptions and scene-flow diagrams using Gemini AI and Mermaid.js."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface StoryboardSegment {
  id: string;
  sectionTitle: string; // e.g., "Verse 1", "Chorus"
  lyrics: string;
  visuals: string;
  cameraWork: string;
  lightingMood: string;
  mermaidDiagram: string;
}

export interface StoryboardData {
  title: string;
  artist: string;
  overallMood: string;
  segments: StoryboardSegment[];
}

export enum AppState {
  IDLE = 'IDLE',
  LOADING = 'LOADING',
  RESULT = 'RESULT',
  ERROR = 'ERROR'
}

import { GoogleGenAI, Type } from "@google/genai";
import { StoryboardData } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateStoryboard = async (lyrics: string): Promise<StoryboardData> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Analyze these lyrics and generate a detailed cinematic video clip storyboard. 
    Break the song into logical segments (e.g., Intro, Verse 1, Pre-Chorus, Chorus, Bridge, Outro).
    For each segment, provide lyrics, visual description, camera work, lighting, and a Mermaid.js diagram code (e.g., flowchart or sequence diagram) representing the scene flow.

    LYRICS:
    ${lyrics}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          title: { type: Type.STRING },
          artist: { type: Type.STRING },
          overallMood: { type: Type.STRING },
          segments: {
            type: Type.ARRAY,
            items: {
              type: Type.OBJECT,
              properties: {
                id: { type: Type.STRING },
                sectionTitle: { type: Type.STRING },
                lyrics: { type: Type.STRING },
                visuals: { type: Type.STRING },
                cameraWork: { type: Type.STRING },
                lightingMood: { type: Type.STRING },
                mermaidDiagram: { type: Type.STRING },
              },
              required: ["id", "sectionTitle", "lyrics", "visuals", "cameraWork", "lightingMood", "mermaidDiagram"]
            }
          }
        },
        required: ["title", "artist", "overallMood", "segments"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text.trim());
};

import React, { useEffect, useRef } from 'react';
import mermaid from 'mermaid';

interface MermaidChartProps {
  chart: string;
  id: string;
}

const MermaidChart: React.FC<MermaidChartProps> = ({ chart, id }) => {
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    mermaid.initialize({
      startOnLoad: true,
      theme: 'dark',
      securityLevel: 'loose',
      fontFamily: 'JetBrains Mono',
    });

    const renderChart = async () => {
      if (chartRef.current) {
        chartRef.current.innerHTML = '';
        try {
            // Clean common AI formatting issues in mermaid code
            const cleanChart = chart
                .replace(/```mermaid/g, '')
                .replace(/```/g, '')
                .trim();

            const { svg } = await mermaid.render(`mermaid-${id}`, cleanChart);
            chartRef.current.innerHTML = svg;
        } catch (error) {
            console.error('Mermaid render error:', error);
            chartRef.current.innerHTML = '<div class="text-red-400 text-xs p-2">Invalid diagram markup</div>';
        }
      }
    };

    renderChart();
  }, [chart, id]);

  return (
    <div className="mermaid-container w-full overflow-hidden flex justify-center bg-slate-900/50 rounded-lg p-4" ref={chartRef} />
  );
};

export default MermaidChart;

import React, { useState, useCallback } from 'react';
import { generateStoryboard } from './services/geminiService';
import { AppState, StoryboardData } from './types';
import StoryboardCard from './components/StoryboardCard';

const App: React.FC = () => {
  const [lyrics, setLyrics] = useState('');
  const [status, setStatus] = useState<AppState>(AppState.IDLE);
  const [storyboard, setStoryboard] = useState<StoryboardData | null>(null);
  const [error, setError] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!lyrics.trim()) return;

    setStatus(AppState.LOADING);
    setError(null);
    try {
      const data = await generateStoryboard(lyrics);
      setStoryboard(data);
      setStatus(AppState.RESULT);
    } catch (err) {
      console.error(err);
      setError("Failed to generate storyboard. Please check your API key and try again.");
      setStatus(AppState.ERROR);
    }
  };

  const handleReset = useCallback(() => {
    setStatus(AppState.IDLE);
    setStoryboard(null);
    setError(null);
  }, []);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {/* Navigation / Header */}
      <header className="sticky top-0 z-50 bg-[#020617]/80 backdrop-blur-md border-b border-slate-800/50">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
              <i className="fa-solid fa-wand-magic-sparkles text-white text-xl"></i>
            </div>
            <div>
              <h1 className="text-xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
                LyricLens
              </h1>
              <p className="text-[10px] uppercase tracking-[0.2em] text-slate-500 font-bold">
                Director's Assistant
              </p>
            </div>
          </div>
          {status !== AppState.IDLE && (
            <button 
              onClick={handleReset}
              className="px-4 py-2 text-sm font-medium text-slate-400 hover:text-white transition-colors flex items-center gap-2"
            >
              <i className="fa-solid fa-rotate-left"></i> New Storyboard
            </button>
          )}
        </div>
      </header>

      <main className="max-w-7xl mx-auto px-6 py-12">
        {status === AppState.IDLE && (
          <div className="max-w-2xl mx-auto text-center animate-in fade-in slide-in-from-bottom-4 duration-700">
            <h2 className="text-4xl md:text-5xl font-extrabold text-white mb-6 tracking-tight">
              Turn your songs into <br/>
              <span className="text-blue-500">cinematic visions.</span>
            </h2>
            <p className="text-lg text-slate-400 mb-10 leading-relaxed">
              Paste your lyrics below. Our AI director will analyze the mood, structure, and themes to generate a technical storyboard with visual notes and scene flow diagrams.
            </p>

            <form onSubmit={handleSubmit} className="space-y-6">
              <div className="relative group">
                <textarea
                  value={lyrics}
                  onChange={(e) => setLyrics(e.target.value)}
                  placeholder="Paste song lyrics here... (e.g. Yesterday, all my troubles seemed so far away...)"
                  className="w-full h-64 p-6 bg-slate-900/50 border border-slate-800 rounded-3xl focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 outline-none text-lg transition-all resize-none group-hover:border-slate-700"
                />
                <div className="absolute bottom-4 right-6 text-slate-600 text-xs font-medium">
                  Markdown support enabled
                </div>
              </div>
              <button
                type="submit"
                disabled={!lyrics.trim()}
                className="w-full py-4 px-8 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed text-white rounded-2xl font-bold text-lg shadow-xl shadow-blue-600/20 transition-all active:scale-[0.98] flex items-center justify-center gap-3"
              >
                <i className="fa-solid fa-clapperboard"></i> Generate Visual Storyboard
              </button>
            </form>
          </div>
        )}

        {status === AppState.LOADING && (
          <div className="flex flex-col items-center justify-center py-20 animate-pulse">
            <div className="relative w-24 h-24 mb-8">
              <div className="absolute inset-0 border-4 border-blue-500/20 rounded-full"></div>
              <div className="absolute inset-0 border-4 border-blue-500 rounded-full border-t-transparent animate-spin"></div>
              <div className="absolute inset-0 flex items-center justify-center">
                <i className="fa-solid fa-film text-blue-500 text-3xl"></i>
              </div>
            </div>
            <h3 className="text-2xl font-bold text-white mb-2">Directing Scene...</h3>
            <p className="text-slate-400">Analyzing lyrical flow and drafting visual transitions...</p>
          </div>
        )}

        {status === AppState.ERROR && (
          <div className="max-w-lg mx-auto bg-red-500/10 border border-red-500/50 p-6 rounded-2xl text-center">
            <i className="fa-solid fa-triangle-exclamation text-red-500 text-3xl mb-4"></i>
            <h3 className="text-xl font-bold text-white mb-2">Production Halt</h3>
            <p className="text-red-400 mb-6">{error}</p>
            <button 
              onClick={handleReset}
              className="px-6 py-2 bg-red-500 text-white font-bold rounded-xl hover:bg-red-600 transition-colors"
            >
              Retry
            </button>
          </div>
        )}

        {status === AppState.RESULT && storyboard && (
          <div className="animate-in fade-in slide-in-from-bottom-8 duration-700">
            <div className="mb-12 border-l-4 border-blue-600 pl-6 py-2">
              <h2 className="text-4xl font-black text-white tracking-tight">
                {storyboard.title}
              </h2>
              <p className="text-xl text-slate-400 font-medium">
                by {storyboard.artist}
              </p>
              <div className="flex items-center gap-4 mt-4">
                <span className="text-xs bg-slate-800 text-slate-300 px-3 py-1 rounded-full border border-slate-700 font-bold uppercase tracking-wider">
                  Atmosphere: {storyboard.overallMood}
                </span>
                <span className="text-xs bg-slate-800 text-slate-300 px-3 py-1 rounded-full border border-slate-700 font-bold uppercase tracking-wider">
                  {storyboard.segments.length} Scenes
                </span>
              </div>
            </div>

            <div className="space-y-4">
              {storyboard.segments.map((segment) => (
                <StoryboardCard key={segment.id} segment={segment} />
              ))}
            </div>

            <footer className="mt-20 pt-10 border-t border-slate-800 text-center text-slate-500 text-sm italic">
              Developed by LyricLens AI • Storyboard rendering powered by Mermaid.js & Gemini 3 Flash
            </footer>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface StoryboardSegment {
  id: string;
  sectionTitle: string;
  lyrics: string;
  visuals: string;
  cameraWork: string;
  lightingMood: string;
  mermaidDiagram?: string;
  isProcessing?: boolean;
}

export interface StoryboardData {
  title: string;
  artist: string;
  overallMood: string;
  segments: StoryboardSegment[];
}

export enum AppStep {
  PASTE_LYRICS = 'PASTE_LYRICS',
  DEFINE_SCENES = 'DEFINE_SCENES',
  PRODUCTION = 'PRODUCTION'
}

import { GoogleGenAI, Type } from "@google/genai";
import { StoryboardSegment } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateSceneContent = async (lyrics: string, context: string): Promise<Partial<StoryboardSegment>> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `As a video director, provide visual instructions for this specific song segment.
    CONTEXT: ${context}
    SEGMENT LYRICS: ${lyrics}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          visuals: { type: Type.STRING, description: "Action happening in the scene" },
          cameraWork: { type: Type.STRING, description: "Camera movement and angles" },
          lightingMood: { type: Type.STRING, description: "Lighting style and color palette" },
          sectionTitle: { type: Type.STRING, description: "Logical name (e.g. Verse 1)" }
        },
        required: ["visuals", "cameraWork", "lightingMood", "sectionTitle"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text.trim());
};

export const generateDiagram = async (segment: StoryboardSegment): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Create a Mermaid.js flowchart representing the flow of the following film scene description. Use clean, professional syntax. Do not include markdown blocks.
    SCENE: ${segment.visuals}
    CAMERA: ${segment.cameraWork}`,
  });

  return response.text || '';
};

import React, { useState } from 'react';
import { StoryboardSegment } from '../types';
import MermaidChart from './MermaidChart';
import { generateDiagram } from '../services/geminiService';

interface StoryboardCardProps {
  segment: StoryboardSegment;
  onUpdate: (updated: StoryboardSegment) => void;
  onRemove?: () => void;
}

const StoryboardCard: React.FC<StoryboardCardProps> = ({ segment, onUpdate, onRemove }) => {
  const [isGeneratingDiagram, setIsGeneratingDiagram] = useState(false);

  const handleChange = (field: keyof StoryboardSegment, value: string) => {
    onUpdate({ ...segment, [field]: value });
  };

  const handleBuildDiagram = async () => {
    setIsGeneratingDiagram(true);
    try {
      const diagram = await generateDiagram(segment);
      onUpdate({ ...segment, mermaidDiagram: diagram });
    } catch (err) {
      console.error(err);
    } finally {
      setIsGeneratingDiagram(false);
    }
  };

  return (
    <div className="group relative bg-slate-800/40 border border-slate-700/50 rounded-2xl overflow-hidden hover:border-blue-500/30 transition-all duration-300 backdrop-blur-sm shadow-xl mb-6">
      <div className="flex flex-col md:flex-row">
        {/* Left Side: Lyrics (Read Only usually) */}
        <div className="w-full md:w-1/3 p-6 border-b md:border-b-0 md:border-r border-slate-700/50 bg-slate-900/40">
          <div className="flex items-center justify-between mb-4">
            <input 
              value={segment.sectionTitle}
              onChange={(e) => handleChange('sectionTitle', e.target.value)}
              className="bg-blue-600/20 text-blue-400 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider outline-none border border-transparent focus:border-blue-500/50"
            />
            {onRemove && (
              <button onClick={onRemove} className="text-slate-600 hover:text-red-400 transition-colors">
                <i className="fa-solid fa-trash-can text-xs"></i>
              </button>
            )}
          </div>
          <p className="text-base font-medium leading-relaxed italic text-slate-300 whitespace-pre-wrap font-serif">
            {segment.lyrics}
          </p>
        </div>

        {/* Right Side: Editable Visuals */}
        <div className="w-full md:w-2/3 p-6 space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div>
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
                  <i className="fa-solid fa-clapperboard"></i> Visual Content
                </label>
                <textarea 
                  value={segment.visuals}
                  onChange={(e) => handleChange('visuals', e.target.value)}
                  placeholder="Describe what we see..."
                  className="w-full bg-slate-900/60 border border-slate-700/50 rounded-xl p-3 text-sm text-slate-200 outline-none focus:border-blue-500/50 h-24 resize-none"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
                    <i className="fa-solid fa-video"></i> Camera
                  </label>
                  <input 
                    value={segment.cameraWork}
                    onChange={(e) => handleChange('cameraWork', e.target.value)}
                    className="w-full bg-slate-900/60 border border-slate-700/50 rounded-lg p-2 text-xs text-slate-300 outline-none focus:border-blue-500/50"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
                    <i className="fa-solid fa-lightbulb"></i> Lighting
                  </label>
                  <input 
                    value={segment.lightingMood}
                    onChange={(e) => handleChange('lightingMood', e.target.value)}
                    className="w-full bg-slate-900/60 border border-slate-700/50 rounded-lg p-2 text-xs text-slate-300 outline-none focus:border-blue-500/50"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <i className="fa-solid fa-diagram-project"></i> Scene Architecture
                </label>
                <button 
                  onClick={handleBuildDiagram}
                  disabled={isGeneratingDiagram || !segment.visuals}
                  className="text-[10px] font-bold text-blue-400 hover:text-blue-300 uppercase tracking-wider flex items-center gap-1 disabled:opacity-50"
                >
                  {isGeneratingDiagram ? (
                    <><i className="fa-solid fa-spinner animate-spin"></i> Processing</>
                  ) : (
                    <><i className="fa-solid fa-bolt"></i> {segment.mermaidDiagram ? 'Update Chart' : 'Build Chart'}</>
                  )}
                </button>
              </div>
              {segment.mermaidDiagram ? (
                <MermaidChart chart={segment.mermaidDiagram} id={segment.id} />
              ) : (
                <div className="h-32 bg-slate-900/30 border border-dashed border-slate-700/50 rounded-xl flex items-center justify-center text-slate-600 text-xs text-center p-4">
                  {segment.visuals ? 'Ready to generate architectural flow' : 'Enter visuals to enable diagramming'}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StoryboardCard;

import React, { useState, useMemo } from 'react';
import { generateSceneContent } from './services/geminiService';
import { AppStep, StoryboardSegment } from './types';
import StoryboardCard from './components/StoryboardCard';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]); // Indices of lines where a new scene starts
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);

  // Split raw text into lines
  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleStartDefining = (e: React.FormEvent) => {
    e.preventDefault();
    if (rawText.trim()) setStep(AppStep.DEFINE_SCENES);
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setStep(AppStep.PRODUCTION);

    // Convert markers to actual segments
    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
      });
    }

    setSegments(newSegments);

    // AI Populate initial drafts
    const populated = await Promise.all(newSegments.map(async (seg) => {
      try {
        const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard");
        return { ...seg, ...aiData };
      } catch (e) {
        return seg;
      }
    }));

    setSegments(populated);
    setIsBulkProcessing(false);
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-slate-800/50">
        <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20">
              <i className="fa-solid fa-clapperboard text-white text-sm"></i>
            </div>
            <h1 className="text-lg font-bold tracking-tight">LyricLens Studio</h1>
          </div>

          <div className="flex items-center gap-6">
            <div className="hidden md:flex items-center gap-2">
              {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.PRODUCTION].map((s, idx) => (
                <React.Fragment key={s}>
                  <div className={`text-[10px] font-bold uppercase tracking-widest ${step === s ? 'text-blue-500' : 'text-slate-600'}`}>
                    {s.replace('_', ' ')}
                  </div>
                  {idx < 2 && <div className="w-4 h-[1px] bg-slate-800"></div>}
                </React.Fragment>
              ))}
            </div>
            <button 
              onClick={() => { setStep(AppStep.PASTE_LYRICS); setSegments([]); setSceneMarkers([]); }}
              className="text-xs text-slate-500 hover:text-white transition-colors"
            >
              Reset
            </button>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 py-12">
        {step === AppStep.PASTE_LYRICS && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-white mb-3">Begin Production</h2>
              <p className="text-slate-400">Paste your raw text or lyrics. We'll split it into scenes in the next step.</p>
            </div>
            <form onSubmit={handleStartDefining} className="space-y-6">
              <textarea
                value={rawText}
                onChange={(e) => setRawText(e.target.value)}
                placeholder="Paste lyrics or narrative text here..."
                className="w-full h-80 p-6 bg-slate-900/50 border border-slate-800 rounded-3xl focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 outline-none text-lg transition-all resize-none font-serif"
              />
              <button
                type="submit"
                disabled={!rawText.trim()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-3"
              >
                Proceed to Scene Layout
              </button>
            </form>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-xl mx-auto">
            <div className="text-center mb-8">
              <h2 className="text-2xl font-bold text-white mb-2">Identify Scene Breaks</h2>
              <p className="text-sm text-slate-400">Click the spaces between lines where you want to start a new scene.</p>
            </div>

            <div className="space-y-1 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button 
                      onClick={() => toggleMarker(idx)}
                      className={`w-full group relative py-2 transition-all flex items-center justify-center`}
                    >
                      <div className={`h-[2px] transition-all ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500' : 'w-1/4 bg-slate-800 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                      {sceneMarkers.includes(idx) && (
                        <div className="absolute bg-blue-500 text-[8px] font-black text-white px-2 py-0.5 rounded uppercase tracking-tighter">New Scene</div>
                      )}
                    </button>
                  )}
                  <div className={`text-center py-1 font-serif text-slate-300 transition-colors ${sceneMarkers.includes(idx) ? 'pt-4' : ''}`}>
                    {line}
                  </div>
                </React.Fragment>
              ))}
            </div>

            <div className="mt-10 flex gap-4">
              <button
                onClick={() => setStep(AppStep.PASTE_LYRICS)}
                className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-2xl font-bold transition-all"
              >
                Back
              </button>
              <button
                onClick={handleProceedToProduction}
                className="flex-[2] py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all"
              >
                Generate Pre-Production Draft
              </button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            <div className="flex justify-between items-end mb-8">
              <div>
                <h2 className="text-3xl font-bold text-white mb-1">Director's Board</h2>
                <p className="text-slate-400 text-sm">Review, edit, and build technical architectures for each scene.</p>
              </div>
              {isBulkProcessing && (
                <div className="flex items-center gap-2 text-blue-400 font-bold text-xs uppercase tracking-widest animate-pulse">
                  <i className="fa-solid fa-spinner animate-spin"></i>
                  Drafting Script...
                </div>
              )}
            </div>

            <div className="space-y-2">
              {segments.map((seg, idx) => (
                <StoryboardCard 
                  key={seg.id} 
                  segment={seg} 
                  onUpdate={(updated) => updateSegment(idx, updated)}
                />
              ))}
            </div>

            <div className="mt-12 pt-8 border-t border-slate-800 flex justify-center gap-6">
               <button className="px-6 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl font-bold flex items-center gap-2 transition-all">
                  <i className="fa-solid fa-file-export"></i> Export PDF
               </button>
               <button className="px-6 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20 transition-all">
                  <i className="fa-solid fa-play"></i> Presentation Mode
               </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface StoryboardSegment {
