import React, { useEffect } from 'react';
import { StoryboardSegment } from '../types';
import MermaidChart from './MermaidChart';

interface PresentationViewProps {
  segments: StoryboardSegment[];
  currentIndex: number;
  onNext: () => void;
  onPrev: () => void;
  onExit: () => void;
}

const PresentationView: React.FC<PresentationViewProps> = ({ 
  segments, 
  currentIndex, 
  onNext, 
  onPrev, 
  onExit 
}) => {
  const current = segments[currentIndex];

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'ArrowRight' || e.key === ' ') onNext();
      if (e.key === 'ArrowLeft') onPrev();
      if (e.key === 'Escape') onExit();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onNext, onPrev, onExit]);

  if (!current) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black text-white flex flex-col overflow-hidden animate-in fade-in duration-500">
      {/* Header HUD */}
      <div className="p-6 flex justify-between items-center bg-gradient-to-b from-black/80 to-transparent">
        <div className="flex items-center gap-4">
          <button 
            onClick={onExit}
            className="w-10 h-10 rounded-full bg-white/10 hover:bg-white/20 flex items-center justify-center transition-colors"
          >
            <i className="fa-solid fa-xmark"></i>
          </button>
          <div>
            <h2 className="text-xs font-bold text-blue-500 uppercase tracking-widest">{current.sectionTitle}</h2>
            <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Production Mode • Scene {currentIndex + 1} of {segments.length}</p>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <div className="flex h-1 gap-1 w-32 bg-white/10 rounded-full overflow-hidden">
              {segments.map((_, i) => (
                <div key={i} className={`flex-1 ${i <= currentIndex ? 'bg-blue-500' : 'bg-transparent'}`}></div>
              ))}
           </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col md:flex-row p-8 md:p-12 gap-12 overflow-hidden">
        {/* Visual & Description */}
        <div className="flex-1 flex flex-col justify-center space-y-8">
          <div className="space-y-4">
             <span className="text-xs font-bold text-slate-600 uppercase tracking-[0.3em]">Lyrics</span>
             <blockquote className="text-3xl md:text-5xl font-serif italic text-slate-200 leading-tight">
               "{current.lyrics}"
             </blockquote>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-8 border-t border-white/10">
            <div>
               <h4 className="text-[10px] font-bold text-blue-500 uppercase tracking-widest mb-3">Action & Visuals</h4>
               <p className="text-lg text-slate-400 leading-relaxed">{current.visuals}</p>
            </div>
            <div className="space-y-6">
              <div>
                <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">Camera</h4>
                <p className="text-sm font-medium text-slate-300 italic">{current.cameraWork}</p>
              </div>
              <div>
                <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-1">Lighting</h4>
                <p className="text-sm font-medium text-slate-300 italic">{current.lightingMood}</p>
              </div>
            </div>
          </div>
        </div>

        {/* Diagram Area */}
        <div className="w-full md:w-1/2 flex items-center justify-center">
          {current.mermaidDiagram ? (
            <div className="w-full max-w-2xl bg-slate-900/40 rounded-3xl p-8 border border-white/5 shadow-2xl">
              <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-6 text-center">Scene Architecture</h4>
              <MermaidChart chart={current.mermaidDiagram} id={`pres-${current.id}`} />
            </div>
          ) : (
            <div className="w-full h-full border border-dashed border-white/10 rounded-3xl flex items-center justify-center text-slate-600 italic">
              No architectural diagram for this scene
            </div>
          )}
        </div>
      </div>

      {/* Footer Controls */}
      <div className="p-8 flex justify-center items-center gap-8 bg-gradient-to-t from-black/80 to-transparent">
        <button 
          onClick={onPrev}
          disabled={currentIndex === 0}
          className="group flex items-center gap-3 px-6 py-3 rounded-2xl hover:bg-white/5 disabled:opacity-20 transition-all"
        >
          <i className="fa-solid fa-arrow-left group-hover:-translate-x-1 transition-transform"></i>
          <span className="text-sm font-bold uppercase tracking-widest">Previous</span>
        </button>

        <div className="h-8 w-[1px] bg-white/10"></div>

        <button 
          onClick={onNext}
          disabled={currentIndex === segments.length - 1}
          className="group flex items-center gap-3 px-6 py-3 rounded-2xl hover:bg-white/5 disabled:opacity-20 transition-all"
        >
          <span className="text-sm font-bold uppercase tracking-widest">Next Scene</span>
          <i className="fa-solid fa-arrow-right group-hover:translate-x-1 transition-transform"></i>
        </button>
      </div>
    </div>
  );
};

