    );
  };

  const handleStartDefining = (e: React.FormEvent) => {
    e.preventDefault();
    if (rawText.trim()) setStep(AppStep.DEFINE_SCENES);
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
      });
    }

    setSegments(newSegments);

    const populated = await Promise.all(newSegments.map(async (seg) => {
      try {
        const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed);
        return { ...seg, ...aiData };
      } catch (e) {
        return seg;
      }
    }));

    setSegments(populated);
    setIsBulkProcessing(false);
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const saveProject = () => {
    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments,
      step,
      version: "1.0.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-project-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => {
    fileInputRef.current?.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText);
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        // Don't auto-jump to presentation if loaded from a presentation state
        setStep(project.step === AppStep.PRESENTATION ? AppStep.PRODUCTION : project.step || AppStep.PASTE_LYRICS);
      } catch (err) {
        alert("Failed to load project file. Invalid format.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input
  };

  const startProductionMode = () => {
    setCurrentSceneIndex(0);
    setStep(AppStep.PRESENTATION);
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {step === AppStep.PRESENTATION && (
        <PresentationView 
          segments={segments}
          currentIndex={currentSceneIndex}
          onNext={() => setCurrentSceneIndex(p => Math.min(segments.length - 1, p + 1))}
          onPrev={() => setCurrentSceneIndex(p => Math.max(0, p - 1))}
          onExit={() => setStep(AppStep.PRODUCTION)}
        />
      )}

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-slate-800/50">
        <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20 cursor-pointer" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
              <i className="fa-solid fa-clapperboard text-white text-sm"></i>
            </div>
            <h1 className="text-lg font-bold tracking-tight">LyricLens Studio</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 mr-4">
              {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.PRODUCTION].map((s, idx) => (
                <React.Fragment key={s}>
                  <div className={`text-[10px] font-bold uppercase tracking-widest ${step === s ? 'text-blue-500' : 'text-slate-600'}`}>
                    {s.replace('_', ' ')}
                  </div>
                  {idx < 2 && <div className="w-4 h-[1px] bg-slate-800"></div>}
                </React.Fragment>
              ))}
            </div>

            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={loadProject} 
              accept=".json" 
              className="hidden" 
            />

            <div className="flex items-center gap-2 border-l border-slate-800 pl-4">
              <button 
                onClick={handleLoadClick}
                className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold"
                title="Load Project"
              >
                <i className="fa-solid fa-folder-open"></i> Load
              </button>
              <button 
                onClick={saveProject}
                className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold"
                title="Save Project"
              >
                <i className="fa-solid fa-floppy-disk"></i> Save
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 py-12">
        {step === AppStep.PASTE_LYRICS && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-white mb-3 tracking-tight">Directing Desk</h2>
              <p className="text-slate-400">Set the narrative and paste your source text.</p>
            </div>
            <form onSubmit={handleStartDefining} className="space-y-8">
              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
                  Narrative Seed / Angle
                </label>
                <input
                  type="text"
                  value={narrativeSeed}
                  onChange={(e) => setNarrativeSeed(e.target.value)}
                  placeholder="e.g. A dystopian future with neon lighting, melancholy mood, focus on shadows"
                  className="w-full p-4 bg-slate-900/50 border border-slate-800 rounded-2xl focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 outline-none text-sm transition-all"
                />
              </div>

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
                  Lyrics / Script
                </label>
                <textarea
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  placeholder="Paste lyrics or narrative text here..."
                  className="w-full h-80 p-6 bg-slate-900/50 border border-slate-800 rounded-3xl focus:ring-2 focus:ring-blue-500/50 focus:border-blue-500 outline-none text-lg transition-all resize-none font-serif"
                />
              </div>

              <button
                type="submit"
                disabled={!rawText.trim()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-3"
              >
                Proceed to Scene Layout
              </button>
            </form>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-xl mx-auto">
            <div className="text-center mb-8">
              <h2 className="text-2xl font-bold text-white mb-2">Identify Scene Breaks</h2>
              <p className="text-sm text-slate-400">Click the spaces between lines to define start points for new visuals.</p>
            </div>

            <div className="space-y-1 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50 shadow-inner">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button 
                      onClick={() => toggleMarker(idx)}
                      className={`w-full group relative py-2 transition-all flex items-center justify-center`}
                    >
                      <div className={`h-[2px] transition-all ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'w-1/4 bg-slate-800 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                      {sceneMarkers.includes(idx) && (
                        <div className="absolute bg-blue-500 text-[8px] font-black text-white px-2 py-0.5 rounded uppercase tracking-tighter">New Scene</div>
                      )}
                    </button>
                  )}
                  <div className={`text-center py-1 font-serif text-slate-300 transition-colors ${sceneMarkers.includes(idx) ? 'pt-4 text-white font-semibold' : ''}`}>
                    {line}
                  </div>
                </React.Fragment>
              ))}
            </div>

            <div className="mt-10 flex gap-4">
              <button
                onClick={() => setStep(AppStep.PASTE_LYRICS)}
                className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-2xl font-bold transition-all"
              >
                Back
              </button>
              <button
                onClick={handleProceedToProduction}
                className="flex-[2] py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all"
              >
                Generate Pre-Production Draft
              </button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4">
              <div>
                <h2 className="text-3xl font-bold text-white mb-1">Director's Board</h2>
                <p className="text-slate-400 text-sm">
                  Angle: <span className="text-blue-400 italic">"{narrativeSeed || 'Standard Cinematic'}"</span>
                </p>
              </div>
              <div className="flex items-center gap-3">
                {isBulkProcessing && (
                  <div className="flex items-center gap-2 text-blue-400 font-bold text-xs uppercase tracking-widest animate-pulse mr-4">
                    <i className="fa-solid fa-spinner animate-spin"></i>
                    Drafting Script...
                  </div>
                )}
                <button 
                  onClick={saveProject}
                  className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold text-xs flex items-center gap-2 transition-all"
                >
                  <i className="fa-solid fa-floppy-disk"></i> Save Changes
                </button>
              </div>
            </div>

            <div className="space-y-2">
              {segments.map((seg, idx) => (
                <StoryboardCard 
                  key={seg.id} 
                  segment={seg} 
                  onUpdate={(updated) => updateSegment(idx, updated)}
                />
              ))}
            </div>

            <div className="mt-12 pt-8 border-t border-slate-800 flex justify-center gap-6">
               <button onClick={saveProject} className="px-6 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl font-bold flex items-center gap-2 transition-all">
                  <i className="fa-solid fa-download"></i> Download Bundle
               </button>
               <button 
                onClick={startProductionMode}
                className="px-6 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20 transition-all"
               >
                  <i className="fa-solid fa-play"></i> Production Mode
               </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface Character {
  id: string;
  name: string;
  imageUrl?: string;
}

export interface StoryboardSegment {
  id: string;
  sectionTitle: string;
  lyrics: string;
  visuals: string;
  cameraWork: string;
  lightingMood: string;
  mermaidDiagram?: string;
  isProcessing?: boolean;
}

export interface StoryboardProject {
  rawText: string;
  narrativeSeed: string;
  sceneMarkers: number[];
  segments: StoryboardSegment[];
  characters: Character[];
  step: AppStep;
  version: string;
}

export enum AppStep {
  PASTE_LYRICS = 'PASTE_LYRICS',
  DEFINE_SCENES = 'DEFINE_SCENES',
  PRODUCTION = 'PRODUCTION',
  PRESENTATION = 'PRESENTATION'
}

import { GoogleGenAI, Type } from "@google/genai";
import { StoryboardSegment, Character } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateSceneContent = async (
  lyrics: string, 
  context: string, 
  seed: string, 
  characters: Character[]
): Promise<Partial<StoryboardSegment>> => {
  const charContext = characters.length > 0 
    ? `CHARACTERS IN STORY: ${characters.map(c => c.name).join(', ')}.` 
    : '';

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `As a video director, provide visual instructions for this specific song segment.

    NARRATIVE ANGLE/DIRECTION: ${seed || "Cinematic and faithful to the lyrics"}
    ${charContext}

    CONTEXT: ${context}
    SEGMENT LYRICS: ${lyrics}`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.OBJECT,
        properties: {
          visuals: { type: Type.STRING, description: "Action happening in the scene. Use character names if applicable." },
          cameraWork: { type: Type.STRING, description: "Camera movement and angles" },
          lightingMood: { type: Type.STRING, description: "Lighting style and color palette" },
          sectionTitle: { type: Type.STRING, description: "Logical name (e.g. Verse 1)" }
        },
        required: ["visuals", "cameraWork", "lightingMood", "sectionTitle"]
      }
    }
  });

  const text = response.text;
  if (!text) throw new Error("No response from AI");
  return JSON.parse(text.trim());
};

export const generateDiagram = async (segment: StoryboardSegment): Promise<string> => {
  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Create a Mermaid.js flowchart representing the flow of the following film scene description. Use clean, professional syntax. Do not include markdown blocks.
    SCENE: ${segment.visuals}
    CAMERA: ${segment.cameraWork}`,
  });

  return response.text || '';
};

import React, { useState, useRef } from 'react';
import { Character } from '../types';

interface CharacterManagerProps {
  characters: Character[];
  onUpdate: (chars: Character[]) => void;
}

const CharacterManager: React.FC<CharacterManagerProps> = ({ characters, onUpdate }) => {
  const [newName, setNewName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);

  const addCharacter = (e: React.FormEvent) => {
    e.preventDefault();
    if (!newName.trim()) return;
    const char: Character = {
      id: `char-${Date.now()}`,
      name: newName.trim(),
    };
    onUpdate([...characters, char]);
    setNewName('');
  };

  const removeCharacter = (id: string) => {
    onUpdate(characters.filter(c => c.id !== id));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeCharId) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const dataUrl = event.target?.result as string;
      onUpdate(characters.map(c => 
        c.id === activeCharId ? { ...c, imageUrl: dataUrl } : c
      ));
      setActiveCharId(null);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const triggerUpload = (id: string) => {
    setActiveCharId(id);
    fileInputRef.current?.click();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
          Cast & Characters
        </label>
        <span className="text-[10px] text-slate-600 italic">Add names then upload reference images</span>
      </div>

      <form onSubmit={addCharacter} className="flex gap-2">
        <input
          type="text"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          placeholder="Type character name and press Enter..."
          className="flex-1 p-3 bg-slate-900/50 border border-slate-800 rounded-xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm transition-all"
        />
        <button 
          type="submit"
          className="px-4 py-2 bg-slate-800 text-slate-300 rounded-xl hover:bg-slate-700 transition-colors"
        >
          <i className="fa-solid fa-plus"></i>
        </button>
      </form>

      <div className="flex flex-wrap gap-3">
        {characters.map((char) => (
          <div 
            key={char.id}
            className="group relative flex items-center gap-3 bg-slate-800/40 border border-slate-700/50 p-2 pr-4 rounded-2xl hover:border-blue-500/30 transition-all"
          >
            <div 
              onClick={() => triggerUpload(char.id)}
              className="w-10 h-10 rounded-full bg-slate-900 border border-slate-700 overflow-hidden flex items-center justify-center cursor-pointer hover:border-blue-500 transition-colors group/img"
            >
              {char.imageUrl ? (
                <img src={char.imageUrl} alt={char.name} className="w-full h-full object-cover" />
              ) : (
                <i className="fa-solid fa-user-plus text-slate-600 group-hover/img:text-blue-500"></i>
              )}
            </div>

            <div className="flex flex-col">
              <span className="text-sm font-bold text-slate-200">{char.name}</span>
              <button 
                onClick={() => removeCharacter(char.id)}
                className="text-[10px] text-slate-500 hover:text-red-400 text-left transition-colors"
              >
                Remove
              </button>
            </div>
          </div>
        ))}

        {characters.length === 0 && (
          <div className="text-xs text-slate-600 italic py-2">No characters defined yet.</div>
        )}
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        className="hidden" 
      />
    </div>
  );
};

export default CharacterManager;

import React, { useState } from 'react';
import { StoryboardSegment, Character } from '../types';
import MermaidChart from './MermaidChart';
import { generateDiagram } from '../services/geminiService';

interface StoryboardCardProps {
  segment: StoryboardSegment;
  characters: Character[];
  onUpdate: (updated: StoryboardSegment) => void;
  onRemove?: () => void;
}

const StoryboardCard: React.FC<StoryboardCardProps> = ({ segment, characters, onUpdate, onRemove }) => {
  const [isGeneratingDiagram, setIsGeneratingDiagram] = useState(false);

  const handleChange = (field: keyof StoryboardSegment, value: string) => {
    onUpdate({ ...segment, [field]: value });
  };

  const handleBuildDiagram = async () => {
    setIsGeneratingDiagram(true);
    try {
      const diagram = await generateDiagram(segment);
      onUpdate({ ...segment, mermaidDiagram: diagram });
    } catch (err) {
      console.error(err);
    } finally {
      setIsGeneratingDiagram(false);
    }
  };

  const insertCharacter = (name: string) => {
    const field = 'visuals';
    handleChange(field, (segment.visuals || '') + ' ' + name);
  };

  return (
    <div className="group relative bg-slate-800/40 border border-slate-700/50 rounded-2xl overflow-hidden hover:border-blue-500/30 transition-all duration-300 backdrop-blur-sm shadow-xl mb-6">
      <div className="flex flex-col md:flex-row">
        {/* Left Side: Lyrics */}
        <div className="w-full md:w-1/3 p-6 border-b md:border-b-0 md:border-r border-slate-700/50 bg-slate-900/40">
          <div className="flex items-center justify-between mb-4">
            <input 
              value={segment.sectionTitle}
              onChange={(e) => handleChange('sectionTitle', e.target.value)}
              className="bg-blue-600/20 text-blue-400 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider outline-none border border-transparent focus:border-blue-500/50"
            />
            {onRemove && (
              <button onClick={onRemove} className="text-slate-600 hover:text-red-400 transition-colors">
                <i className="fa-solid fa-trash-can text-xs"></i>
              </button>
            )}
          </div>
          <p className="text-base font-medium leading-relaxed italic text-slate-300 whitespace-pre-wrap font-serif">
            {segment.lyrics}
          </p>
        </div>

        {/* Right Side: Editable Visuals */}
        <div className="w-full md:w-2/3 p-6 space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <i className="fa-solid fa-clapperboard"></i> Visual Content
                  </label>
                  {characters.length > 0 && (
                    <div className="flex gap-1 overflow-x-auto max-w-[150px] no-scrollbar">
                      {characters.map(c => (
                        <button 
                          key={c.id}
                          onClick={() => insertCharacter(c.name)}
                          className="text-[9px] bg-slate-900 border border-slate-700 text-slate-400 px-1.5 py-0.5 rounded hover:border-blue-500 hover:text-white transition-all whitespace-nowrap"
                          title={`Mention ${c.name}`}
                        >
                          @{c.name}
                        </button>
                      ))}
                    </div>
                  )}
                </div>
                <textarea 
                  value={segment.visuals}
                  onChange={(e) => handleChange('visuals', e.target.value)}
                  placeholder="Describe what we see... Tip: Use @names to mention characters."
                  className="w-full bg-slate-900/60 border border-slate-700/50 rounded-xl p-3 text-sm text-slate-200 outline-none focus:border-blue-500/50 h-32 resize-none"
                />
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
                    <i className="fa-solid fa-video"></i> Camera
                  </label>
                  <input 
                    value={segment.cameraWork}
                    onChange={(e) => handleChange('cameraWork', e.target.value)}
                    className="w-full bg-slate-900/60 border border-slate-700/50 rounded-lg p-2 text-xs text-slate-300 outline-none focus:border-blue-500/50"
                  />
                </div>
                <div>
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
                    <i className="fa-solid fa-lightbulb"></i> Lighting
                  </label>
                  <input 
                    value={segment.lightingMood}
                    onChange={(e) => handleChange('lightingMood', e.target.value)}
                    className="w-full bg-slate-900/60 border border-slate-700/50 rounded-lg p-2 text-xs text-slate-300 outline-none focus:border-blue-500/50"
                  />
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <i className="fa-solid fa-diagram-project"></i> Scene Architecture
                </label>
                <button 
                  onClick={handleBuildDiagram}
                  disabled={isGeneratingDiagram || !segment.visuals}
                  className="text-[10px] font-bold text-blue-400 hover:text-blue-300 uppercase tracking-wider flex items-center gap-1 disabled:opacity-50"
                >
                  {isGeneratingDiagram ? (
                    <><i className="fa-solid fa-spinner animate-spin"></i> Processing</>
                  ) : (
                    <><i className="fa-solid fa-bolt"></i> {segment.mermaidDiagram ? 'Update Chart' : 'Build Chart'}</>
                  )}
                </button>
              </div>
              {segment.mermaidDiagram ? (
                <div className="w-full max-h-[300px] overflow-auto bg-slate-900/50 rounded-xl scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
                  <MermaidChart chart={segment.mermaidDiagram} id={segment.id} />
                </div>
              ) : (
                <div className="h-32 bg-slate-900/30 border border-dashed border-slate-700/50 rounded-xl flex items-center justify-center text-slate-600 text-xs text-center p-4">
                  {segment.visuals ? 'Ready to generate architectural flow' : 'Enter visuals to enable diagramming'}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StoryboardCard;

import React, { useState, useMemo, useRef } from 'react';
import { generateSceneContent } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import PresentationView from './components/PresentationView';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [currentSceneIndex, setCurrentSceneIndex] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleStartDefining = (e: React.FormEvent) => {
    e.preventDefault();
    if (rawText.trim()) setStep(AppStep.DEFINE_SCENES);
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
      });
    }

    setSegments(newSegments);

    const populated = await Promise.all(newSegments.map(async (seg) => {
      try {
        const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
        return { ...seg, ...aiData };
      } catch (e) {
        return seg;
      }
    }));

    setSegments(populated);
    setIsBulkProcessing(false);
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const saveProject = () => {
    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments,
      characters,
      step,
      version: "1.0.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-project-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => {
    fileInputRef.current?.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText);
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);
        setStep(project.step === AppStep.PRESENTATION ? AppStep.PRODUCTION : project.step || AppStep.PASTE_LYRICS);
      } catch (err) {
        alert("Failed to load project file. Invalid format.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input
  };

  const startProductionMode = () => {
    setCurrentSceneIndex(0);
    setStep(AppStep.PRESENTATION);
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {step === AppStep.PRESENTATION && (
        <PresentationView 
          segments={segments}
          currentIndex={currentSceneIndex}
          onNext={() => setCurrentSceneIndex(p => Math.min(segments.length - 1, p + 1))}
          onPrev={() => setCurrentSceneIndex(p => Math.max(0, p - 1))}
          onExit={() => setStep(AppStep.PRODUCTION)}
        />
      )}

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-slate-800/50">
        <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20 cursor-pointer" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
              <i className="fa-solid fa-clapperboard text-white text-sm"></i>
            </div>
            <h1 className="text-lg font-bold tracking-tight">LyricLens Studio</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 mr-4">
              {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.PRODUCTION].map((s, idx) => (
                <React.Fragment key={s}>
                  <div className={`text-[10px] font-bold uppercase tracking-widest ${step === s ? 'text-blue-500' : 'text-slate-600'}`}>
                    {s.replace('_', ' ')}
                  </div>
                  {idx < 2 && <div className="w-4 h-[1px] bg-slate-800"></div>}
                </React.Fragment>
              ))}
            </div>

            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={loadProject} 
              accept=".json" 
              className="hidden" 
            />

            <div className="flex items-center gap-2 border-l border-slate-800 pl-4">
              <button 
                onClick={handleLoadClick}
                className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold"
                title="Load Project"
              >
                <i className="fa-solid fa-folder-open"></i> Load
              </button>
              <button 
                onClick={saveProject}
                className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold"
                title="Save Project"
              >
                <i className="fa-solid fa-floppy-disk"></i> Save
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 py-12">
        {step === AppStep.PASTE_LYRICS && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-white mb-3 tracking-tight">Directing Desk</h2>
              <p className="text-slate-400">Set the stage, define your cast, and paste your source text.</p>
            </div>
            <form onSubmit={handleStartDefining} className="space-y-10">
              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
                  Narrative Seed / Angle
                </label>
                <input
                  type="text"
                  value={narrativeSeed}
                  onChange={(e) => setNarrativeSeed(e.target.value)}
                  placeholder="e.g. A dystopian future with neon lighting, melancholy mood, focus on shadows"
                  className="w-full p-4 bg-slate-900/50 border border-slate-800 rounded-2xl focus:ring-1 focus:ring-blue-500/50 focus:border-blue-500/50 outline-none text-sm transition-all shadow-inner"
                />
              </div>

              <CharacterManager 
                characters={characters} 
                onUpdate={setCharacters} 
              />

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
                  Lyrics / Script
                </label>
                <textarea
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  placeholder="Paste lyrics or narrative text here..."
                  className="w-full h-80 p-6 bg-slate-900/50 border border-slate-800 rounded-3xl focus:ring-1 focus:ring-blue-500/50 outline-none text-lg transition-all resize-none font-serif shadow-inner"
                />
              </div>

              <button
                type="submit"
                disabled={!rawText.trim()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-3"
              >
                Proceed to Scene Layout
              </button>
            </form>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-xl mx-auto">
            <div className="text-center mb-8">
              <h2 className="text-2xl font-bold text-white mb-2">Identify Scene Breaks</h2>
              <p className="text-sm text-slate-400">Click the spaces between lines to define start points for new visuals.</p>
            </div>

            <div className="space-y-1 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50 shadow-inner">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button 
                      onClick={() => toggleMarker(idx)}
                      className={`w-full group relative py-2 transition-all flex items-center justify-center`}
                    >
                      <div className={`h-[2px] transition-all ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'w-1/4 bg-slate-800 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                      {sceneMarkers.includes(idx) && (
                        <div className="absolute bg-blue-500 text-[8px] font-black text-white px-2 py-0.5 rounded uppercase tracking-tighter">New Scene</div>
                      )}
                    </button>
                  )}
                  <div className={`text-center py-1 font-serif text-slate-300 transition-colors ${sceneMarkers.includes(idx) ? 'pt-4 text-white font-semibold' : ''}`}>
                    {line}
                  </div>
                </React.Fragment>
              ))}
            </div>

            <div className="mt-10 flex gap-4">
              <button
                onClick={() => setStep(AppStep.PASTE_LYRICS)}
                className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-2xl font-bold transition-all"
              >
                Back
              </button>
              <button
                onClick={handleProceedToProduction}
                className="flex-[2] py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all"
              >
                Generate Pre-Production Draft
              </button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4">
              <div className="space-y-1">
                <h2 className="text-3xl font-bold text-white mb-1">Director's Board</h2>
                <div className="flex flex-wrap gap-2">
                   <p className="text-slate-400 text-xs">
                    Angle: <span className="text-blue-400 italic">"{narrativeSeed || 'Standard Cinematic'}"</span>
                  </p>
                  {characters.length > 0 && (
                    <div className="flex gap-2 border-l border-slate-800 pl-2">
                      {characters.map(c => (
                        <span key={c.id} className="text-[10px] text-slate-500 border border-slate-800 px-1.5 rounded">@{c.name}</span>
                      ))}
                    </div>
                  )}
                </div>
              </div>
              <div className="flex items-center gap-3">
                {isBulkProcessing && (
                  <div className="flex items-center gap-2 text-blue-400 font-bold text-xs uppercase tracking-widest animate-pulse mr-4">
                    <i className="fa-solid fa-spinner animate-spin"></i>
                    Drafting Script...
                  </div>
                )}
                <button 
                  onClick={saveProject}
                  className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold text-xs flex items-center gap-2 transition-all"
                >
                  <i className="fa-solid fa-floppy-disk"></i> Save Changes
                </button>
              </div>
            </div>

            <div className="space-y-2">
              {segments.map((seg, idx) => (
                <StoryboardCard 
                  key={seg.id} 
                  segment={seg} 
                  characters={characters}
                  onUpdate={(updated) => updateSegment(idx, updated)}
                />
              ))}
            </div>

            <div className="mt-12 pt-8 border-t border-slate-800 flex justify-center gap-6">
               <button onClick={saveProject} className="px-6 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl font-bold flex items-center gap-2 transition-all">
                  <i className="fa-solid fa-download"></i> Download Bundle
               </button>
               <button 
                onClick={startProductionMode}
                className="px-6 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20 transition-all"
               >
                  <i className="fa-solid fa-play"></i> Production Mode
               </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

export interface Character {
  id: string;
  name: string;
  imageUrl?: string;
}

export interface StoryboardSegment {
  id: string;
  sectionTitle: string;
  lyrics: string;
  visuals: string;
  cameraWork: string;
  lightingMood: string;
  mermaidDiagram?: string;
  isProcessing?: boolean;
  characters?: string[]; // IDs or names of characters present in this scene
}

export interface StoryboardProject {
  rawText: string;
  narrativeSeed: string;
  sceneMarkers: number[];
  segments: StoryboardSegment[];
  characters: Character[];
  step: AppStep;
  version: string;
}

export enum AppStep {
  PASTE_LYRICS = 'PASTE_LYRICS',
  DEFINE_SCENES = 'DEFINE_SCENES',
  PRODUCTION = 'PRODUCTION',
  PRESENTATION = 'PRESENTATION'
}

import React, { useEffect, useState } from 'react';
import { StoryboardSegment, Character } from '../types';
import MermaidChart from './MermaidChart';
import { generateSceneContent, generateDiagram } from '../services/geminiService';

interface PresentationViewProps {
  segments: StoryboardSegment[];
  characters: Character[];
  currentIndex: number;
  onUpdateSegment: (index: number, updated: StoryboardSegment) => void;
  onNext: () => void;
  onPrev: () => void;
  onExit: () => void;
  narrativeSeed: string;
}

const PresentationView: React.FC<PresentationViewProps> = ({ 
  segments, 
  characters,
  currentIndex, 
  onUpdateSegment,
  onNext, 
  onPrev, 
  onExit,
  narrativeSeed
}) => {
  const current = segments[currentIndex];
  const [isRegenerating, setIsRegenerating] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.key === 'ArrowRight' || e.key === ' ') && (e.target as HTMLElement).tagName !== 'TEXTAREA' && (e.target as HTMLElement).tagName !== 'INPUT') {
        onNext();
      }
      if (e.key === 'ArrowLeft' && (e.target as HTMLElement).tagName !== 'TEXTAREA' && (e.target as HTMLElement).tagName !== 'INPUT') {
        onPrev();
      }
      if (e.key === 'Escape') onExit();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onNext, onPrev, onExit]);

  const handleFieldChange = (field: keyof StoryboardSegment, value: string) => {
    onUpdateSegment(currentIndex, { ...current, [field]: value });
  };

  const handleRegenerate = async () => {
    setIsRegenerating(true);
    try {
      const aiData = await generateSceneContent(current.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
      const updated = { ...current, ...aiData };
      // Also update diagram to match new visuals
      const newDiagram = await generateDiagram(updated as StoryboardSegment);
      onUpdateSegment(currentIndex, { ...updated, mermaidDiagram: newDiagram });
    } catch (err) {
      console.error("Failed to regenerate scene:", err);
    } finally {
      setIsRegenerating(false);
    }
  };

  if (!current) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black text-white flex flex-col animate-in fade-in duration-500 overflow-hidden">
      {/* Header HUD */}
      <div className="p-4 flex justify-between items-center bg-zinc-900/80 border-b border-white/5">
        <div className="flex items-center gap-4">
          <button 
            onClick={onExit}
            className="w-8 h-8 rounded-lg bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors border border-white/10"
          >
            <i className="fa-solid fa-chevron-left text-xs"></i>
          </button>
          <div>
            <input 
              value={current.sectionTitle}
              onChange={(e) => handleFieldChange('sectionTitle', e.target.value)}
              className="bg-transparent border-none focus:ring-0 text-sm font-bold text-blue-500 uppercase tracking-widest p-0 w-48"
            />
            <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Production Mode • Scene {currentIndex + 1} of {segments.length}</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
           <button 
             onClick={handleRegenerate}
             disabled={isRegenerating}
             className="text-[10px] font-bold text-blue-400 hover:text-blue-300 uppercase tracking-widest flex items-center gap-2 px-3 py-1.5 bg-blue-500/10 rounded-md border border-blue-500/20 disabled:opacity-50"
           >
             <i className={`fa-solid fa-wand-magic-sparkles ${isRegenerating ? 'animate-spin' : ''}`}></i>
             {isRegenerating ? 'Recreating...' : 'Recreate Scene'}
           </button>
           <div className="flex h-1 gap-1 w-24 bg-white/10 rounded-full overflow-hidden">
              {segments.map((_, i) => (
                <div key={i} className={`flex-1 ${i <= currentIndex ? 'bg-blue-500' : 'bg-transparent'}`}></div>
              ))}
           </div>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col md:flex-row p-6 md:p-8 gap-8 min-h-0">
        {/* Left Side: Editorial */}
        <div className="w-full md:w-[45%] flex flex-col gap-6 overflow-y-auto pr-2 custom-scrollbar">
          <div className="space-y-3">
             <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.3em]">Lyrics</span>
             <blockquote className="text-2xl md:text-3xl font-serif italic text-slate-100 leading-snug bg-zinc-900/40 p-6 rounded-2xl border border-white/5">
               "{current.lyrics}"
             </blockquote>
          </div>

          <div className="space-y-6 pt-2 border-t border-white/10">
            <div>
               <h4 className="text-[10px] font-bold text-blue-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                 <i className="fa-solid fa-clapperboard"></i> Action & Visuals
               </h4>
               <textarea 
                  value={current.visuals}
                  onChange={(e) => handleFieldChange('visuals', e.target.value)}
                  className="w-full bg-zinc-900 border border-white/10 rounded-xl p-4 text-base text-slate-300 leading-relaxed outline-none focus:border-blue-500/50 min-h-[160px] resize-none"
                  placeholder="Describe the action..."
               />
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div>
                <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
                  <i className="fa-solid fa-video"></i> Camera
                </h4>
                <input 
                  value={current.cameraWork}
                  onChange={(e) => handleFieldChange('cameraWork', e.target.value)}
                  className="w-full bg-zinc-900 border border-white/10 rounded-lg p-3 text-sm font-medium text-slate-300 outline-none focus:border-blue-500/50"
                />
              </div>
              <div>
                <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 flex items-center gap-2">
                  <i className="fa-solid fa-lightbulb"></i> Lighting
                </h4>
                <input 
                  value={current.lightingMood}
                  onChange={(e) => handleFieldChange('lightingMood', e.target.value)}
                  className="w-full bg-zinc-900 border border-white/10 rounded-lg p-3 text-sm font-medium text-slate-300 outline-none focus:border-blue-500/50"
                />
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Architecture (Autonomous Scrollable Frame) */}
        <div className="flex-1 flex flex-col bg-zinc-900/60 rounded-3xl border border-white/5 shadow-2xl overflow-hidden">
          <div className="p-4 border-b border-white/5 flex justify-between items-center shrink-0">
             <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Scene Architecture Map</h4>
             <button 
              onClick={async () => {
                const diag = await generateDiagram(current);
                handleFieldChange('mermaidDiagram', diag);
              }}
              className="text-[10px] text-blue-400 hover:underline"
             >
               Refresh Diagram
             </button>
          </div>
          <div className="flex-1 overflow-auto p-8 flex items-start justify-center custom-scrollbar">
            {current.mermaidDiagram ? (
              <div className="w-full">
                <MermaidChart chart={current.mermaidDiagram} id={`pres-${current.id}`} />
              </div>
            ) : (
              <div className="self-center flex flex-col items-center gap-4 text-slate-600">
                <i className="fa-solid fa-diagram-project text-4xl opacity-20"></i>
                <p className="italic text-sm">Diagram pending reconstruction</p>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Footer Controls */}
      <div className="p-4 flex justify-between items-center bg-zinc-900 border-t border-white/5 shrink-0">
        <button 
          onClick={onPrev}
          disabled={currentIndex === 0}
          className="group flex items-center gap-3 px-6 py-2 rounded-xl bg-white/5 hover:bg-white/10 disabled:opacity-20 transition-all border border-white/5"
        >
          <i className="fa-solid fa-arrow-left text-xs group-hover:-translate-x-1 transition-transform"></i>
          <span className="text-xs font-bold uppercase tracking-widest">Prev</span>
        </button>

        <div className="text-[10px] text-slate-600 font-mono tracking-widest">
          SYSTEM_VERSION: PRODUCTION_STABLE
        </div>

        <button 
          onClick={onNext}
          disabled={currentIndex === segments.length - 1}
          className="group flex items-center gap-3 px-6 py-2 rounded-xl bg-blue-600 hover:bg-blue-500 disabled:opacity-20 transition-all shadow-lg shadow-blue-500/10"
        >
          <span className="text-xs font-bold uppercase tracking-widest text-white">Next Scene</span>
          <i className="fa-solid fa-arrow-right text-xs text-white group-hover:translate-x-1 transition-transform"></i>
        </button>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 6px;
          height: 6px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: rgba(255, 255, 255, 0.02);
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: rgba(255, 255, 255, 0.1);
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: rgba(255, 255, 255, 0.2);
        }
      `}</style>
    </div>
  );
};

export default PresentationView;

import React, { useState, useMemo, useRef } from 'react';
import { generateSceneContent } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import PresentationView from './components/PresentationView';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [currentSceneIndex, setCurrentSceneIndex] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleStartDefining = (e: React.FormEvent) => {
    e.preventDefault();
    if (rawText.trim()) setStep(AppStep.DEFINE_SCENES);
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);

    const populated = await Promise.all(newSegments.map(async (seg) => {
      try {
        const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
        return { ...seg, ...aiData };
      } catch (e) {
        return seg;
      }
    }));

    setSegments(populated);
    setIsBulkProcessing(false);
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const extractCharactersFromText = (text: string) => {
    return characters
      .filter(char => text.toLowerCase().includes(char.name.toLowerCase()))
      .map(char => char.name);
  };

  const saveProject = () => {
    // Before saving, ensure segments have identified characters from their current visuals
    const updatedSegments = segments.map(seg => ({
      ...seg,
      characters: extractCharactersFromText(seg.visuals)
    }));

    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments: updatedSegments,
      characters,
      step,
      version: "1.1.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-project-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => {
    fileInputRef.current?.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText);
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);

        // Always go to the step defined in file, but ensure they can still edit characters if they need
        setStep(project.step === AppStep.PRESENTATION ? AppStep.PRODUCTION : project.step || AppStep.PASTE_LYRICS);
      } catch (err) {
        alert("Failed to load project file. Invalid format.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input
  };

  const startProductionMode = () => {
    setCurrentSceneIndex(0);
    setStep(AppStep.PRESENTATION);
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {step === AppStep.PRESENTATION && (
        <PresentationView 
          segments={segments}
          characters={characters}
          currentIndex={currentSceneIndex}
          onUpdateSegment={updateSegment}
          onNext={() => setCurrentSceneIndex(p => Math.min(segments.length - 1, p + 1))}
          onPrev={() => setCurrentSceneIndex(p => Math.max(0, p - 1))}
          onExit={() => setStep(AppStep.PRODUCTION)}
          narrativeSeed={narrativeSeed}
        />
      )}

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-slate-800/50">
        <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20 cursor-pointer" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
              <i className="fa-solid fa-clapperboard text-white text-sm"></i>
            </div>
            <h1 className="text-lg font-bold tracking-tight">LyricLens Studio</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 mr-4">
              {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.PRODUCTION].map((s, idx) => (
                <React.Fragment key={s}>
                  <div 
                    className={`text-[10px] font-bold uppercase tracking-widest cursor-pointer ${step === s ? 'text-blue-500' : 'text-slate-600'}`}
                    onClick={() => setStep(s)}
                  >
                    {s.replace('_', ' ')}
                  </div>
                  {idx < 2 && <div className="w-4 h-[1px] bg-slate-800"></div>}
                </React.Fragment>
              ))}
            </div>

            <input 
              type="file" 
              ref={fileInputRef} 
              onChange={loadProject} 
              accept=".json" 
              className="hidden" 
            />

            <div className="flex items-center gap-2 border-l border-slate-800 pl-4">
              <button 
                onClick={handleLoadClick}
                className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold"
                title="Load Project"
              >
                <i className="fa-solid fa-folder-open"></i> Load
              </button>
              <button 
                onClick={saveProject}
                className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold"
                title="Save Project"
              >
                <i className="fa-solid fa-floppy-disk"></i> Save
              </button>
            </div>
          </div>
        </div>
      </header>

      <main className="max-w-5xl mx-auto px-6 py-12">
        {/* We allow character modifications even if we are in PRODUCTION or DEFINE_SCENES by going back to step 1 */}
        {step === AppStep.PASTE_LYRICS && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-2xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-white mb-3 tracking-tight">Directing Desk</h2>
              <p className="text-slate-400">Set the stage, define your cast, and paste your source text.</p>
            </div>
            <form onSubmit={handleStartDefining} className="space-y-10">
              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
                  Narrative Seed / Angle
                </label>
                <input
                  type="text"
                  value={narrativeSeed}
                  onChange={(e) => setNarrativeSeed(e.target.value)}
                  placeholder="e.g. A dystopian future with neon lighting, melancholy mood, focus on shadows"
                  className="w-full p-4 bg-slate-900/50 border border-slate-800 rounded-2xl focus:ring-1 focus:ring-blue-500/50 focus:border-blue-500/50 outline-none text-sm transition-all shadow-inner"
                />
              </div>

              <CharacterManager 
                characters={characters} 
                onUpdate={setCharacters} 
              />

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
                  Lyrics / Script
                </label>
                <textarea
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  placeholder="Paste lyrics or narrative text here..."
                  className="w-full h-80 p-6 bg-slate-900/50 border border-slate-800 rounded-3xl focus:ring-1 focus:ring-blue-500/50 outline-none text-lg transition-all resize-none font-serif shadow-inner"
                />
              </div>

              <button
                type="submit"
                disabled={!rawText.trim()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all flex items-center justify-center gap-3"
              >
                Proceed to Scene Layout
              </button>
            </form>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-xl mx-auto">
            <div className="text-center mb-8">
              <h2 className="text-2xl font-bold text-white mb-2">Identify Scene Breaks</h2>
              <p className="text-sm text-slate-400">Click the spaces between lines to define start points for new visuals.</p>
            </div>

            <div className="space-y-1 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50 shadow-inner">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button 
                      onClick={() => toggleMarker(idx)}
                      className={`w-full group relative py-2 transition-all flex items-center justify-center`}
                    >
                      <div className={`h-[2px] transition-all ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'w-1/4 bg-slate-800 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                      {sceneMarkers.includes(idx) && (
                        <div className="absolute bg-blue-500 text-[8px] font-black text-white px-2 py-0.5 rounded uppercase tracking-tighter">New Scene</div>
                      )}
                    </button>
                  )}
                  <div className={`text-center py-1 font-serif text-slate-300 transition-colors ${sceneMarkers.includes(idx) ? 'pt-4 text-white font-semibold' : ''}`}>
                    {line}
                  </div>
                </React.Fragment>
              ))}
            </div>

            <div className="mt-10 flex gap-4">
              <button
                onClick={() => setStep(AppStep.PASTE_LYRICS)}
                className="flex-1 py-4 bg-slate-800 hover:bg-slate-700 text-slate-300 rounded-2xl font-bold transition-all"
              >
                Back
              </button>
              <button
                onClick={handleProceedToProduction}
                className="flex-[2] py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-bold shadow-xl shadow-blue-600/20 transition-all"
              >
                Generate Pre-Production Draft
              </button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-8 gap-4">
              <div className="space-y-1">
                <h2 className="text-3xl font-bold text-white mb-1">Director's Board</h2>
                <div className="flex flex-wrap gap-2">
                   <p className="text-slate-400 text-xs">
                    Angle: <span className="text-blue-400 italic">"{narrativeSeed || 'Standard Cinematic'}"</span>
                  </p>
                  {characters.length > 0 && (
                    <div className="flex gap-2 border-l border-slate-800 pl-2">
                      {characters.map(c => (
                        <span key={c.id} className="text-[10px] text-slate-500 border border-slate-800 px-1.5 rounded">@{c.name}</span>
                      ))}
                    </div>
                  )}
                  {/* Allow adding characters even here */}
                  <button 
                    onClick={() => setStep(AppStep.PASTE_LYRICS)}
                    className="text-[10px] text-blue-500 hover:underline"
                  >
                    Edit Cast
                  </button>
                </div>
              </div>
              <div className="flex items-center gap-3">
                {isBulkProcessing && (
                  <div className="flex items-center gap-2 text-blue-400 font-bold text-xs uppercase tracking-widest animate-pulse mr-4">
                    <i className="fa-solid fa-spinner animate-spin"></i>
                    Drafting Script...
                  </div>
                )}
                <button 
                  onClick={saveProject}
                  className="px-4 py-2 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold text-xs flex items-center gap-2 transition-all"
                >
                  <i className="fa-solid fa-floppy-disk"></i> Save Changes
                </button>
              </div>
            </div>

            <div className="space-y-2">
              {segments.map((seg, idx) => (
                <StoryboardCard 
                  key={seg.id} 
                  segment={seg} 
                  characters={characters}
                  onUpdate={(updated) => updateSegment(idx, updated)}
                />
              ))}
            </div>

            <div className="mt-12 pt-8 border-t border-slate-800 flex justify-center gap-6">
               <button onClick={saveProject} className="px-6 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl font-bold flex items-center gap-2 transition-all">
                  <i className="fa-solid fa-download"></i> Download Bundle
               </button>
               <button 
                onClick={startProductionMode}
                className="px-6 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20 transition-all"
               >
                  <i className="fa-solid fa-play"></i> Production Mode
               </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useRef } from 'react';
import { Character } from '../types';

interface CharacterManagerProps {
  characters: Character[];
  onUpdate: (chars: Character[]) => void;
}

const CharacterManager: React.FC<CharacterManagerProps> = ({ characters = [], onUpdate }) => {
  const [newName, setNewName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);

  const handleAddCharacter = () => {
    if (!newName.trim()) return;
    const char: Character = {
      id: `char-${Date.now()}`,
      name: newName.trim(),
    };
    onUpdate([...characters, char]);
    setNewName('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddCharacter();
    }
  };

  const removeCharacter = (id: string) => {
    onUpdate(characters.filter(c => c.id !== id));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !activeCharId) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      const dataUrl = event.target?.result as string;
      onUpdate(characters.map(c => 
        c.id === activeCharId ? { ...c, imageUrl: dataUrl } : c
      ));
      setActiveCharId(null);
    };
    reader.readAsDataURL(file);
    e.target.value = '';
  };

  const triggerUpload = (id: string) => {
    setActiveCharId(id);
    fileInputRef.current?.click();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
          Cast & Characters
        </label>
        <span className="text-[10px] text-slate-600 italic">Add names then upload reference images</span>
      </div>

      <div className="flex gap-2">
        <input
          type="text"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Type character name and press Enter..."
          className="flex-1 p-3 bg-slate-900/50 border border-slate-800 rounded-xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm transition-all text-white"
        />
        <button 
          type="button"
          onClick={handleAddCharacter}
          className="px-4 py-2 bg-slate-800 text-slate-300 rounded-xl hover:bg-slate-700 transition-colors"
        >
          <i className="fa-solid fa-plus"></i>
        </button>
      </div>

      <div className="flex flex-wrap gap-3">
        {(characters || []).map((char) => (
          <div 
            key={char.id}
            className="group relative flex items-center gap-3 bg-slate-800/40 border border-slate-700/50 p-2 pr-4 rounded-2xl hover:border-blue-500/30 transition-all"
          >
            <div 
              onClick={() => triggerUpload(char.id)}
              className="w-10 h-10 rounded-full bg-slate-900 border border-slate-700 overflow-hidden flex items-center justify-center cursor-pointer hover:border-blue-500 transition-colors group/img"
            >
              {char.imageUrl ? (
                <img src={char.imageUrl} alt={char.name} className="w-full h-full object-cover" />
              ) : (
                <i className="fa-solid fa-user-plus text-slate-600 group-hover/img:text-blue-500"></i>
              )}
            </div>

            <div className="flex flex-col">
              <span className="text-sm font-bold text-slate-200">{char.name}</span>
              <button 
                type="button"
                onClick={() => removeCharacter(char.id)}
                className="text-[10px] text-slate-500 hover:text-red-400 text-left transition-colors"
              >
                Remove
              </button>
            </div>
          </div>
        ))}

        {(!characters || characters.length === 0) && (
          <div className="text-xs text-slate-600 italic py-2">No characters defined yet.</div>
        )}
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        className="hidden" 
      />
    </div>
  );
};

export default CharacterManager;

import React, { useState, useMemo, useRef } from 'react';
import { generateSceneContent } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import PresentationView from './components/PresentationView';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [currentSceneIndex, setCurrentSceneIndex] = useState(0);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleStartDefining = (e: React.FormEvent) => {
    e.preventDefault();
    if (rawText.trim()) setStep(AppStep.DEFINE_SCENES);
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);

    const populated = await Promise.all(newSegments.map(async (seg) => {
      try {
        const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
        return { ...seg, ...aiData };
      } catch (e) {
        return seg;
      }
    }));

    setSegments(populated);
    setIsBulkProcessing(false);
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const extractCharactersFromText = (text: string) => {
    return characters
      .filter(char => {
        const regex = new RegExp(`\\b${char.name}\\b`, 'i');
        return regex.test(text);
      })
      .map(char => char.name);
  };

  const saveProject = () => {
    // Before saving, update segments with detected characters
    const updatedSegments = segments.map(seg => ({
      ...seg,
      characters: extractCharactersFromText(seg.visuals)
    }));

    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments: updatedSegments,
      characters: characters || [],
      step,
      version: "1.1.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-project-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => {
    fileInputRef.current?.click();
  };

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText || '');
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);

        // Go to Step 1 if characters are missing but we want them, otherwise stick to production
        setStep(project.step === AppStep.PRESENTATION ? AppStep.PRODUCTION : project.step || AppStep.PASTE_LYRICS);
      } catch (err) {
        alert("Failed to load project file. Invalid format.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; // Reset input
  };

  const startProductionMode = () => {
    setCurrentSceneIndex(0);
    setStep(AppStep.PRESENTATION);
  };

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {step === AppStep.PRESENTATION && (
        <PresentationView 
          segments={segments}
          characters={characters}
          currentIndex={currentSceneIndex}
          onUpdateSegment={updateSegment}
          onNext={() => setCurrentSceneIndex(p => Math.min(segments.length - 1, p + 1))}
          onPrev={() => setCurrentSceneIndex(p => Math.max(0, p - 1))}
          onExit={() => setStep(AppStep.PRODUCTION)}
          narrativeSeed={narrativeSeed}
        />
      )}

