                />
              </div>

              <CharacterManager 
                characters={characters || []} 
                onUpdate={setCharacters} 
              />

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
                  Lyrics / Script
                </label>
                <textarea
                  value={rawText}
