                  placeholder="Paste lyrics or narrative text here..."
                  className="w-full h-80 p-6 bg-slate-900/50 border border-slate-800 rounded-3xl focus:ring-1 focus:ring-blue-500/50 outline-none text-lg transition-all resize-none font-serif shadow-inner text-white"
                />
              </div>

              <button
                type="button"
                onClick={() => rawText.trim() && setStep(AppStep.DEFINE_SCENES)}
