            <div className="space-y-2">
              {segments.map((seg, idx) => (
                <StoryboardCard 
                  key={seg.id} 
                  segment={seg} 
                  characters={characters}
                  onUpdate={(updated) => updateSegment(idx, updated)}
                />
              ))}
            </div>

            <div className="mt-12 pt-8 border-t border-slate-800 flex justify-center gap-6">
               <button onClick={saveProject} className="px-6 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl font-bold flex items-center gap-2 transition-all text-sm">
                  <i className="fa-solid fa-download"></i> Download JSON
               </button>
               <button 
                onClick={startProductionMode}
                className="px-6 py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-bold flex items-center gap-2 shadow-lg shadow-blue-600/20 transition-all text-sm"
               >
                  <i className="fa-solid fa-play"></i> Production Mode
               </button>
            </div>
          </div>
        )}
      </main>
    </div>
  );
};

