            <div className="mt-10 flex gap-4">
              <button onClick={() => setStep(AppStep.PASTE_LYRICS)} className="flex-1 py-4 bg-slate-800 text-slate-300 rounded-2xl font-bold">Back</button>
              <button onClick={handleProceedToProduction} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-bold">Generate Pre-Production Draft</button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            {isCharModalOpen && (
              <div className="fixed inset-0 z-[150] bg-black/80 backdrop-blur-sm flex items-center justify-center p-6">
                <div className="bg-slate-900 border border-slate-800 w-full max-w-2xl rounded-3xl p-8 shadow-2xl space-y-6">
                  <div className="flex justify-between items-center"><h3 className="text-xl font-bold text-white">Edit Production Cast</h3><button onClick={() => setIsCharModalOpen(false)} className="text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
                  <CharacterManager characters={characters} onUpdate={setCharacters} />
                  <div className="pt-4 flex justify-end"><button onClick={() => setIsCharModalOpen(false)} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold">Apply Changes</button></div>
                </div>
              </div>
            )}
            <div className="flex justify-between items-end mb-8">
              <div>
                <h2 className="text-3xl font-bold text-white mb-1">Director's Board</h2>
                <div className="flex gap-4">
                  <button onClick={() => setIsCharModalOpen(true)} className="text-[10px] text-blue-500 hover:underline">Edit Cast</button>
                  <button onClick={saveProject} className="text-[10px] text-slate-500 hover:text-white transition-colors"><i className="fa-solid fa-cloud-arrow-up mr-1"></i> Stage Save</button>
                </div>
              </div>
              <button onClick={() => setStep(AppStep.RESOURCES)} className="px-6 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg shadow-blue-600/20">Finalize Resources <i className="fa-solid fa-arrow-right ml-2"></i></button>
            </div>
            <div className="space-y-4">
              {segments.map((seg, idx) => (
                <StoryboardCard key={seg.id} segment={seg} characters={characters} onUpdate={(updated) => updateSegment(idx, updated)} />
              ))}
            </div>
          </div>
        )}

        {step === AppStep.RESOURCES && (
          <div className="animate-in fade-in duration-700 max-w-4xl mx-auto">
             <div className="text-center mb-12">
               <h2 className="text-3xl font-bold text-white mb-2">Resource Gallery</h2>
               <p className="text-slate-400">Upload or refine character visual references for the final production package.</p>
             </div>

             <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6">
               {characters.map(char => (
                 <div key={char.id} className="bg-slate-800/40 border border-slate-700/50 rounded-3xl p-6 flex flex-col items-center gap-6 group hover:border-blue-500/50 transition-all">
                    <div className="w-full aspect-square rounded-2xl bg-slate-900 border border-slate-700 flex items-center justify-center overflow-hidden relative group/img cursor-pointer">
                       {char.imageUrl ? (
                         <>
                           <img src={char.imageUrl} alt={char.name} className="w-full h-full object-cover group-hover/img:scale-105 transition-transform duration-500" />
                           <div className="absolute inset-0 bg-black/60 opacity-0 group-hover/img:opacity-100 flex flex-col items-center justify-center transition-opacity">
                              <i className="fa-solid fa-camera-rotate text-2xl text-white mb-2"></i>
                              <span className="text-[10px] text-white font-bold uppercase tracking-widest">Update Reference</span>
                           </div>
                         </>
                       ) : (
                         <div className="flex flex-col items-center justify-center text-slate-700 group-hover/img:text-blue-500 transition-colors">
                           <i className="fa-solid fa-user-plus text-5xl mb-4"></i>
                           <p className="text-[10px] font-bold uppercase tracking-widest">Add Reference</p>
                         </div>
                       )}
                       <input 
                         type="file" 
                         accept="image/*"
                         className="absolute inset-0 opacity-0 cursor-pointer"
                         onChange={(e) => {
                           const file = e.target.files?.[0];
                           if (file) {
                             const reader = new FileReader();
                             reader.onload = (ev) => setCharacters(prev => prev.map(c => c.id === char.id ? {...c, imageUrl: ev.target?.result as string} : c));
                             reader.readAsDataURL(file);
                           }
                         }}
                       />
                    </div>
                    <div className="text-center w-full">
                       <h3 className="text-xl font-bold text-white mb-1 group-hover:text-blue-400 transition-colors">{char.name}</h3>
                       <div className="h-0.5 w-12 bg-blue-600/30 mx-auto rounded-full mb-3"></div>
                       <p className="text-[10px] text-slate-500 uppercase tracking-widest font-mono">ID: {char.id.split('-')[1]}</p>
                    </div>
                 </div>
               ))}
               {characters.length === 0 && (
                 <div className="col-span-full text-center py-20 bg-slate-900/30 rounded-3xl border border-dashed border-slate-800">
                   <p className="text-slate-500 italic">No characters defined. Return to Directing Desk to add cast.</p>
                   <button onClick={() => setStep(AppStep.PASTE_LYRICS)} className="mt-4 text-blue-500 text-sm hover:underline">Add Characters</button>
                 </div>
               )}
             </div>

             <div className="mt-16 flex flex-col items-center gap-8">
                <div className="flex justify-center gap-6 w-full">
                  <button onClick={() => setStep(AppStep.PRODUCTION)} className="px-8 py-4 bg-slate-800 text-slate-300 rounded-2xl font-bold flex items-center gap-3 transition-colors hover:bg-slate-700"><i className="fa-solid fa-chevron-left"></i> Storyboard</button>
                  <button onClick={saveProject} className="px-10 py-4 bg-white text-slate-900 rounded-2xl font-bold flex items-center gap-3 shadow-xl transition-all hover:bg-slate-100 hover:scale-[1.02]"><i className="fa-solid fa-cube"></i> Bounce Full Package</button>
                  <button onClick={() => { setCurrentSceneIndex(0); setStep(AppStep.PRESENTATION); }} className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-bold flex items-center gap-3 shadow-xl shadow-blue-600/20 transition-all hover:bg-blue-500 hover:scale-[1.02]"><i className="fa-solid fa-play"></i> Start Presentation</button>
                </div>
                <div className="text-center">
                  <p className="text-[10px] text-slate-500 uppercase tracking-[0.4em] font-bold">End of Pre-Production</p>
                </div>
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { StoryboardSegment, Character } from '../types';
import MermaidChart from './MermaidChart';
import { generateDiagram } from '../services/geminiService';

interface StoryboardCardProps {
  segment: StoryboardSegment;
  characters: Character[];
  onUpdate: (updated: StoryboardSegment) => void;
  onRemove?: () => void;
}

const StoryboardCard: React.FC<StoryboardCardProps> = ({ segment, characters, onUpdate, onRemove }) => {
  const [isGeneratingDiagram, setIsGeneratingDiagram] = useState(false);

  const handleChange = (field: keyof StoryboardSegment, value: string) => {
    onUpdate({ ...segment, [field]: value });
  };

  const combinedText = useMemo(() => {
    return (segment.visuals + ' ' + segment.cameraWork + ' ' + segment.lightingMood).toLowerCase();
  }, [segment.visuals, segment.cameraWork, segment.lightingMood]);

  const handleBuildDiagram = async () => {
    setIsGeneratingDiagram(true);
    try {
      const diagram = await generateDiagram(segment);
      onUpdate({ ...segment, mermaidDiagram: diagram });
    } catch (err) {
      console.error(err);
    } finally {
      setIsGeneratingDiagram(false);
    }
  };

  const insertCharacter = (field: keyof StoryboardSegment, name: string) => {
    const currentValue = (segment[field] as string) || '';
    const newValue = currentValue.endsWith(' ') || currentValue === '' ? currentValue + name : currentValue + ' ' + name;
    handleChange(field, newValue);
  };

  const CharacterShortcuts = ({ field }: { field: keyof StoryboardSegment }) => {
    if (!characters || characters.length === 0) return null;
    return (
      <div className="flex gap-1 overflow-x-auto max-w-[200px] no-scrollbar py-1">
        {characters.map(c => {
          const isMentioned = combinedText.includes(c.name.toLowerCase());
          return (
            <button 
              key={c.id}
              onClick={() => insertCharacter(field, c.name)}
              className={`text-[9px] border px-2 py-0.5 rounded transition-all whitespace-nowrap font-bold uppercase tracking-tighter
                ${isMentioned 
                  ? 'bg-blue-600/30 border-blue-400 text-blue-300 shadow-[0_0_12px_rgba(59,130,246,0.4)] scale-105' 
                  : 'bg-slate-900 border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300'
                }`}
              title={`Mention ${c.name}`}
            >
              {c.name}
            </button>
          );
        })}
      </div>
    );
  };

  return (
    <div className="group relative bg-slate-800/40 border border-slate-700/50 rounded-2xl overflow-hidden hover:border-blue-500/30 transition-all duration-300 backdrop-blur-sm shadow-xl mb-6">
      <div className="flex flex-col md:flex-row">
        {/* Left Side: Lyrics */}
        <div className="w-full md:w-1/3 p-6 border-b md:border-b-0 md:border-r border-slate-700/50 bg-slate-900/40">
          <div className="flex items-center justify-between mb-4">
            <input 
              value={segment.sectionTitle}
              onChange={(e) => handleChange('sectionTitle', e.target.value)}
              className="bg-blue-600/20 text-blue-400 text-[10px] font-bold px-2 py-1 rounded uppercase tracking-wider outline-none border border-transparent focus:border-blue-500/50"
            />
            {onRemove && (
              <button onClick={onRemove} className="text-slate-600 hover:text-red-400 transition-colors">
                <i className="fa-solid fa-trash-can text-xs"></i>
              </button>
            )}
          </div>
          <p className="text-base font-medium leading-relaxed italic text-slate-300 whitespace-pre-wrap font-serif">
            {segment.lyrics}
          </p>
        </div>

        {/* Right Side: Editable Visuals */}
        <div className="w-full md:w-2/3 p-6 space-y-6">
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
            <div className="space-y-4">
              <div>
                <div className="flex justify-between items-center mb-2">
                  <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <i className="fa-solid fa-clapperboard"></i> Visual Content
                  </label>
                  <CharacterShortcuts field="visuals" />
                </div>
                <textarea 
                  value={segment.visuals}
                  onChange={(e) => handleChange('visuals', e.target.value)}
                  placeholder="Describe what we see..."
                  className="w-full bg-slate-900/60 border border-slate-700/50 rounded-xl p-3 text-sm text-slate-200 outline-none focus:border-blue-500/50 h-32 resize-none"
                />
              </div>

              <div className="grid grid-cols-1 gap-4">
                <div>
                  <div className="flex justify-between items-center mb-2">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                      <i className="fa-solid fa-video"></i> Camera
                    </label>
                    <CharacterShortcuts field="cameraWork" />
                  </div>
                  <textarea 
                    value={segment.cameraWork}
                    onChange={(e) => handleChange('cameraWork', e.target.value)}
                    rows={4}
                    className="w-full bg-slate-900/60 border border-slate-700/50 rounded-lg p-3 text-xs text-slate-300 outline-none focus:border-blue-500/50 resize-none"
                    placeholder="Describe camera movement, lens, and focus..."
                  />
                </div>
                <div>
                  <div className="flex justify-between items-center mb-2">
                    <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                      <i className="fa-solid fa-lightbulb"></i> Lighting & Mood
                    </label>
                    <CharacterShortcuts field="lightingMood" />
                  </div>
                  <textarea 
                    value={segment.lightingMood}
                    onChange={(e) => handleChange('lightingMood', e.target.value)}
                    rows={4}
                    className="w-full bg-slate-900/60 border border-slate-700/50 rounded-lg p-3 text-xs text-slate-300 outline-none focus:border-blue-500/50 resize-none"
                    placeholder="Describe lighting setup, color palette, and atmospheric effects..."
                  />
                </div>
              </div>
            </div>

            <div className="space-y-3">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                  <i className="fa-solid fa-diagram-project"></i> Scene Architecture
                </label>
                <button 
                  onClick={handleBuildDiagram}
                  disabled={isGeneratingDiagram || !segment.visuals}
                  className="text-[10px] font-bold text-blue-400 hover:text-blue-300 uppercase tracking-wider flex items-center gap-1 disabled:opacity-50"
                >
                  {isGeneratingDiagram ? (
                    <><i className="fa-solid fa-spinner animate-spin"></i> Processing</>
                  ) : (
                    <><i className="fa-solid fa-bolt"></i> {segment.mermaidDiagram ? 'Update Chart' : 'Build Chart'}</>
                  )}
                </button>
              </div>
              {segment.mermaidDiagram ? (
                <div className="w-full max-h-[400px] overflow-auto bg-slate-900/50 rounded-xl scrollbar-thin scrollbar-thumb-slate-700 scrollbar-track-transparent">
                  <MermaidChart chart={segment.mermaidDiagram} id={segment.id} />
                </div>
              ) : (
                <div className="h-full min-h-[150px] bg-slate-900/30 border border-dashed border-slate-700/50 rounded-xl flex items-center justify-center text-slate-600 text-xs text-center p-4">
                  {segment.visuals ? 'Ready to generate architectural flow' : 'Enter visuals to enable diagramming'}
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default StoryboardCard;

import React, { useEffect, useState, useMemo } from 'react';
import { StoryboardSegment, Character } from '../types';
import MermaidChart from './MermaidChart';
import { generateSceneContent, generateDiagram } from '../services/geminiService';
import HighlightText from './HighlightText';

interface PresentationViewProps {
  segments: StoryboardSegment[];
  characters: Character[];
  currentIndex: number;
  onUpdateSegment: (index: number, updated: StoryboardSegment) => void;
  onNext: () => void;
  onPrev: () => void;
  onExit: () => void;
  narrativeSeed: string;
}

const PresentationView: React.FC<PresentationViewProps> = ({ 
  segments, 
  characters,
  currentIndex, 
  onUpdateSegment,
  onNext, 
  onPrev, 
  onExit,
  narrativeSeed
}) => {
  const current = segments[currentIndex];
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.key === 'ArrowRight' || e.key === ' ') && (e.target as HTMLElement).tagName !== 'TEXTAREA' && (e.target as HTMLElement).tagName !== 'INPUT') {
        onNext();
      }
      if (e.key === 'ArrowLeft' && (e.target as HTMLElement).tagName !== 'TEXTAREA' && (e.target as HTMLElement).tagName !== 'INPUT') {
        onPrev();
      }
      if (e.key === 'Escape') onExit();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onNext, onPrev, onExit]);

  const handleFieldChange = (field: keyof StoryboardSegment, value: string) => {
    onUpdateSegment(currentIndex, { ...current, [field]: value });
  };

  const combinedText = useMemo(() => {
    if (!current) return '';
    return (current.visuals + ' ' + current.cameraWork + ' ' + current.lightingMood).toLowerCase();
  }, [current?.visuals, current?.cameraWork, current?.lightingMood]);

  const handleRegenerate = async () => {
    setIsRegenerating(true);
    try {
      const aiData = await generateSceneContent(current.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
      const updated = { ...current, ...aiData };
      const newDiagram = await generateDiagram(updated as StoryboardSegment);
      onUpdateSegment(currentIndex, { ...updated, mermaidDiagram: newDiagram });
    } catch (err) {
      console.error("Failed to regenerate scene:", err);
    } finally {
      setIsRegenerating(false);
    }
  };

  const insertCharacter = (field: keyof StoryboardSegment, name: string) => {
    const currentValue = (current[field] as string) || '';
    const newValue = currentValue.endsWith(' ') || currentValue === '' ? currentValue + name : currentValue + ' ' + name;
    handleFieldChange(field, newValue);
  };

  const CharacterShortcuts = ({ field }: { field: keyof StoryboardSegment }) => {
    if (!characters || characters.length === 0) return null;
    return (
      <div className="flex gap-1 overflow-x-auto max-w-[200px] no-scrollbar py-1">
        {characters.map(c => {
          const isMentioned = combinedText.includes(c.name.toLowerCase());
          return (
            <button 
              key={c.id}
              onClick={() => insertCharacter(field, c.name)}
              className={`text-[9px] border px-1.5 py-0.5 rounded transition-all whitespace-nowrap font-bold uppercase tracking-tighter
                ${isMentioned 
                  ? 'bg-blue-600/20 border-blue-500 text-blue-400 shadow-[0_0_10px_rgba(59,130,246,0.3)]' 
                  : 'bg-white/5 border-white/10 text-slate-500 hover:border-blue-500/50 hover:text-white'
                }`}
              title={`Mention ${c.name}`}
            >
              {c.name}
            </button>
          );
        })}
      </div>
    );
  };

  if (!current) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black text-white flex flex-col animate-in fade-in duration-500 overflow-hidden font-sans">
      {/* Header HUD */}
      <div className="p-4 flex justify-between items-center bg-zinc-900/80 border-b border-white/5">
        <div className="flex items-center gap-4">
          <button 
            onClick={onExit}
            className="w-8 h-8 rounded-lg bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors border border-white/10"
          >
            <i className="fa-solid fa-chevron-left text-xs"></i>
          </button>
          <div>
            <input 
              value={current.sectionTitle}
              onChange={(e) => handleFieldChange('sectionTitle', e.target.value)}
              className="bg-transparent border-none focus:ring-0 text-sm font-bold text-blue-500 uppercase tracking-widest p-0 w-48"
            />
            <p className="text-[10px] text-slate-500 uppercase tracking-tighter">Production Mode • Scene {currentIndex + 1} of {segments.length}</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
           <button 
             onClick={() => setIsPreviewMode(!isPreviewMode)}
             className={`px-3 py-1.5 rounded-md border text-[10px] font-bold uppercase tracking-widest transition-all
               ${isPreviewMode ? 'bg-blue-600 border-blue-500 text-white' : 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10'}`}
           >
             <i className={`fa-solid ${isPreviewMode ? 'fa-eye' : 'fa-pen-to-square'} mr-2`}></i>
             {isPreviewMode ? 'Preview Mode' : 'Edit Mode'}
           </button>
           <button 
             onClick={handleRegenerate}
             disabled={isRegenerating}
             className="text-[10px] font-bold text-blue-400 hover:text-blue-300 uppercase tracking-widest flex items-center gap-2 px-3 py-1.5 bg-blue-500/10 rounded-md border border-blue-500/20 disabled:opacity-50"
           >
             <i className={`fa-solid fa-wand-magic-sparkles ${isRegenerating ? 'animate-spin' : ''}`}></i>
             {isRegenerating ? 'Recreating...' : 'Recreate Scene'}
           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col md:flex-row p-4 md:p-8 gap-6 md:gap-8 min-h-0 overflow-y-auto md:overflow-hidden">
        {/* Left Side: Editorial */}
        <div className="w-full md:w-[45%] flex flex-col gap-6 md:overflow-y-auto pr-0 md:pr-4 custom-scrollbar">
          <div className="space-y-3">
             <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.3em]">Lyrics</span>
             <blockquote className="text-xl md:text-2xl font-serif italic text-slate-100 leading-snug bg-zinc-900/40 p-4 md:p-6 rounded-2xl border border-white/5">
               "{current.lyrics}"
             </blockquote>
          </div>

          <div className="space-y-6 pt-2 border-t border-white/10">
            <div>
               <div className="flex justify-between items-center mb-3">
                 <h4 className="text-[10px] font-bold text-blue-500 uppercase tracking-widest flex items-center gap-2">
                   <i className="fa-solid fa-clapperboard"></i> Action & Visuals
                 </h4>
                 {!isPreviewMode && <CharacterShortcuts field="visuals" />}
               </div>
               {isPreviewMode ? (
                 <div className="w-full bg-zinc-900/40 border border-white/5 rounded-xl p-4 md:p-6 text-lg md:text-xl text-slate-200 leading-relaxed min-h-[120px]">
                   <HighlightText text={current.visuals} characters={characters} />
                 </div>
               ) : (
                 <textarea 
                    value={current.visuals}
                    onChange={(e) => handleFieldChange('visuals', e.target.value)}
                    className="w-full bg-zinc-900 border border-white/10 rounded-xl p-4 text-base text-slate-300 leading-relaxed outline-none focus:border-blue-500/50 h-40 resize-none"
                    placeholder="Describe the action..."
                 />
               )}
            </div>

            <div className="flex flex-col gap-6">
              <div>
                <div className="flex justify-between items-center mb-2">
                  <h4 className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <i className="fa-solid fa-video"></i> Camera
                  </h4>
                  {!isPreviewMode && <CharacterShortcuts field="cameraWork" />}
                </div>
                {isPreviewMode ? (
                  <div className="w-full bg-zinc-900/40 border border-white/5 rounded-lg p-3 text-sm font-medium text-slate-300 min-h-[80px]">
                    <HighlightText text={current.cameraWork} characters={characters} />
                  </div>
                ) : (
                  <textarea 
                    value={current.cameraWork}
                    onChange={(e) => handleFieldChange('cameraWork', e.target.value)}
                    rows={4}
                    className="w-full bg-zinc-900 border border-white/10 rounded-lg p-3 text-sm font-medium text-slate-300 outline-none focus:border-blue-500/50 resize-none"
                    placeholder="Camera notes..."
                  />
                )}
              </div>
