import React, { useState, useRef } from 'react';
import { Character } from '../types';

interface CharacterManagerProps {
  characters: Character[];
  onUpdate: (chars: Character[]) => void;
}

const CharacterManager: React.FC<CharacterManagerProps> = ({ characters = [], onUpdate }) => {
  const [newName, setNewName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);

  const handleAddCharacter = () => {
    if (!newName.trim()) return;
    const char: Character = {
      id: `char-${Date.now()}`,
      name: newName.trim(),
      images: []
    };
    onUpdate([...characters, char]);
    setNewName('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddCharacter();
    }
  };

  const removeCharacter = (id: string) => {
    onUpdate(characters.filter(c => c.id !== id));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    // Cast files to File[] to fix 'unknown' type error during assignment or passing to readAsDataURL
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0 || !activeCharId) return;

    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        onUpdate(characters.map(c => 
          c.id === activeCharId 
            ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } 
            : c
        ));
      };
      // reader.readAsDataURL expects a Blob; File inherits from Blob
      reader.readAsDataURL(file);
    });

    setActiveCharId(null);
    e.target.value = '';
  };

  const triggerUpload = (id: string) => {
    setActiveCharId(id);
    fileInputRef.current?.click();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
          Cast & Characters
        </label>
        <span className="text-[10px] text-slate-600 italic">Add names then upload reference images</span>
      </div>

      <div className="flex gap-2">
        <input
          type="text"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Type character name and press Enter..."
          className="flex-1 p-3 bg-slate-900/50 border border-slate-800 rounded-xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm transition-all text-white"
        />
        <button 
          type="button"
          onClick={handleAddCharacter}
          className="px-4 py-2 bg-slate-800 text-slate-300 rounded-xl hover:bg-slate-700 transition-colors"
        >
          <i className="fa-solid fa-plus"></i>
        </button>
      </div>

      <div className="flex flex-wrap gap-3">
        {(characters || []).map((char) => (
          <div 
            key={char.id}
            className="group relative flex items-center gap-3 bg-slate-800/40 border border-slate-700/50 p-2 pr-4 rounded-2xl hover:border-blue-500/30 transition-all"
          >
            <div 
              onClick={() => triggerUpload(char.id)}
              className="w-10 h-10 rounded-full bg-slate-900 border border-slate-700 overflow-hidden flex items-center justify-center cursor-pointer hover:border-blue-500 transition-colors group/img"
            >
              {char.images && char.images.length > 0 ? (
                <img src={char.images[0]} alt={char.name} className="w-full h-full object-cover" />
              ) : (
                <i className="fa-solid fa-user-plus text-slate-600 group-hover/img:text-blue-500"></i>
              )}
            </div>

            <div className="flex flex-col">
              <span className="text-sm font-bold text-slate-200">{char.name}</span>
              <div className="flex items-center gap-2">
                <span className="text-[8px] text-blue-400 uppercase font-bold">{(char.images || []).length} Refs</span>
                <button 
                  type="button"
                  onClick={() => removeCharacter(id)}
                  className="text-[10px] text-slate-500 hover:text-red-400 text-left transition-colors"
                >
                  Remove
                </button>
              </div>
            </div>
          </div>
        ))}

        {(!characters || characters.length === 0) && (
          <div className="text-xs text-slate-600 italic py-2">No characters defined yet.</div>
        )}
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        multiple
        className="hidden" 
      />
    </div>
  );
};

export default CharacterManager;

import { GoogleGenAI, Type } from "@google/genai";
import { StoryboardSegment, Character } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const generateSceneContent = async (
  lyrics: string, 
  context: string, 
  seed: string, 
  characters: Character[]
): Promise<Partial<StoryboardSegment>> => {
  const charContext = characters.length > 0 
    ? `CHARACTERS IN STORY: ${characters.map(c => c.name).join(', ')}.` 
    : '';

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `As a video director, provide visual instructions for this specific song segment.

      NARRATIVE ANGLE/DIRECTION: ${seed || "Cinematic and faithful to the lyrics"}
      ${charContext}

      CONTEXT: ${context}
      SEGMENT LYRICS: ${lyrics}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visuals: { type: Type.STRING, description: "Action happening in the scene. Use character names if applicable." },
            cameraWork: { type: Type.STRING, description: "Camera movement and angles" },
            lightingMood: { type: Type.STRING, description: "Lighting style and color palette" },
            sectionTitle: { type: Type.STRING, description: "Logical name (e.g. Verse 1)" }
          },
          required: ["visuals", "cameraWork", "lightingMood", "sectionTitle"]
        }
      }
    });

    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text.trim());
  } catch (error: any) {
    if (error?.message?.includes('429') || error?.status === 'RESOURCE_EXHAUSTED') {
      throw new Error("QUOTA_EXHAUSTED: API rate limit reached. Please wait a moment before trying again.");
    }
    throw error;
  }
};

export const generateDiagram = async (segment: StoryboardSegment): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Create a Mermaid.js flowchart representing the flow of the following film scene. 
      IMPORTANT RULES:
      1. Use clean, professional syntax.
      2. ALL node labels MUST be wrapped in double quotes to prevent syntax errors, e.g., A["Label with @ or symbols"].
      3. Use 'graph TD' (Top Down).
      4. Do not include markdown blocks or "mermaid" tags.

      SCENE DESCRIPTION: ${segment.visuals}
      CAMERA: ${segment.cameraWork}`,
    });

    return response.text || '';
  } catch (error: any) {
    if (error?.message?.includes('429')) throw new Error("QUOTA_EXHAUSTED");
    throw error;
  }
};

export const generateFrame = async (
  segment: StoryboardSegment, 
  characters: Character[],
  type: 'FIRST' | 'LAST',
  seed: string
): Promise<string> => {
  const model = 'gemini-2.5-flash-image';

  const mentionedChars = characters.filter(c => 
    segment.visuals.toLowerCase().includes(c.name.toLowerCase()) ||
    segment.cameraWork.toLowerCase().includes(c.name.toLowerCase())
  );

  const parts: any[] = [];

  mentionedChars.forEach(char => {
    (char.images || []).slice(0, 2).forEach(img => {
      const parts_img = img.split(',');
      if (parts_img.length < 2) return;
      const base64Data = parts_img[1];
      const mimeType = parts_img[0].split(';')[0].split(':')[1];
      parts.push({
        inlineData: { data: base64Data, mimeType }
      });
    });
  });

  const prompt = `Generate a high-quality cinematic ${type} FRAME for a music video scene.
  SCENE DESCRIPTION: ${segment.visuals}
  CAMERA WORK: ${segment.cameraWork}
  LIGHTING & MOOD: ${segment.lightingMood}
  NARRATIVE DIRECTION: ${seed}

  The provided images are character references. Ensure characters match these references exactly.
  ${type === 'FIRST' ? 'Capture the starting moment.' : 'Capture the peak of motion.'}

  Style: Photorealistic, cinematic 35mm film.`;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts },
      config: {
          imageConfig: { aspectRatio: "16:9" }
      }
    });

    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
  } catch (error: any) {
    if (error?.message?.includes('429')) throw new Error("QUOTA_EXHAUSTED");
    throw error;
  }

  throw new Error("No image generated");
};

import React, { useEffect, useRef } from 'react';
import mermaid from 'mermaid';

interface MermaidChartProps {
  chart: string;
  id: string;
}

const MermaidChart: React.FC<MermaidChartProps> = ({ chart, id }) => {
  const chartRef = useRef<HTMLDivElement>(null);
  const renderId = useRef(0);

  useEffect(() => {
    mermaid.initialize({
      startOnLoad: false,
      theme: 'dark',
      securityLevel: 'loose',
      fontFamily: 'JetBrains Mono',
    });

    const renderChart = async () => {
      const currentRenderId = ++renderId.current;
      const target = chartRef.current;
      if (!target) return;

      try {
          // Clean common AI formatting issues in mermaid code
          let cleanChart = chart
              .replace(/```mermaid/g, '')
              .replace(/```/g, '')
              .trim();

          // Basic fix for unquoted labels with special characters like @
          // This wraps node labels that contain @ in quotes if not already quoted
          cleanChart = cleanChart.replace(/(\w+)\[([^"\]]+@[^"\]]+)\]/g, '$1["$2"]');
          cleanChart = cleanChart.replace(/(\w+)\(([^"\]]+@[^"\]]+)\)/g, '$1("$2")');

          // Ensure it has a graph header if missing
          if (!cleanChart.startsWith('graph') && !cleanChart.startsWith('flowchart')) {
            cleanChart = 'graph TD\n' + cleanChart;
          }

          const { svg } = await mermaid.render(`mermaid-${id}-${currentRenderId}`, cleanChart);

          // Re-verify ref and render sequence before updating DOM
          if (chartRef.current && currentRenderId === renderId.current) {
            chartRef.current.innerHTML = svg;
          }
      } catch (error) {
          console.error('Mermaid render error:', error);
          if (chartRef.current && currentRenderId === renderId.current) {
            chartRef.current.innerHTML = '<div class="text-red-400 text-[10px] p-2 bg-red-900/20 rounded border border-red-900/50">Syntax error in architectural diagram</div>';
          }
      }
    };

    renderChart();

    return () => {
      renderId.current++; // Invalidate previous render on cleanup
    };
  }, [chart, id]);

  return (
    <div className="mermaid-container w-full min-h-[100px] overflow-hidden flex justify-center bg-slate-900/50 rounded-lg p-4" ref={chartRef} />
  );
};

export default MermaidChart;

import React, { useState, useRef } from 'react';
import { Character } from '../types';

interface CharacterManagerProps {
  characters: Character[];
  onUpdate: (chars: Character[]) => void;
}

const CharacterManager: React.FC<CharacterManagerProps> = ({ characters = [], onUpdate }) => {
  const [newName, setNewName] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);

  const handleAddCharacter = () => {
    if (!newName.trim()) return;
    const char: Character = {
      id: `char-${Date.now()}`,
      name: newName.trim(),
      images: []
    };
    onUpdate([...characters, char]);
    setNewName('');
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      e.preventDefault();
      handleAddCharacter();
    }
  };

  const removeCharacter = (id: string) => {
    onUpdate(characters.filter(c => c.id !== id));
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0 || !activeCharId) return;

    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        onUpdate(characters.map(c => 
          c.id === activeCharId 
            ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } 
            : c
        ));
      };
      reader.readAsDataURL(file);
    });

    setActiveCharId(null);
    e.target.value = '';
  };

  const triggerUpload = (id: string) => {
    setActiveCharId(id);
    fileInputRef.current?.click();
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">
          Cast & Characters
        </label>
        <span className="text-[10px] text-slate-600 italic">Add names then upload reference images</span>
      </div>

      <div className="flex gap-2">
        <input
          type="text"
          value={newName}
          onChange={(e) => setNewName(e.target.value)}
          onKeyDown={handleKeyDown}
          placeholder="Type character name and press Enter..."
          className="flex-1 p-3 bg-slate-900/50 border border-slate-800 rounded-xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm transition-all text-white"
        />
        <button 
          type="button"
          onClick={handleAddCharacter}
          className="px-4 py-2 bg-slate-800 text-slate-300 rounded-xl hover:bg-slate-700 transition-colors"
        >
          <i className="fa-solid fa-plus"></i>
        </button>
      </div>

      <div className="flex flex-wrap gap-3">
        {(characters || []).map((char) => (
          <div 
            key={char.id}
            className="group relative flex items-center gap-3 bg-slate-800/40 border border-slate-700/50 p-2 pr-4 rounded-2xl hover:border-blue-500/30 transition-all"
          >
            <div 
              onClick={() => triggerUpload(char.id)}
              className="w-10 h-10 rounded-full bg-slate-900 border border-slate-700 overflow-hidden flex items-center justify-center cursor-pointer hover:border-blue-500 transition-colors group/img"
            >
              {char.images && char.images.length > 0 ? (
                <img src={char.images[0]} alt={char.name} className="w-full h-full object-cover" />
              ) : (
                <i className="fa-solid fa-user-plus text-slate-600 group-hover/img:text-blue-500"></i>
              )}
            </div>

            <div className="flex flex-col">
              <span className="text-sm font-bold text-slate-200">{char.name}</span>
              <div className="flex items-center gap-2">
                <span className="text-[8px] text-blue-400 uppercase font-bold">{(char.images || []).length} Refs</span>
                <button 
                  type="button"
                  onClick={() => removeCharacter(char.id)}
                  className="text-[10px] text-slate-500 hover:text-red-400 text-left transition-colors"
                >
                  Remove
                </button>
              </div>
            </div>
          </div>
        ))}

        {(!characters || characters.length === 0) && (
          <div className="text-xs text-slate-600 italic py-2">No characters defined yet.</div>
        )}
      </div>

      <input 
        type="file" 
        ref={fileInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        multiple
        className="hidden" 
      />
    </div>
  );
};

export default CharacterManager;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { generateSceneContent, generateFrame } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import PresentationView from './components/PresentationView';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [currentSceneIndex, setCurrentSceneIndex] = useState(0);
  const [isCharModalOpen, setIsCharModalOpen] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
  const [isGeneratingFrames, setIsGeneratingFrames] = useState(false);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setErrorMessage(null);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);

    try {
      const populated = await Promise.all(newSegments.map(async (seg) => {
        try {
          const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
          return { ...seg, ...aiData };
        } catch (e: any) {
          if (e.message.includes('QUOTA')) {
            setErrorMessage("Some scenes couldn't be automatically populated due to API rate limits.");
          }
          return seg;
        }
      }));
      setSegments(populated);
    } catch (e) {
      console.error(e);
    } finally {
      setIsBulkProcessing(false);
    }
  };

  const handleProcessVisuals = async (sceneId: string) => {
    setActiveSceneId(sceneId);
    setErrorMessage(null);
    setStep(AppStep.FRAME_DEV);
    setIsGeneratingFrames(true);

    const segment = segments.find(s => s.id === sceneId);
    if (!segment) return;

    try {
      const [first, last] = await Promise.all([
        generateFrame(segment, characters, 'FIRST', narrativeSeed),
        generateFrame(segment, characters, 'LAST', narrativeSeed)
      ]);

      setSegments(prev => prev.map(s => 
        s.id === sceneId ? { ...s, firstFrame: first, lastFrame: last } : s
      ));
    } catch (err: any) {
      console.error("Frame generation failed:", err);
      if (err.message.includes('QUOTA')) {
        setErrorMessage("Visual generation limit reached. Please wait a few seconds.");
      } else {
        setErrorMessage("Visual generation failed. Ensure your character photos are valid.");
      }
    } finally {
      setIsGeneratingFrames(false);
    }
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const extractCharactersFromText = (text: string) => {
    return (characters || [])
      .filter(char => {
        const regex = new RegExp(`\\b${char.name}\\b`, 'i');
        return regex.test(text);
      })
      .map(char => char.name);
  };

  const saveProject = () => {
    const updatedSegments = segments.map(seg => ({
      ...seg,
      characters: extractCharactersFromText(seg.visuals + ' ' + seg.cameraWork + ' ' + seg.lightingMood)
    }));

    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments: updatedSegments,
      characters: characters || [],
      step,
      version: "1.4.1"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-bundle-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => fileInputRef.current?.click();

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText || '');
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);
        setStep(AppStep.PRODUCTION);
      } catch (err) {
        alert("Failed to load project file.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; 
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0 || !activeCharId) return;

    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        setCharacters(prev => prev.map(c => 
          c.id === activeCharId 
            ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } 
            : c
        ));
      };
      reader.readAsDataURL(file);
    });

    setActiveCharId(null);
    e.target.value = '';
  };

  const activeSegment = segments.find(s => s.id === activeSceneId);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {step === AppStep.PRESENTATION && (
        <PresentationView 
          segments={segments}
          characters={characters}
          currentIndex={currentSceneIndex}
          onUpdateSegment={updateSegment}
          onNext={() => setCurrentSceneIndex(p => Math.min(segments.length - 1, p + 1))}
          onPrev={() => setCurrentSceneIndex(p => Math.max(0, p - 1))}
          onExit={() => setStep(AppStep.PRODUCTION)}
          narrativeSeed={narrativeSeed}
        />
      )}

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-slate-800/50">
        <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/20 cursor-pointer" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
              <i className="fa-solid fa-clapperboard text-white text-sm"></i>
            </div>
            <h1 className="text-lg font-bold tracking-tight">LyricLens Studio</h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 mr-4">
              {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.PRODUCTION, AppStep.RESOURCES].map((s, idx) => (
                <React.Fragment key={s}>
                  <div 
                    className={`text-[10px] font-bold uppercase tracking-widest cursor-pointer hover:text-blue-400 transition-colors ${step === s ? 'text-blue-500 border-b-2 border-blue-500 pb-0.5' : 'text-slate-600'}`}
                    onClick={() => setStep(s)}
                  >
                    {s.replace('_', ' ')}
                  </div>
                  {idx < 3 && <div className="w-4 h-[1px] bg-slate-800"></div>}
                </React.Fragment>
              ))}
            </div>

            <input type="file" ref={fileInputRef} onChange={loadProject} accept=".json" className="hidden" />

            <div className="flex items-center gap-2 border-l border-slate-800 pl-4">
              <button onClick={handleLoadClick} className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-xs font-bold"><i className="fa-solid fa-folder-open"></i> Load</button>
              <button onClick={saveProject} className="p-2 text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-2 text-xs font-bold"><i className="fa-solid fa-floppy-disk"></i> Save Project</button>
            </div>
          </div>
        </div>
      </header>

      {errorMessage && (
        <div className="bg-red-900/40 border-b border-red-800 p-3 text-center animate-in slide-in-from-top duration-300">
           <p className="text-xs font-bold text-red-200 uppercase tracking-widest flex items-center justify-center gap-2">
             <i className="fa-solid fa-triangle-exclamation"></i> {errorMessage}
             <button onClick={() => setErrorMessage(null)} className="ml-4 underline opacity-50 hover:opacity-100">Dismiss</button>
           </p>
        </div>
      )}

      <main className="max-w-5xl mx-auto px-6 py-12">
        {step === AppStep.PASTE_LYRICS && (
          <div className="animate-in fade-in duration-500 max-w-2xl mx-auto">
            <div className="text-center mb-10">
              <h2 className="text-3xl font-bold text-white mb-3 tracking-tight">Directing Desk</h2>
              <p className="text-slate-400">Set the stage, define your cast, and paste your source text.</p>
            </div>
            <div className="space-y-10">
              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">Narrative Seed / Angle</label>
                <input
                  type="text"
                  value={narrativeSeed}
                  onChange={(e) => setNarrativeSeed(e.target.value)}
                  placeholder="e.g. A dystopian future with neon lighting..."
                  className="w-full p-4 bg-slate-900/50 border border-slate-800 rounded-2xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm text-white"
                />
              </div>

              <CharacterManager characters={characters || []} onUpdate={setCharacters} />

              <div className="space-y-3">
                <label className="text-xs font-bold text-slate-500 uppercase tracking-widest block px-1">Lyrics / Script</label>
                <textarea
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  placeholder="Paste lyrics or narrative text here..."
                  className="w-full h-80 p-6 bg-slate-900/50 border border-slate-800 rounded-3xl focus:ring-1 focus:ring-blue-500/50 outline-none text-lg resize-none font-serif text-white shadow-inner"
                />
              </div>

              <button
                type="button"
                onClick={() => setStep(AppStep.DEFINE_SCENES)}
                disabled={!rawText.trim()}
                className="w-full py-4 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-bold shadow-xl transition-all"
              >
                Proceed to Scene Layout
              </button>
            </div>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="animate-in fade-in duration-500 max-w-xl mx-auto">
            <div className="text-center mb-8">
              <h2 className="text-2xl font-bold text-white mb-2">Identify Scene Breaks</h2>
              <p className="text-sm text-slate-400">Click the gaps between lines to define start points for new visual directions.</p>
            </div>
            <div className="space-y-1 bg-slate-900/30 p-8 rounded-3xl border border-slate-800/50 shadow-inner">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button onClick={() => toggleMarker(idx)} className="w-full py-2 flex items-center justify-center group relative">
                      <div className={`h-[2px] transition-all ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'w-1/4 bg-slate-800 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                    </button>
                  )}
                  <div className={`text-center py-1 font-serif text-slate-300 ${sceneMarkers.includes(idx) ? 'pt-4 text-white font-semibold' : ''}`}>{line}</div>
                </React.Fragment>
              ))}
            </div>
            <div className="mt-10 flex gap-4">
              <button onClick={() => setStep(AppStep.PASTE_LYRICS)} className="flex-1 py-4 bg-slate-800 text-slate-300 rounded-2xl font-bold">Back</button>
              <button onClick={handleProceedToProduction} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-bold">Generate Pre-Production Draft</button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            {isCharModalOpen && (
              <div className="fixed inset-0 z-[150] bg-black/80 backdrop-blur-sm flex items-center justify-center p-6">
                <div className="bg-slate-900 border border-slate-800 w-full max-w-2xl rounded-3xl p-8 shadow-2xl space-y-6">
                  <div className="flex justify-between items-center"><h3 className="text-xl font-bold text-white">Edit Production Cast</h3><button onClick={() => setIsCharModalOpen(false)} className="text-slate-400 hover:text-white"><i className="fa-solid fa-xmark"></i></button></div>
                  <CharacterManager characters={characters} onUpdate={setCharacters} />
                  <div className="pt-4 flex justify-end"><button onClick={() => setIsCharModalOpen(false)} className="px-6 py-2 bg-blue-600 text-white rounded-xl font-bold">Apply Changes</button></div>
                </div>
              </div>
            )}
            <div className="flex justify-between items-end mb-8">
              <div>
                <h2 className="text-3xl font-bold text-white mb-1">Director's Board</h2>
                <div className="flex gap-4">
                  <button onClick={() => setIsCharModalOpen(true)} className="text-[10px] text-blue-500 hover:underline">Edit Cast</button>
                  <button onClick={saveProject} className="text-[10px] text-slate-500 hover:text-white transition-colors"><i className="fa-solid fa-cloud-arrow-up mr-1"></i> Stage Save</button>
                </div>
              </div>
              <button onClick={() => setStep(AppStep.RESOURCES)} className="px-6 py-3 bg-blue-600 text-white rounded-xl font-bold shadow-lg shadow-blue-600/20">Finalize Resources <i className="fa-solid fa-arrow-right ml-2"></i></button>
            </div>
            <div className="space-y-4">
              {segments.map((seg, idx) => (
                <StoryboardCard 
                  key={seg.id} 
                  segment={seg} 
                  characters={characters} 
                  onUpdate={(updated) => updateSegment(idx, updated)} 
                  onProcess={() => handleProcessVisuals(seg.id)}
                />
              ))}
            </div>
          </div>
        )}

        {step === AppStep.RESOURCES && (
          <div className="animate-in fade-in duration-700 max-w-5xl mx-auto">
             <div className="text-center mb-12">
               <h2 className="text-3xl font-bold text-white mb-2">Resource Gallery</h2>
               <p className="text-slate-400">Build character mood-boards to maintain visual consistency across all generated frames.</p>
             </div>

             <div className="space-y-12">
               {characters.map(char => (
                 <div key={char.id} className="bg-slate-800/20 border border-slate-800 rounded-3xl p-8 group">
                    <div className="flex items-center justify-between mb-6">
                       <div>
                         <h3 className="text-2xl font-bold text-white">{char.name}</h3>
                         <p className="text-[10px] text-slate-500 uppercase tracking-[0.3em]">Character Profile</p>
                       </div>
                       <button 
                         onClick={() => {
                           setActiveCharId(char.id);
                           imageInputRef.current?.click();
                         }}
                         className="px-4 py-2 bg-blue-600/10 hover:bg-blue-600 text-blue-500 hover:text-white border border-blue-500/20 rounded-xl text-xs font-bold transition-all"
                       >
                         Add Reference Photo
                       </button>
                    </div>
                    <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-5 gap-4">
                       {(char.images || []).map((img, i) => (
                         <div key={i} className="aspect-square rounded-xl bg-slate-900 border border-slate-700 overflow-hidden relative group/img">
                            <img src={img} className="w-full h-full object-cover transition-transform duration-500 group-hover/img:scale-110" />
                            <button 
                              onClick={() => setCharacters(prev => prev.map(c => c.id === char.id ? {...c, images: c.images.filter((_, idx) => idx !== i)} : c))}
                              className="absolute top-2 right-2 w-6 h-6 bg-black/60 rounded-full flex items-center justify-center opacity-0 group-hover/img:opacity-100 transition-opacity"
                            >
                              <i className="fa-solid fa-xmark text-[10px] text-white"></i>
                            </button>
                         </div>
                       ))}
                       {(!char.images || char.images.length === 0) && (
                         <div 
                           onClick={() => {
                             setActiveCharId(char.id);
                             imageInputRef.current?.click();
                           }}
                           className="aspect-square rounded-xl border-2 border-dashed border-slate-800 hover:border-blue-500/50 flex flex-col items-center justify-center text-slate-700 cursor-pointer transition-colors"
                         >
                            <i className="fa-solid fa-camera text-2xl mb-2"></i>
                            <span className="text-[10px] font-bold uppercase tracking-widest">Upload</span>
                         </div>
                       )}
                    </div>
                 </div>
               ))}
               {characters.length === 0 && <div className="text-center py-20 text-slate-600 italic">No characters defined yet. Go to Directing Desk.</div>}
             </div>

             <div className="mt-16 flex justify-center gap-6">
                <button onClick={() => setStep(AppStep.PRODUCTION)} className="px-8 py-4 bg-slate-800 text-slate-300 rounded-2xl font-bold flex items-center gap-3"><i className="fa-solid fa-chevron-left"></i> Storyboard</button>
                <button onClick={() => { setCurrentSceneIndex(0); setStep(AppStep.PRESENTATION); }} className="px-10 py-4 bg-blue-600 text-white rounded-2xl font-bold flex items-center gap-3 shadow-xl shadow-blue-600/20"><i className="fa-solid fa-play"></i> Final Review</button>
             </div>
          </div>
        )}

        {step === AppStep.FRAME_DEV && activeSegment && (
          <div className="animate-in fade-in duration-700 max-w-6xl mx-auto space-y-12">
             <div className="flex flex-col md:flex-row justify-between items-center gap-6">
                <div>
                  <h2 className="text-3xl font-bold text-white mb-2">{activeSegment.sectionTitle}: Visual Dev</h2>
                  <p className="text-slate-400 max-w-lg italic font-serif">"{activeSegment.lyrics}"</p>
                </div>
                <button 
                  onClick={() => setStep(AppStep.PRODUCTION)}
                  className="px-6 py-3 bg-slate-800 hover:bg-slate-700 text-white rounded-xl font-bold flex items-center gap-2 transition-all"
                >
                  <i className="fa-solid fa-arrow-left"></i> Back to Board
                </button>
             </div>

             <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* First Frame */}
                <div className="space-y-4">
                   <div className="flex justify-between items-center">
                      <span className="text-[10px] font-bold text-blue-500 uppercase tracking-[0.4em]">First Frame (Scene Start)</span>
                      {isGeneratingFrames && <i className="fa-solid fa-circle-notch animate-spin text-blue-500 text-xs"></i>}
                   </div>
                   <div className="aspect-video bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl relative flex items-center justify-center">
                      {activeSegment.firstFrame ? (
                        <img src={activeSegment.firstFrame} className="w-full h-full object-cover animate-in zoom-in duration-1000" />
                      ) : (
                        <div className="text-center space-y-4">
                           <div className="w-16 h-1 bg-slate-800 mx-auto rounded-full overflow-hidden">
                              <div className="h-full bg-blue-600 animate-[loading_2s_infinite_ease-in-out]"></div>
                           </div>
                           <p className="text-[10px] text-slate-600 font-bold uppercase tracking-widest">Generating Character Consistent Shot...</p>
                        </div>
                      )}
                   </div>
                </div>

                {/* Last Frame */}
                <div className="space-y-4">
                   <div className="flex justify-between items-center">
                      <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.4em]">Last Frame (Peak Motion)</span>
                      {isGeneratingFrames && <i className="fa-solid fa-circle-notch animate-spin text-slate-600 text-xs"></i>}
                   </div>
                   <div className="aspect-video bg-slate-900 border border-slate-800 rounded-3xl overflow-hidden shadow-2xl relative flex items-center justify-center">
                      {activeSegment.lastFrame ? (
                        <img src={activeSegment.lastFrame} className="w-full h-full object-cover animate-in zoom-in duration-1000" />
                      ) : (
                        <div className="text-center space-y-4">
                           <div className="w-16 h-1 bg-slate-800 mx-auto rounded-full overflow-hidden">
                              <div className="h-full bg-slate-600 animate-[loading_2s_infinite_ease-in-out_delay-500]"></div>
                           </div>
                           <p className="text-[10px] text-slate-600 font-bold uppercase tracking-widest">Extrapolating Cinematic Motion...</p>
                        </div>
                      )}
                   </div>
                </div>
             </div>

             <div className="p-8 bg-slate-900/40 border border-slate-800 rounded-3xl grid grid-cols-1 md:grid-cols-3 gap-8">
                <div>
                   <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 block">Action Recap</label>
                   <p className="text-sm text-slate-300 leading-relaxed">{activeSegment.visuals}</p>
                </div>
                <div>
                   <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 block">Camera Notes</label>
                   <p className="text-sm text-slate-300 leading-relaxed">{activeSegment.cameraWork}</p>
                </div>
                <div>
                   <label className="text-[10px] font-bold text-slate-500 uppercase tracking-widest mb-2 block">Atmosphere</label>
                   <p className="text-sm text-slate-300 leading-relaxed">{activeSegment.lightingMood}</p>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Separate hidden input for character image uploads */}
      <input 
        type="file" 
        ref={imageInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        multiple
        className="hidden" 
      />

      <style>{`
        @keyframes loading {
          0% { transform: translateX(-100%); }
          100% { transform: translateX(100%); }
        }
        .delay-500 { animation-delay: 0.5s; }
      `}</style>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { generateSceneContent, generateFrame } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import PresentationView from './components/PresentationView';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [currentSceneIndex, setCurrentSceneIndex] = useState(0);
  const [isCharModalOpen, setIsCharModalOpen] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
  const [isGeneratingFrames, setIsGeneratingFrames] = useState(false);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setErrorMessage(null);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);

    try {
      const populated = await Promise.all(newSegments.map(async (seg) => {
        try {
          const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
          return { ...seg, ...aiData };
        } catch (e: any) {
          if (e.message.includes('QUOTA')) {
            setErrorMessage("Some scenes couldn't be automatically populated due to API rate limits.");
          }
          return seg;
        }
      }));
      setSegments(populated);
    } catch (e) {
      console.error(e);
    } finally {
      setIsBulkProcessing(false);
    }
  };

  const handleProcessVisuals = async (sceneId: string) => {
    setActiveSceneId(sceneId);
    setErrorMessage(null);
    setStep(AppStep.FRAME_DEV);
    setIsGeneratingFrames(true);

    const segment = segments.find(s => s.id === sceneId);
    if (!segment) return;

    try {
      const [first, last] = await Promise.all([
        generateFrame(segment, characters, 'FIRST', narrativeSeed),
        generateFrame(segment, characters, 'LAST', narrativeSeed)
      ]);

      setSegments(prev => prev.map(s => 
        s.id === sceneId ? { ...s, firstFrame: first, lastFrame: last } : s
      ));
    } catch (err: any) {
      console.error("Frame generation failed:", err);
      if (err.message.includes('QUOTA')) {
        setErrorMessage("Visual generation limit reached. Please wait a few seconds.");
      } else {
        setErrorMessage("Visual generation failed. Ensure your character photos are valid.");
      }
    } finally {
      setIsGeneratingFrames(false);
    }
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const extractCharactersFromText = (text: string) => {
    return (characters || [])
      .filter(char => {
        const regex = new RegExp(`\\b${char.name}\\b`, 'i');
        return regex.test(text);
      })
      .map(char => char.name);
  };

  const saveProject = () => {
    const updatedSegments = segments.map(seg => ({
      ...seg,
      characters: extractCharactersFromText(seg.visuals + ' ' + seg.cameraWork + ' ' + seg.lightingMood)
    }));

    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments: updatedSegments,
      characters: characters || [],
      step,
      version: "1.5.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-bundle-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => fileInputRef.current?.click();

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText || '');
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);
        setStep(AppStep.PRODUCTION);
      } catch (err) {
        alert("Failed to load project file.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; 
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0 || !activeCharId) return;

    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        setCharacters(prev => prev.map(c => 
          c.id === activeCharId 
            ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } 
            : c
        ));
      };
      reader.readAsDataURL(file);
    });

    setActiveCharId(null);
    e.target.value = '';
  };

  const activeSegment = segments.find(s => s.id === activeSceneId);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 selection:bg-blue-500/30">
      {step === AppStep.PRESENTATION && (
        <PresentationView 
          segments={segments}
          characters={characters}
          currentIndex={currentSceneIndex}
          onUpdateSegment={updateSegment}
          onNext={() => setCurrentSceneIndex(p => Math.min(segments.length - 1, p + 1))}
          onPrev={() => setCurrentSceneIndex(p => Math.max(0, p - 1))}
          onExit={() => setStep(AppStep.PRODUCTION)}
          narrativeSeed={narrativeSeed}
        />
      )}

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-white/5">
        <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/30 cursor-pointer hover:scale-105 transition-transform" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
              <i className="fa-solid fa-clapperboard text-white text-sm"></i>
            </div>
            <h1 className="text-lg font-black tracking-tighter uppercase italic">LyricLens <span className="text-blue-500">Studio</span></h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 mr-4">
              {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.PRODUCTION, AppStep.RESOURCES].map((s, idx) => (
                <React.Fragment key={s}>
                  <div 
                    className={`text-[10px] font-bold uppercase tracking-widest cursor-pointer hover:text-blue-400 transition-colors ${step === s ? 'text-blue-500 border-b-2 border-blue-500 pb-1' : 'text-slate-600'}`}
                    onClick={() => setStep(s)}
                  >
                    {s.replace('_', ' ')}
                  </div>
                  {idx < 3 && <div className="w-4 h-[1px] bg-white/10"></div>}
                </React.Fragment>
              ))}
            </div>

            <input type="file" ref={fileInputRef} onChange={loadProject} accept=".json" className="hidden" />

            <div className="flex items-center gap-2 border-l border-white/10 pl-4">
              <button onClick={handleLoadClick} className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider"><i className="fa-solid fa-folder-open"></i> Load</button>
              <button onClick={saveProject} className="p-2 text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider"><i className="fa-solid fa-floppy-disk"></i> Save Bundle</button>
            </div>
          </div>
        </div>
      </header>

      {errorMessage && (
        <div className="fixed top-16 left-0 right-0 z-[60] bg-red-600 border-b border-red-500 p-2 text-center animate-in slide-in-from-top duration-300">
           <p className="text-[10px] font-black text-white uppercase tracking-[0.2em] flex items-center justify-center gap-3">
             <i className="fa-solid fa-triangle-exclamation"></i> {errorMessage}
             <button onClick={() => setErrorMessage(null)} className="ml-4 bg-white/20 px-2 py-0.5 rounded hover:bg-white/30">Dismiss</button>
           </p>
        </div>
      )}

      <main className="max-w-7xl mx-auto px-6 py-8">
        {step === AppStep.PASTE_LYRICS && (
          <div className="animate-in fade-in zoom-in-95 duration-500 max-w-2xl mx-auto py-12">
            <div className="text-center mb-12">
              <div className="inline-block px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/20 text-[10px] font-bold text-blue-400 uppercase tracking-[0.3em] mb-4">Phase 01: Setup</div>
              <h2 className="text-5xl font-black text-white mb-4 tracking-tighter uppercase">Directing <span className="text-blue-500">Desk</span></h2>
              <p className="text-slate-400 font-medium">Set the creative direction and define your cinematic cast.</p>
            </div>
            <div className="space-y-10">
              <div className="space-y-3">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] block px-1">Production Aesthetic Seed</label>
                <input
                  type="text"
                  value={narrativeSeed}
                  onChange={(e) => setNarrativeSeed(e.target.value)}
                  placeholder="e.g. Gritty cyberpunk noir with anamorphic flares..."
                  className="w-full p-4 bg-slate-900 border border-white/5 rounded-2xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm text-white placeholder:text-slate-700 transition-all shadow-inner"
                />
              </div>

              <CharacterManager characters={characters || []} onUpdate={setCharacters} />

              <div className="space-y-3">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] block px-1">Lyrics / Storybeat Script</label>
                <textarea
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  placeholder="Paste your source text here..."
                  className="w-full h-80 p-8 bg-slate-900 border border-white/5 rounded-[2.5rem] focus:ring-1 focus:ring-blue-500/50 outline-none text-xl resize-none font-serif text-white shadow-inner leading-relaxed"
                />
              </div>

              <button
                type="button"
                onClick={() => setStep(AppStep.DEFINE_SCENES)}
                disabled={!rawText.trim()}
                className="w-full py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl shadow-blue-500/20 transition-all hover:-translate-y-1 active:translate-y-0"
              >
                Proceed to Scene Layout <i className="fa-solid fa-arrow-right ml-2"></i>
              </button>
            </div>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-xl mx-auto py-12">
            <div className="text-center mb-8">
              <div className="inline-block px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/20 text-[10px] font-bold text-blue-400 uppercase tracking-[0.3em] mb-4">Phase 02: Pacing</div>
              <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase">Identify Scene <span className="text-blue-500">Breaks</span></h2>
              <p className="text-sm text-slate-400 font-medium leading-relaxed">Slice your script into visual segments. Click between lines to create markers.</p>
            </div>
            <div className="space-y-1 bg-slate-900/50 p-8 rounded-[3rem] border border-white/5 shadow-2xl">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button onClick={() => toggleMarker(idx)} className="w-full py-3 flex items-center justify-center group relative outline-none">
                      <div className={`h-[2px] transition-all duration-300 ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.6)]' : 'w-1/6 bg-white/5 group-hover:w-full group-hover:bg-white/20'}`}></div>
                      <div className={`absolute text-[8px] font-bold uppercase tracking-widest transition-opacity duration-300 ${sceneMarkers.includes(idx) ? 'opacity-100 text-blue-400' : 'opacity-0 text-white/40'}`}>Break Point</div>
                    </button>
                  )}
                  <div className={`text-center py-2 font-serif text-slate-400 transition-all duration-500 ${sceneMarkers.includes(idx) ? 'pt-6 text-white font-black text-lg scale-105' : 'text-sm'}`}>{line}</div>
                </React.Fragment>
              ))}
            </div>
            <div className="mt-12 flex gap-4">
              <button onClick={() => setStep(AppStep.PASTE_LYRICS)} className="flex-1 py-4 bg-white/5 border border-white/10 text-slate-400 hover:text-white rounded-2xl font-bold uppercase tracking-widest transition-all">Back</button>
              <button onClick={handleProceedToProduction} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-600/20 transition-all hover:scale-[1.02]">Generate Drafts</button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            {isCharModalOpen && (
              <div className="fixed inset-0 z-[150] bg-black/90 backdrop-blur-xl flex items-center justify-center p-6">
                <div className="bg-slate-900 border border-white/10 w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl space-y-8">
                  <div className="flex justify-between items-center">
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Edit Production <span className="text-blue-500">Cast</span></h3>
                    <button onClick={() => setIsCharModalOpen(false)} className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 hover:text-white transition-colors">
                      <i className="fa-solid fa-xmark"></i>
                    </button>
                  </div>
                  <CharacterManager characters={characters} onUpdate={setCharacters} />
                  <div className="pt-6 flex justify-end">
                    <button onClick={() => setIsCharModalOpen(false)} className="px-10 py-3 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-blue-500/20">Apply Changes</button>
                  </div>
                </div>
              </div>
            )}
            <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
              <div>
                <div className="flex items-center gap-3 mb-2">
                  <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.4em]">Pre-Production Live</span>
                </div>
                <h2 className="text-5xl font-black text-white tracking-tighter uppercase">Director's <span className="text-blue-500">Board</span></h2>
                <div className="flex gap-6 mt-3">
                  <button onClick={() => setIsCharModalOpen(true)} className="text-[10px] font-black text-blue-500 hover:text-blue-400 uppercase tracking-widest flex items-center gap-2"><i className="fa-solid fa-user-gear"></i> Manage Cast</button>
