export default App;

import React, { useEffect, useState, useMemo } from 'react';
import { StoryboardSegment, Character } from '../types';
import MermaidChart from './MermaidChart';
import { generateSceneContent, generateDiagram } from '../services/geminiService';
import HighlightText from './HighlightText';

interface PresentationViewProps {
  segments: StoryboardSegment[];
  characters: Character[];
  currentIndex: number;
  onUpdateSegment: (index: number, updated: StoryboardSegment) => void;
  onNext: () => void;
  onPrev: () => void;
  onExit: () => void;
  narrativeSeed: string;
}

const PresentationView: React.FC<PresentationViewProps> = ({ 
  segments, 
  characters,
  currentIndex, 
  onUpdateSegment,
  onNext, 
  onPrev, 
  onExit,
  narrativeSeed
}) => {
  const current = segments[currentIndex];
  const [isRegenerating, setIsRegenerating] = useState(false);
  const [isPreviewMode, setIsPreviewMode] = useState(false);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.key === 'ArrowRight' || e.key === ' ') && (e.target as HTMLElement).tagName !== 'TEXTAREA' && (e.target as HTMLElement).tagName !== 'INPUT') {
        onNext();
      }
      if (e.key === 'ArrowLeft' && (e.target as HTMLElement).tagName !== 'TEXTAREA' && (e.target as HTMLElement).tagName !== 'INPUT') {
        onPrev();
      }
      if (e.key === 'Escape') onExit();
    };
    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [onNext, onPrev, onExit]);

  const handleFieldChange = (field: keyof StoryboardSegment, value: string) => {
    onUpdateSegment(currentIndex, { ...current, [field]: value });
  };

  const combinedText = useMemo(() => {
    if (!current) return '';
    return (current.visuals + ' ' + current.cameraWork + ' ' + current.lightingMood).toLowerCase();
  }, [current?.visuals, current?.cameraWork, current?.lightingMood]);

  const handleRegenerate = async () => {
    setIsRegenerating(true);
    try {
      const aiData = await generateSceneContent(current.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
      const updated = { ...current, ...aiData };
      const newDiagram = await generateDiagram(updated as StoryboardSegment);
      onUpdateSegment(currentIndex, { ...updated, mermaidDiagram: newDiagram });
    } catch (err) {
      console.error("Failed to regenerate scene:", err);
    } finally {
      setIsRegenerating(false);
    }
  };

  const insertCharacter = (field: keyof StoryboardSegment, name: string) => {
    const currentValue = (current[field] as string) || '';
    const newValue = currentValue.endsWith(' ') || currentValue === '' ? currentValue + name : currentValue + ' ' + name;
    handleFieldChange(field, newValue);
  };

  const CharacterShortcuts = ({ field }: { field: keyof StoryboardSegment }) => {
    if (!characters || characters.length === 0) return null;
    return (
      <div className="flex gap-1 overflow-x-auto max-w-[200px] no-scrollbar py-1">
        {characters.map(c => {
          const isMentioned = combinedText.includes(c.name.toLowerCase());
          return (
            <button 
              key={c.id}
              onClick={() => insertCharacter(field, c.name)}
              className={`text-[9px] border px-1.5 py-0.5 rounded transition-all whitespace-nowrap font-bold uppercase tracking-tighter
                ${isMentioned 
                  ? 'bg-blue-600/20 border-blue-500 text-blue-400 shadow-[0_0_10px_rgba(59,130,246,0.3)]' 
                  : 'bg-white/5 border-white/10 text-slate-500 hover:border-blue-500/50 hover:text-white'
                }`}
              title={`Mention ${c.name}`}
            >
              {c.name}
            </button>
          );
        })}
      </div>
    );
  };

  if (!current) return null;

  return (
    <div className="fixed inset-0 z-[100] bg-black text-white flex flex-col animate-in fade-in duration-500 overflow-hidden font-sans">
      {/* Header HUD */}
      <div className="p-4 flex justify-between items-center bg-zinc-900/80 border-b border-white/5">
        <div className="flex items-center gap-4">
          <button 
            onClick={onExit}
            className="w-10 h-10 rounded-xl bg-white/5 hover:bg-white/10 flex items-center justify-center transition-colors border border-white/10"
          >
            <i className="fa-solid fa-chevron-left text-xs"></i>
          </button>
          <div>
            <input 
              value={current.sectionTitle}
              onChange={(e) => handleFieldChange('sectionTitle', e.target.value)}
              className="bg-transparent border-none focus:ring-0 text-lg font-black text-blue-500 uppercase tracking-tighter p-0 w-64"
            />
            <p className="text-[10px] text-slate-500 uppercase tracking-widest font-bold">Cinema Mode • Frame {currentIndex + 1} / {segments.length}</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
           <button 
             onClick={() => setIsPreviewMode(!isPreviewMode)}
             className={`px-4 py-2 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all
               ${isPreviewMode ? 'bg-blue-600 border-blue-500 text-white shadow-lg shadow-blue-500/30' : 'bg-white/5 border-white/10 text-slate-400 hover:bg-white/10'}`}
           >
             <i className={`fa-solid ${isPreviewMode ? 'fa-eye' : 'fa-pen-to-square'} mr-2`}></i>
             {isPreviewMode ? 'Preview Mode' : 'Edit Mode'}
           </button>
           <button 
             onClick={handleRegenerate}
             disabled={isRegenerating}
             className="text-[10px] font-black text-blue-400 hover:text-blue-300 uppercase tracking-widest flex items-center gap-2 px-4 py-2 bg-blue-500/10 rounded-xl border border-blue-500/20 disabled:opacity-50 transition-all"
           >
             <i className={`fa-solid fa-wand-magic-sparkles ${isRegenerating ? 'animate-spin' : ''}`}></i>
             {isRegenerating ? 'Syncing...' : 'Redraft Scene'}
           </button>
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col md:flex-row p-4 md:p-8 gap-6 md:gap-10 min-h-0 overflow-y-auto md:overflow-hidden">
        {/* Left Side: Editorial */}
        <div className="w-full md:w-[45%] flex flex-col gap-8 md:overflow-y-auto pr-0 md:pr-4 custom-scrollbar">
          <div className="space-y-4">
             <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em]">Current Script</span>
             <blockquote className="text-xl md:text-3xl font-serif italic text-white leading-relaxed bg-zinc-900/40 p-6 md:p-10 rounded-[2.5rem] border border-white/5 shadow-inner">
               "{current.lyrics}"
             </blockquote>
          </div>

          <div className="space-y-8 pt-6 border-t border-white/10">
            <div>
               <div className="flex justify-between items-center mb-4">
                 <h4 className="text-[10px] font-black text-blue-500 uppercase tracking-widest flex items-center gap-2">
                   <i className="fa-solid fa-clapperboard"></i> Action Narrative
                 </h4>
                 {!isPreviewMode && <CharacterShortcuts field="visuals" />}
               </div>
               {isPreviewMode ? (
                 <div className="w-full bg-zinc-900/40 border border-white/5 rounded-[2rem] p-6 md:p-8 text-lg md:text-xl text-slate-200 leading-relaxed min-h-[140px] shadow-inner">
                   <HighlightText text={current.visuals} characters={characters} />
                 </div>
               ) : (
                 <textarea 
                    value={current.visuals}
                    onChange={(e) => handleFieldChange('visuals', e.target.value)}
                    className="w-full bg-zinc-950 border border-white/10 rounded-[2rem] p-6 text-base text-slate-300 leading-relaxed outline-none focus:border-blue-500/50 h-48 resize-none shadow-inner"
                    placeholder="Describe the cinematic action..."
                 />
               )}
            </div>

            <div className="flex flex-col gap-8">
              <div>
                <div className="flex justify-between items-center mb-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <i className="fa-solid fa-video"></i> Camera Configuration
                  </h4>
                  {!isPreviewMode && <CharacterShortcuts field="cameraWork" />}
                </div>
                {isPreviewMode ? (
                  <div className="w-full bg-zinc-900/40 border border-white/5 rounded-[1.5rem] p-5 text-sm font-medium text-slate-300 min-h-[100px] shadow-inner">
                    <HighlightText text={current.cameraWork} characters={characters} />
                  </div>
                ) : (
                  <textarea 
                    value={current.cameraWork}
                    onChange={(e) => handleFieldChange('cameraWork', e.target.value)}
                    rows={4}
                    className="w-full bg-zinc-950 border border-white/10 rounded-[1.5rem] p-5 text-sm font-medium text-slate-300 outline-none focus:border-blue-500/50 resize-none shadow-inner"
                    placeholder="Lens, movement, focus..."
                  />
                )}
              </div>
              <div>
                <div className="flex justify-between items-center mb-3">
                  <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                    <i className="fa-solid fa-lightbulb"></i> Lighting Setup
                  </h4>
                  {!isPreviewMode && <CharacterShortcuts field="lightingMood" />}
                </div>
                {isPreviewMode ? (
                  <div className="w-full bg-zinc-900/40 border border-white/5 rounded-[1.5rem] p-5 text-sm font-medium text-slate-300 min-h-[100px] shadow-inner">
                    <HighlightText text={current.lightingMood} characters={characters} />
                  </div>
                ) : (
                  <textarea 
                    value={current.lightingMood}
                    onChange={(e) => handleFieldChange('lightingMood', e.target.value)}
                    rows={4}
                    className="w-full bg-zinc-950 border border-white/10 rounded-[1.5rem] p-5 text-sm font-medium text-slate-300 outline-none focus:border-blue-500/50 resize-none shadow-inner"
                    placeholder="Gaffer notes, color temps..."
                  />
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Right Side: Architecture - Responsive Diagram Box */}
        <div className="w-full md:flex-1 flex flex-col bg-zinc-950/80 rounded-[3rem] border border-white/10 shadow-2xl overflow-hidden min-h-[500px] md:min-h-0 relative">
          <div className="p-6 border-b border-white/5 flex justify-between items-center shrink-0">
             <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Architectural Map</h4>
             <button 
              onClick={async () => {
                const diag = await generateDiagram(current);
                handleFieldChange('mermaidDiagram', diag);
              }}
              className="text-[10px] font-black text-blue-400 hover:text-blue-300 flex items-center gap-2 uppercase tracking-widest"
             >
               <i className="fa-solid fa-rotate"></i> Re-Route
             </button>
          </div>
          <div className="flex-1 overflow-auto p-6 md:p-10 flex items-start justify-center custom-scrollbar">
            {current.mermaidDiagram ? (
              <div className="w-full h-full min-h-[350px]">
                <MermaidChart chart={current.mermaidDiagram} id={`pres-${current.id}`} />
              </div>
            ) : (
              <div className="self-center flex flex-col items-center gap-6 text-slate-700">
                <div className="w-20 h-20 rounded-full bg-white/5 flex items-center justify-center border border-white/5">
                   <i className="fa-solid fa-diagram-project text-3xl opacity-20"></i>
                </div>
                <div className="text-center">
                   <p className="italic text-sm font-medium mb-1">Architecture pending sync</p>
                   <p className="text-[10px] uppercase font-bold tracking-widest opacity-40">Logical flow not yet calculated</p>
                </div>
                <button 
                  onClick={async () => {
                    const diag = await generateDiagram(current);
                    handleFieldChange('mermaidDiagram', diag);
                  }}
                  className="px-6 py-3 bg-white/5 rounded-2xl border border-white/10 text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-white transition-all"
                >
                  Sync Map Now
                </button>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* Footer Controls */}
      <div className="p-6 flex justify-between items-center bg-zinc-950 border-t border-white/10 shrink-0">
        <button 
          onClick={onPrev}
          disabled={currentIndex === 0}
          className="group flex items-center gap-4 px-6 md:px-8 py-3 rounded-2xl bg-white/5 hover:bg-white/10 disabled:opacity-10 transition-all border border-white/5"
        >
          <i className="fa-solid fa-arrow-left text-xs group-hover:-translate-x-1 transition-transform"></i>
          <span className="hidden md:inline text-[10px] font-black uppercase tracking-widest">Previous</span>
        </button>

        <div className="flex-1 flex justify-center gap-3">
          {(characters || []).map(c => {
            const isMentioned = combinedText.includes(c.name.toLowerCase());
            const charImg = c.images && c.images.length > 0 ? c.images[0] : null;
            return (
              <div 
                key={c.id} 
                className={`w-10 h-10 md:w-12 md:h-12 rounded-full border-2 transition-all overflow-hidden flex items-center justify-center shadow-lg
                  ${isMentioned 
                    ? 'border-blue-500 scale-125 shadow-[0_0_20px_rgba(59,130,246,0.6)]' 
                    : 'border-white/5 opacity-30 grayscale blur-[0.5px]'
                  }`}
                title={c.name}
              >
                {charImg ? (
                  <img src={charImg} alt={c.name} className="w-full h-full object-cover" />
                ) : (
                  <div className="w-full h-full bg-slate-800 flex items-center justify-center text-xs font-black uppercase">{c.name[0]}</div>
                )}
              </div>
            );
          })}
        </div>

        <button 
          onClick={onNext}
          disabled={currentIndex === segments.length - 1}
          className="group flex items-center gap-4 px-6 md:px-10 py-3 rounded-2xl bg-blue-600 hover:bg-blue-500 disabled:opacity-10 transition-all shadow-xl shadow-blue-500/30"
        >
          <span className="hidden md:inline text-[10px] font-black uppercase tracking-widest text-white">Next Frame</span>
          <i className="fa-solid fa-arrow-right text-xs text-white group-hover:translate-x-1 transition-transform"></i>
        </button>
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 5px;
          height: 5px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: rgba(255, 255, 255, 0.05);
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: rgba(255, 255, 255, 0.15);
        }
      `}</style>
    </div>
  );
};

export default PresentationView;

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { generateSceneContent, generateFrame } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import PresentationView from './components/PresentationView';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [currentSceneIndex, setCurrentSceneIndex] = useState(0);
  const [isCharModalOpen, setIsCharModalOpen] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
  const [isGeneratingFrames, setIsGeneratingFrames] = useState(false);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setErrorMessage(null);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);

    try {
      const populated = await Promise.all(newSegments.map(async (seg) => {
        try {
          const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
          return { ...seg, ...aiData };
        } catch (e: any) {
          if (e.message.includes('QUOTA')) {
            setErrorMessage("Some scenes couldn't be automatically populated due to API rate limits.");
          }
          return seg;
        }
      }));
      setSegments(populated);
    } catch (e) {
      console.error(e);
    } finally {
      setIsBulkProcessing(false);
    }
  };

  const handleProcessVisuals = async (sceneId: string) => {
    setActiveSceneId(sceneId);
    setErrorMessage(null);
    setStep(AppStep.FRAME_DEV);
    setIsGeneratingFrames(true);

    const segment = segments.find(s => s.id === sceneId);
    if (!segment) return;

    try {
      const [first, last] = await Promise.all([
        generateFrame(segment, characters, 'FIRST', narrativeSeed),
        generateFrame(segment, characters, 'LAST', narrativeSeed)
      ]);

      setSegments(prev => prev.map(s => 
        s.id === sceneId ? { ...s, firstFrame: first, lastFrame: last } : s
      ));
    } catch (err: any) {
      console.error("Frame generation failed:", err);
      if (err.message.includes('QUOTA')) {
        setErrorMessage("Visual generation limit reached. Please wait a few seconds.");
      } else {
        setErrorMessage("Visual generation failed. Ensure your character photos are valid.");
      }
    } finally {
      setIsGeneratingFrames(false);
    }
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const extractCharactersFromText = (text: string) => {
    return (characters || [])
      .filter(char => {
        const regex = new RegExp(`\\b${char.name}\\b`, 'i');
        return regex.test(text);
      })
      .map(char => char.name);
  };

  const saveProject = () => {
    const updatedSegments = segments.map(seg => ({
      ...seg,
      characters: extractCharactersFromText(seg.visuals + ' ' + seg.cameraWork + ' ' + seg.lightingMood)
    }));

    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments: updatedSegments,
      characters: characters || [],
      step,
      version: "1.5.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-bundle-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => fileInputRef.current?.click();

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText || '');
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);
        setStep(AppStep.PRODUCTION);
      } catch (err) {
        alert("Failed to load project file.");
      }
    };
    reader.readAsText(file);
    e.target.value = ''; 
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0 || !activeCharId) return;

    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        setCharacters(prev => prev.map(c => 
          c.id === activeCharId 
            ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } 
            : c
        ));
      };
      reader.readAsDataURL(file);
    });

    setActiveCharId(null);
    e.target.value = '';
  };

  const handlePrint = () => {
    window.print();
  };

  const activeSegment = segments.find(s => s.id === activeSceneId);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200 selection:bg-blue-500/30">
      {step === AppStep.PRESENTATION && (
        <PresentationView 
          segments={segments}
          characters={characters}
          currentIndex={currentSceneIndex}
          onUpdateSegment={updateSegment}
          onNext={() => setCurrentSceneIndex(p => Math.min(segments.length - 1, p + 1))}
          onPrev={() => setCurrentSceneIndex(p => Math.max(0, p - 1))}
          onExit={() => setStep(AppStep.PRODUCTION)}
          narrativeSeed={narrativeSeed}
        />
      )}

      {/* Hidden Print Layout */}
      <div className="print-only p-8 text-black bg-white">
        <h1 className="text-4xl font-black uppercase mb-2">LyricLens Production Bundle</h1>
        <p className="text-sm font-bold text-gray-500 mb-8 uppercase tracking-widest">Master Storyboard Document • {new Date().toLocaleDateString()}</p>

        {segments.map((seg, idx) => (
          <div key={seg.id} className={`mb-12 border-t-2 border-gray-100 pt-8 ${idx % 2 === 0 && idx !== 0 ? 'page-break' : ''}`}>
            <div className="flex justify-between items-start mb-6">
              <h2 className="text-2xl font-black uppercase">{seg.sectionTitle}</h2>
              <div className="text-right">
                <span className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Scene {idx + 1} of {segments.length}</span>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-4 mb-8">
              <div className="aspect-video bg-gray-100 border border-gray-200 rounded-lg overflow-hidden flex items-center justify-center">
                {seg.firstFrame ? (
                  <img src={seg.firstFrame} className="w-full h-full object-cover" />
                ) : (
                  <span className="text-xs font-bold text-gray-400 uppercase">First Frame Pending</span>
                )}
              </div>
              <div className="aspect-video bg-gray-100 border border-gray-200 rounded-lg overflow-hidden flex items-center justify-center">
                {seg.lastFrame ? (
                  <img src={seg.lastFrame} className="w-full h-full object-cover" />
                ) : (
                  <span className="text-xs font-bold text-gray-400 uppercase">Last Frame Pending</span>
                )}
              </div>
            </div>

            <div className="grid grid-cols-3 gap-8">
              <div>
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2">Source Lyrics</h4>
                <p className="text-sm italic border-l-2 border-blue-500 pl-4">{seg.lyrics}</p>
              </div>
              <div className="col-span-2 grid grid-cols-1 gap-4">
                <div>
                   <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Visuals</h4>
                   <p className="text-sm font-medium">{seg.visuals}</p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Camera</h4>
                    <p className="text-xs text-gray-600">{seg.cameraWork}</p>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Lighting</h4>
                    <p className="text-xs text-gray-600">{seg.lightingMood}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-white/5 no-print">
        <div className="max-w-7xl mx-auto px-6 py-3 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center shadow-lg shadow-blue-500/30 cursor-pointer hover:scale-105 transition-transform" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
              <i className="fa-solid fa-clapperboard text-white text-sm"></i>
            </div>
            <h1 className="text-lg font-black tracking-tighter uppercase italic">LyricLens <span className="text-blue-500">Studio</span></h1>
          </div>

          <div className="flex items-center gap-4">
            <div className="hidden md:flex items-center gap-2 mr-4">
              {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.PRODUCTION, AppStep.RESOURCES].map((s, idx) => (
                <React.Fragment key={s}>
                  <div 
                    className={`text-[10px] font-bold uppercase tracking-widest cursor-pointer hover:text-blue-400 transition-colors ${step === s ? 'text-blue-500 border-b-2 border-blue-500 pb-1' : 'text-slate-600'}`}
                    onClick={() => setStep(s)}
                  >
                    {s.replace('_', ' ')}
                  </div>
                  {idx < 3 && <div className="w-4 h-[1px] bg-white/10"></div>}
                </React.Fragment>
              ))}
            </div>

            <input type="file" ref={fileInputRef} onChange={loadProject} accept=".json" className="hidden" />

            <div className="flex items-center gap-2 border-l border-white/10 pl-4">
              <button onClick={handleLoadClick} className="p-2 text-slate-400 hover:text-white transition-colors flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider"><i className="fa-solid fa-folder-open"></i> Load</button>
              <button onClick={saveProject} className="p-2 text-blue-400 hover:text-blue-300 transition-colors flex items-center gap-2 text-[10px] font-bold uppercase tracking-wider"><i className="fa-solid fa-floppy-disk"></i> Save Bundle</button>
            </div>
          </div>
        </div>
      </header>

      {errorMessage && (
        <div className="fixed top-16 left-0 right-0 z-[60] bg-red-600 border-b border-red-500 p-2 text-center animate-in slide-in-from-top duration-300 no-print">
           <p className="text-[10px] font-black text-white uppercase tracking-[0.2em] flex items-center justify-center gap-3">
             <i className="fa-solid fa-triangle-exclamation"></i> {errorMessage}
             <button onClick={() => setErrorMessage(null)} className="ml-4 bg-white/20 px-2 py-0.5 rounded hover:bg-white/30">Dismiss</button>
           </p>
        </div>
      )}

      <main className="max-w-7xl mx-auto px-6 py-8 no-print">
        {step === AppStep.PASTE_LYRICS && (
          <div className="animate-in fade-in zoom-in-95 duration-500 max-w-2xl mx-auto py-12">
            <div className="text-center mb-12">
              <div className="inline-block px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/20 text-[10px] font-bold text-blue-400 uppercase tracking-[0.3em] mb-4">Phase 01: Setup</div>
              <h2 className="text-5xl font-black text-white mb-4 tracking-tighter uppercase">Directing <span className="text-blue-500">Desk</span></h2>
              <p className="text-slate-400 font-medium">Set the creative direction and define your cinematic cast.</p>
            </div>
            <div className="space-y-10">
              <div className="space-y-3">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] block px-1">Production Aesthetic Seed</label>
                <input
                  type="text"
                  value={narrativeSeed}
                  onChange={(e) => setNarrativeSeed(e.target.value)}
                  placeholder="e.g. Gritty cyberpunk noir with anamorphic flares..."
                  className="w-full p-4 bg-slate-900 border border-white/5 rounded-2xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm text-white placeholder:text-slate-700 transition-all shadow-inner"
                />
              </div>

              <CharacterManager characters={characters || []} onUpdate={setCharacters} />

              <div className="space-y-3">
                <label className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] block px-1">Lyrics / Storybeat Script</label>
                <textarea
                  value={rawText}
                  onChange={(e) => setRawText(e.target.value)}
                  placeholder="Paste your source text here..."
                  className="w-full h-80 p-8 bg-slate-900 border border-white/5 rounded-[2.5rem] focus:ring-1 focus:ring-blue-500/50 outline-none text-xl resize-none font-serif text-white shadow-inner leading-relaxed"
                />
              </div>

              <button
                type="button"
                onClick={() => setStep(AppStep.DEFINE_SCENES)}
                disabled={!rawText.trim()}
                className="w-full py-5 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 text-white rounded-2xl font-black uppercase tracking-widest shadow-2xl shadow-blue-500/20 transition-all hover:-translate-y-1 active:translate-y-0"
              >
                Proceed to Scene Layout <i className="fa-solid fa-arrow-right ml-2"></i>
              </button>
            </div>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="animate-in fade-in slide-in-from-bottom-4 duration-500 max-w-xl mx-auto py-12">
            <div className="text-center mb-8">
              <div className="inline-block px-3 py-1 rounded-full bg-blue-500/10 border border-blue-500/20 text-[10px] font-bold text-blue-400 uppercase tracking-[0.3em] mb-4">Phase 02: Pacing</div>
              <h2 className="text-4xl font-black text-white mb-4 tracking-tighter uppercase">Identify Scene <span className="text-blue-500">Breaks</span></h2>
              <p className="text-sm text-slate-400 font-medium leading-relaxed">Slice your script into visual segments. Click between lines to create markers.</p>
            </div>
            <div className="space-y-1 bg-slate-900/50 p-8 rounded-[3rem] border border-white/5 shadow-2xl">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button onClick={() => toggleMarker(idx)} className="w-full py-3 flex items-center justify-center group relative outline-none">
                      <div className={`h-[2px] transition-all duration-300 ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_15px_rgba(59,130,246,0.6)]' : 'w-1/6 bg-white/5 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                      <div className={`absolute text-[8px] font-bold uppercase tracking-widest transition-opacity duration-300 ${sceneMarkers.includes(idx) ? 'opacity-100 text-blue-400' : 'opacity-0 text-white/40'}`}>Break Point</div>
                    </button>
                  )}
                  <div className={`text-center py-2 font-serif text-slate-400 transition-all duration-500 ${sceneMarkers.includes(idx) ? 'pt-6 text-white font-black text-lg scale-105' : 'text-sm'}`}>{line}</div>
                </React.Fragment>
              ))}
            </div>
            <div className="mt-12 flex gap-4">
              <button onClick={() => setStep(AppStep.PASTE_LYRICS)} className="flex-1 py-4 bg-white/5 border border-white/10 text-slate-400 hover:text-white rounded-2xl font-bold uppercase tracking-widest transition-all">Back</button>
              <button onClick={handleProceedToProduction} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-600/20 transition-all hover:scale-[1.02]">Generate Drafts</button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            {isCharModalOpen && (
              <div className="fixed inset-0 z-[150] bg-black/90 backdrop-blur-xl flex items-center justify-center p-6 no-print">
                <div className="bg-slate-900 border border-white/10 w-full max-w-2xl rounded-[3rem] p-10 shadow-2xl space-y-8">
                  <div className="flex justify-between items-center">
                    <h3 className="text-2xl font-black text-white uppercase tracking-tighter">Edit Production <span className="text-blue-500">Cast</span></h3>
                    <button onClick={() => setIsCharModalOpen(false)} className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center text-slate-400 hover:text-white transition-colors">
                      <i className="fa-solid fa-xmark"></i>
                    </button>
                  </div>
                  <CharacterManager characters={characters} onUpdate={setCharacters} />
                  <div className="pt-6 flex justify-end">
                    <button onClick={() => setIsCharModalOpen(false)} className="px-10 py-3 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-blue-500/20">Apply Changes</button>
                  </div>
                </div>
              </div>
            )}
            <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
              <div>
                <div className="flex items-center gap-3 mb-2">
                  <div className="w-2 h-2 rounded-full bg-red-500 animate-pulse"></div>
                  <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.4em]">Pre-Production Live</span>
                </div>
                <h2 className="text-5xl font-black text-white tracking-tighter uppercase">Director's <span className="text-blue-500">Board</span></h2>
                <div className="flex gap-6 mt-3">
                  <button onClick={() => setIsCharModalOpen(true)} className="text-[10px] font-black text-blue-500 hover:text-blue-400 uppercase tracking-widest flex items-center gap-2 transition-colors"><i className="fa-solid fa-user-gear"></i> Manage Cast</button>
                  <button onClick={saveProject} className="text-[10px] font-black text-slate-500 hover:text-white uppercase tracking-widest flex items-center gap-2 transition-colors"><i className="fa-solid fa-cloud-arrow-up"></i> Export Bundle</button>
                  <button onClick={handlePrint} className="text-[10px] font-black text-emerald-500 hover:text-emerald-400 uppercase tracking-widest flex items-center gap-2 transition-colors"><i className="fa-solid fa-file-pdf"></i> Print Storyboard</button>
                </div>
              </div>
