                   <p className="text-[10px] font-black uppercase tracking-widest text-gray-400">A: Start Shot</p>
                   <div className="aspect-video bg-gray-50 border-2 border-gray-100 rounded-2xl overflow-hidden flex items-center justify-center shadow-sm">
                    {seg.firstFrame ? (
                      <img src={seg.firstFrame} className="w-full h-full object-cover" />
