                      <div className={`absolute text-[8px] font-bold uppercase tracking-widest transition-opacity duration-300 ${sceneMarkers.includes(idx) ? 'opacity-100 text-blue-400' : 'opacity-0 text-white/40'}`}>Break Point</div>
