import { GoogleGenAI, Type } from "@google/genai";
import { StoryboardSegment, Character } from "../types";

// Always use const ai = new GoogleGenAI({apiKey: process.env.API_KEY});
const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const generateSceneContent = async (
  lyrics: string, 
  context: string, 
  seed: string, 
  characters: Character[]
): Promise<Partial<StoryboardSegment>> => {
  const charContext = characters.length > 0 
    ? `CHARACTERS IN STORY: ${characters.map(c => c.name).join(', ')}.` 
    : '';

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `As a video director, provide visual instructions for this specific song segment.

      NARRATIVE ANGLE/DIRECTION: ${seed || "Cinematic and faithful to the lyrics"}
      ${charContext}

      CONTEXT: ${context}
      SEGMENT LYRICS: ${lyrics}`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            visuals: { type: Type.STRING, description: "Action happening in the scene. Use character names if applicable." },
            cameraWork: { type: Type.STRING, description: "Camera movement and angles" },
            lightingMood: { type: Type.STRING, description: "Lighting style and color palette" },
            sectionTitle: { type: Type.STRING, description: "Logical name (e.g. Verse 1)" }
          },
          required: ["visuals", "cameraWork", "lightingMood", "sectionTitle"]
        }
      }
    });

    // The GenerateContentResponse object features a text property (not a method)
    const text = response.text;
    if (!text) throw new Error("No response from AI");
    return JSON.parse(text.trim());
  } catch (error: any) {
    if (error?.message?.includes('429') || error?.status === 'RESOURCE_EXHAUSTED') {
      throw new Error("QUOTA_EXHAUSTED: API rate limit reached. Please wait a moment before trying again.");
    }
    throw error;
  }
};

export const generateDiagram = async (segment: StoryboardSegment): Promise<string> => {
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Create a Mermaid.js flowchart (graph TD) representing the cinematic flow of the following film scene. 

      STRICT SYNTAX RULES:
      1. Use 'graph TD'.
      2. ALL node labels MUST be wrapped in double quotes. 
         - CORRECT: A["Character @Name"]
         - INCORRECT: A[Character @Name]
      3. Do not use special characters outside of quotes.
      4. If a name starts with @, it MUST be inside double quotes.

      SCENE DESCRIPTION: ${segment.visuals}
      CAMERA: ${segment.cameraWork}`,
    });

    // Directly access the .text property
    return response.text || '';
  } catch (error: any) {
    if (error?.message?.includes('429')) throw new Error("QUOTA_EXHAUSTED");
    throw error;
  }
};

export const generateFrame = async (
  segment: StoryboardSegment, 
  characters: Character[],
  type: 'FIRST' | 'LAST',
  seed: string
): Promise<string> => {
  const model = 'gemini-2.5-flash-image';

  const mentionedChars = characters.filter(c => 
    segment.visuals.toLowerCase().includes(c.name.toLowerCase()) ||
    segment.cameraWork.toLowerCase().includes(c.name.toLowerCase())
  );

  const parts: any[] = [];

  mentionedChars.forEach(char => {
    (char.images || []).slice(0, 2).forEach(img => {
      const parts_img = img.split(',');
      if (parts_img.length < 2) return;
      const base64Data = parts_img[1];
      const mimeType = parts_img[0].split(';')[0].split(':')[1];
      parts.push({
        inlineData: { data: base64Data, mimeType }
      });
    });
  });

  const prompt = `Generate a high-quality cinematic ${type} FRAME for a music video scene.
  SCENE DESCRIPTION: ${segment.visuals}
  CAMERA WORK: ${segment.cameraWork}
  LIGHTING & MOOD: ${segment.lightingMood}
  NARRATIVE DIRECTION: ${seed}

  The provided images are character references. Ensure characters match these references exactly.
  ${type === 'FIRST' ? 'Capture the starting moment.' : 'Capture the peak of motion.'}

  Style: Photorealistic, cinematic 35mm film.`;

  parts.push({ text: prompt });

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts },
      config: {
          imageConfig: { aspectRatio: "16:9" }
      }
    });

    // Find the image part, do not assume it is the first part.
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) {
        return `data:${part.inlineData.mimeType};base64,${part.inlineData.data}`;
      }
    }
  } catch (error: any) {
    if (error?.message?.includes('429')) throw new Error("QUOTA_EXHAUSTED");
    throw error;
  }

  throw new Error("No image generated");
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { generateSceneContent, generateFrame } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import PresentationView from './components/PresentationView';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [isBulkProcessing, setIsBulkProcessing] = useState(false);
  const [currentSceneIndex, setCurrentSceneIndex] = useState(0);
  const [isCharModalOpen, setIsCharModalOpen] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
  const [isGeneratingFrames, setIsGeneratingFrames] = useState(false);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleProceedToProduction = async () => {
    setIsBulkProcessing(true);
    setErrorMessage(null);
    setStep(AppStep.PRODUCTION);

    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);

    try {
      const populated = await Promise.all(newSegments.map(async (seg) => {
        try {
          const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
          return { ...seg, ...aiData };
        } catch (e: any) {
          if (e.message.includes('QUOTA')) {
            setErrorMessage("Some scenes couldn't be automatically populated due to API rate limits.");
          }
          return seg;
        }
      }));
      setSegments(populated);
    } catch (e) {
      console.error(e);
    } finally {
      setIsBulkProcessing(false);
    }
  };

  const handleProcessVisuals = async (sceneId: string) => {
    setActiveSceneId(sceneId);
    setErrorMessage(null);
    setStep(AppStep.FRAME_DEV);
    setIsGeneratingFrames(true);

    const segment = segments.find(s => s.id === sceneId);
    if (!segment) return;

    try {
      const [first, last] = await Promise.all([
        generateFrame(segment, characters, 'FIRST', narrativeSeed),
        generateFrame(segment, characters, 'LAST', narrativeSeed)
      ]);

      setSegments(prev => prev.map(s => 
        s.id === sceneId ? { ...s, firstFrame: first, lastFrame: last } : s
      ));
    } catch (err: any) {
      console.error("Frame generation failed:", err);
      if (err.message.includes('QUOTA')) {
        setErrorMessage("Visual generation limit reached. Please wait a few seconds.");
      } else {
        setErrorMessage("Visual generation failed. Ensure your character photos are valid.");
      }
    } finally {
      setIsGeneratingFrames(false);
    }
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const extractCharactersFromText = (text: string) => {
    return (characters || [])
      .filter(char => {
        const regex = new RegExp(`\\b${char.name}\\b`, 'i');
        return regex.test(text);
      })
      .map(char => char.name);
  };

  const saveProject = () => {
    const updatedSegments = segments.map(seg => ({
      ...seg,
      characters: extractCharactersFromText(seg.visuals + ' ' + seg.cameraWork + ' ' + seg.lightingMood)
    }));

    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments: updatedSegments,
      characters: characters || [],
      step,
      version: "1.6.0"
    };
    // The JSONified bundle includes all assets (base64 images)
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-codified-bundle-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

