      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        setCharacters(prev => prev.map(c => 
          c.id === activeCharId 
            ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } 
            : c
        ));
      };
      reader.readAsDataURL(file);
    });

    setActiveCharId(null);
    e.target.value = '';
  };

  const handlePrint = () => {
    window.print();
  };

