                  <div className="grid grid-cols-2 gap-8">
                    <div>
                      <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2">Camera Logic</h4>
                      <p className="text-xs text-gray-600 leading-relaxed font-medium">{seg.cameraWork}</p>
                    </div>
                    <div>
                      <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em] mb-2">Atmospheric Palette</h4>
                      <p className="text-xs text-gray-600 leading-relaxed font-medium">{seg.lightingMood}</p>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          ))}
        </div>

        <div className="mt-20 pt-10 border-t-2 border-black flex justify-between items-center text-[10px] font-bold uppercase tracking-widest text-gray-400">
           <span>Production Bundle Export</span>
           <span>Generated via LyricLens AI Suite</span>
           <span>Page {currentSceneIndex + 1} of {Math.ceil(segments.length / 2)}</span>
        </div>
      </div>

