                           </div>
                           <div className="text-center space-y-2">
                             <p className="text-[10px] text-blue-400 font-black uppercase tracking-[0.3em] animate-pulse">Analyzing References</p>
                             <p className="text-[9px] text-slate-700 uppercase font-bold tracking-widest">Injecting Continuity Anchors...</p>
                           </div>
                        </div>
                      )}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex justify-between items-center px-4">
                      <div className="flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-indigo-500 shadow-[0_0_8px_rgba(99,102,241,0.8)]"></div>
                        <span className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em]">B: Peak Motion</span>
                      </div>
                      {isGeneratingFrames && <i className="fa-solid fa-circle-notch animate-spin text-slate-600 text-xs"></i>}
                   </div>
                   <div className="aspect-video bg-black border border-white/10 rounded-[2.5rem] overflow-hidden shadow-[0_0_50px_rgba(99,102,241,0.1)] group/frame relative ring-1 ring-white/5">
                      {activeSegment.lastFrame ? (
                        <div className="relative w-full h-full overflow-hidden">
                           <img src={activeSegment.lastFrame} className="w-full h-full object-cover animate-in fade-in zoom-in duration-1000" />
                           <div className="absolute inset-0 bg-indigo-500/5 pointer-events-none"></div>
                           <div className="absolute top-6 left-6 px-3 py-1 bg-black/60 backdrop-blur-md border border-white/10 rounded-full text-[8px] font-bold text-white uppercase tracking-widest">Motion Keyframe - Extrapolated</div>
                        </div>
                      ) : (
                        <div className="w-full h-full flex flex-col items-center justify-center space-y-6 p-12 bg-zinc-950">
                           <div className="relative">
                              <div className="w-20 h-20 border-t-2 border-l-2 border-indigo-500/40 rounded-full animate-spin direction-reverse"></div>
                              <div className="absolute inset-0 flex items-center justify-center">
                                 <i className="fa-solid fa-wind text-indigo-500/20 text-2xl"></i>
                              </div>
                           </div>
                           <div className="text-center space-y-2">
                             <p className="text-[10px] text-indigo-400 font-black uppercase tracking-[0.3em] animate-pulse">Calculating Motion</p>
                             <p className="text-[9px] text-slate-700 uppercase font-bold tracking-widest">Extrapolating Cinematic Depth...</p>
                           </div>
                        </div>
                      )}
                   </div>
                </div>
             </div>

             <div className="p-10 bg-slate-950 border border-white/10 rounded-[3.5rem] shadow-2xl relative overflow-hidden">
                <div className="absolute top-0 right-0 w-64 h-64 bg-blue-600/5 blur-[100px] pointer-events-none"></div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-12 relative">
                   <div>
                      <div className="flex items-center gap-3 mb-4">
                         <i className="fa-solid fa-clapperboard text-blue-500 text-xs"></i>
                         <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Visual Narrative</label>
                      </div>
                      <p className="text-sm text-slate-300 leading-relaxed font-medium">{activeSegment.visuals}</p>
                   </div>
                   <div>
                      <div className="flex items-center gap-3 mb-4">
                         <i className="fa-solid fa-video text-indigo-500 text-xs"></i>
                         <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Camera Dynamics</label>
                      </div>
                      <p className="text-sm text-slate-300 leading-relaxed font-medium">{activeSegment.cameraWork}</p>
                   </div>
                   <div>
                      <div className="flex items-center gap-3 mb-4">
                         <i className="fa-solid fa-lightbulb text-amber-500 text-xs"></i>
                         <label className="text-[10px] font-black text-slate-500 uppercase tracking-[0.3em]">Mood & Atmosphere</label>
                      </div>
                      <p className="text-sm text-slate-300 leading-relaxed font-medium">{activeSegment.lightingMood}</p>
                   </div>
                </div>
             </div>
          </div>
        )}
      </main>

      {/* Separate hidden input for character image uploads */}
      <input 
        type="file" 
        ref={imageInputRef} 
        onChange={handleImageUpload} 
        accept="image/*" 
        multiple
        className="hidden" 
      />

      <style>{`
        ::-webkit-scrollbar {
          width: 8px;
          height: 8px;
        }
        ::-webkit-scrollbar-track {
          background: #020617;
        }
        ::-webkit-scrollbar-thumb {
          background: #1e293b;
          border-radius: 10px;
        }
        ::-webkit-scrollbar-thumb:hover {
          background: #334155;
        }
      `}</style>
    </div>
  );
};

export default App;

export interface Character {
  id: string;
  name: string;
  images: string[]; // Support multiple reference images
}

export interface StoryboardSegment {
  id: string;
  sectionTitle: string;
  lyrics: string;
  visuals: string;
  cameraWork: string;
  lightingMood: string;
  mermaidDiagram?: string;
  isProcessing?: boolean;
  characters?: string[]; // Names of characters present
  firstFrame?: string; // Generated base64 image
  lastFrame?: string;  // Generated base64 image
}

export interface StoryboardProject {
  rawText: string;
  narrativeSeed: string;
  sceneMarkers: number[];
  segments: StoryboardSegment[];
  characters: Character[];
  step: AppStep;
  version: string;
}

export enum AppStep {
  PASTE_LYRICS = 'PASTE_LYRICS',
  DEFINE_SCENES = 'DEFINE_SCENES',
  RESOURCES = 'RESOURCES',
  PRODUCTION = 'PRODUCTION',
  FRAME_DEV = 'FRAME_DEV'
}

import React, { useState, useMemo, useRef } from 'react';
import { generateSceneContent, generateFrame } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
  const [isGeneratingFrames, setIsGeneratingFrames] = useState(false);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleCreateDrafts = async () => {
    setErrorMessage(null);
    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);
    setStep(AppStep.RESOURCES); // Move to Resources first to get refs
  };

  const handleGoToProduction = async () => {
    setStep(AppStep.PRODUCTION);
    if (segments.some(s => !s.visuals)) {
      // Bulk populate descriptions if empty
      try {
        const populated = await Promise.all(segments.map(async (seg) => {
          if (seg.visuals) return seg;
          try {
            const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
            return { ...seg, ...aiData };
          } catch (e) { return seg; }
        }));
        setSegments(populated);
      } catch (e) { console.error(e); }
    }
  };

  const handleProcessVisuals = async (sceneId: string) => {
    setActiveSceneId(sceneId);
    setErrorMessage(null);
    setStep(AppStep.FRAME_DEV);
    setIsGeneratingFrames(true);

    const segment = segments.find(s => s.id === sceneId);
    if (!segment) return;

    try {
      const [first, last] = await Promise.all([
        generateFrame(segment, characters, 'FIRST', narrativeSeed),
        generateFrame(segment, characters, 'LAST', narrativeSeed)
      ]);

      setSegments(prev => prev.map(s => 
        s.id === sceneId ? { ...s, firstFrame: first, lastFrame: last } : s
      ));
    } catch (err: any) {
      setErrorMessage(err.message.includes('QUOTA') ? "Limit reached. Wait a moment." : "Generation failed.");
    } finally {
      setIsGeneratingFrames(false);
    }
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const saveProject = () => {
    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments,
      characters,
      step,
      version: "2.0.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-bundle-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => fileInputRef.current?.click();

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText || '');
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);
        setStep(project.step || AppStep.PRODUCTION);
      } catch (err) { alert("Invalid project file."); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0 || !activeCharId) return;
    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        setCharacters(prev => prev.map(c => 
          c.id === activeCharId ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } : c
        ));
      };
      reader.readAsDataURL(file);
    });
    setActiveCharId(null);
    e.target.value = '';
  };

  const activeSegment = segments.find(s => s.id === activeSceneId);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {/* GLOBAL PRINT LAYOUT */}
      <div className="print-only">
        <div className="border-b-4 border-black pb-8 mb-12 flex justify-between items-end">
          <div>
            <h1 className="text-6xl font-black uppercase tracking-tighter">Production <span className="text-blue-600">Bundle</span></h1>
            <p className="text-lg font-bold text-gray-400 mt-2 uppercase tracking-widest">Master Storyboard • {new Date().toLocaleDateString()}</p>
          </div>
          <div className="text-right">
             <p className="text-sm font-black uppercase">LyricLens AI Suite</p>
             <p className="text-xs text-gray-400">Reference: {narrativeSeed || 'Untitled'}</p>
          </div>
        </div>
        {segments.map((seg, idx) => (
          <div key={seg.id} className="storyboard-strip">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-12 h-12 bg-black text-white flex items-center justify-center font-black text-2xl rounded-lg">{idx + 1}</div>
              <h2 className="text-3xl font-black uppercase tracking-tight">{seg.sectionTitle}</h2>
            </div>
            <div className="grid grid-cols-2 gap-6 mb-10">
              <div className="aspect-video bg-gray-50 border border-gray-100 rounded-xl overflow-hidden shadow-sm">
                {seg.firstFrame && <img src={seg.firstFrame} className="w-full h-full object-cover" />}
              </div>
              <div className="aspect-video bg-gray-50 border border-gray-100 rounded-xl overflow-hidden shadow-sm">
                {seg.lastFrame && <img src={seg.lastFrame} className="w-full h-full object-cover" />}
              </div>
            </div>
            <div className="grid grid-cols-12 gap-10">
              <div className="col-span-4">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 border-b border-gray-100 pb-1">Script Context</h4>
                <p className="text-sm font-serif italic text-gray-700 leading-relaxed bg-gray-50 p-4 rounded-xl border border-gray-100">"{seg.lyrics}"</p>
              </div>
              <div className="col-span-8 space-y-4">
                <div>
                   <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Visual Action</h4>
                   <p className="text-sm font-bold text-gray-900">{seg.visuals}</p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Camera</h4>
                    <p className="text-xs text-gray-600">{seg.cameraWork}</p>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Atmosphere</h4>
                    <p className="text-xs text-gray-600">{seg.lightingMood}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-white/5 no-print px-6 py-3 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/30 cursor-pointer" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
            <i className="fa-solid fa-clapperboard text-white text-xs"></i>
          </div>
          <h1 className="text-md font-black tracking-tighter uppercase italic">LyricLens <span className="text-blue-500">Studio</span></h1>
        </div>
        <div className="flex items-center gap-4">
          <div className="hidden md:flex items-center gap-4 mr-4">
            {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.RESOURCES, AppStep.PRODUCTION].map((s) => (
              <div key={s} className={`text-[10px] font-bold uppercase tracking-widest cursor-pointer ${step === s ? 'text-blue-500 border-b-2 border-blue-500 pb-1' : 'text-slate-600'}`} onClick={() => setStep(s)}>{s.replace('_', ' ')}</div>
            ))}
          </div>
          <input type="file" ref={fileInputRef} onChange={loadProject} accept=".json" className="hidden" />
          <button onClick={handleLoadClick} className="p-2 text-slate-400 hover:text-white transition-colors text-[10px] font-bold uppercase"><i className="fa-solid fa-folder-open"></i></button>
          <button onClick={saveProject} className="p-2 text-blue-400 hover:text-white transition-colors text-[10px] font-bold uppercase"><i className="fa-solid fa-floppy-disk"></i></button>
        </div>
      </header>

      {errorMessage && (
        <div className="fixed top-14 left-0 right-0 z-[60] bg-red-600 p-2 text-center no-print">
           <p className="text-[10px] font-black text-white uppercase tracking-widest">{errorMessage}</p>
        </div>
      )}

      <main className="max-w-7xl mx-auto px-6 py-8 no-print">
        {step === AppStep.PASTE_LYRICS && (
          <div className="max-w-2xl mx-auto py-12 animate-in fade-in zoom-in-95 duration-500">
            <div className="text-center mb-10">
              <h2 className="text-5xl font-black text-white mb-4 tracking-tighter uppercase">Director's <span className="text-blue-500">Input</span></h2>
              <p className="text-slate-400 font-medium">Define your narrative core and production seed.</p>
            </div>
            <div className="space-y-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Aesthetic Seed</label>
                <input type="text" value={narrativeSeed} onChange={(e) => setNarrativeSeed(e.target.value)} placeholder="e.g. Gritty 35mm film noir, neon highlights..." className="w-full p-4 bg-slate-900 border border-white/5 rounded-2xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm text-white" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Lyrics / Story Script</label>
                <textarea value={rawText} onChange={(e) => setRawText(e.target.value)} placeholder="Paste your song text here..." className="w-full h-80 p-8 bg-slate-900 border border-white/5 rounded-3xl focus:ring-1 focus:ring-blue-500/50 outline-none text-xl font-serif text-white resize-none shadow-inner" />
              </div>
              <button onClick={() => setStep(AppStep.DEFINE_SCENES)} disabled={!rawText.trim()} className="w-full py-5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-500/20">Next: Define Breaks <i className="fa-solid fa-arrow-right ml-2"></i></button>
            </div>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="max-w-xl mx-auto py-12 animate-in fade-in duration-500">
            <div className="text-center mb-8">
              <h2 className="text-4xl font-black text-white mb-2 uppercase">Scene <span className="text-blue-500">Pacing</span></h2>
              <p className="text-sm text-slate-400">Click between lines to create scene breaks.</p>
            </div>
            <div className="bg-slate-900/50 p-6 rounded-[2.5rem] border border-white/5 space-y-1">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button onClick={() => toggleMarker(idx)} className="w-full py-2 group relative">
                      <div className={`h-[2px] transition-all ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'w-1/6 bg-white/5 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                    </button>
                  )}
                  <div className={`text-center py-2 font-serif transition-all ${sceneMarkers.includes(idx) ? 'text-white font-black text-lg' : 'text-slate-400 text-sm'}`}>{line}</div>
                </React.Fragment>
              ))}
            </div>
            <div className="mt-10 flex gap-4">
              <button onClick={() => setStep(AppStep.PASTE_LYRICS)} className="flex-1 py-4 bg-white/5 rounded-2xl font-bold uppercase tracking-widest">Back</button>
              <button onClick={handleCreateDrafts} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest">Next: Moodboard</button>
            </div>
          </div>
        )}

        {step === AppStep.RESOURCES && (
          <div className="max-w-4xl mx-auto py-8 animate-in fade-in duration-500">
            <div className="text-center mb-12">
               <h2 className="text-5xl font-black text-white mb-4 tracking-tighter uppercase">Visual <span className="text-blue-500">Anchors</span></h2>
               <p className="text-slate-400 font-medium">Define your cast and upload references for AI continuity.</p>
            </div>
            <div className="bg-slate-900/50 p-10 rounded-[3rem] border border-white/5 shadow-2xl mb-12">
               <CharacterManager characters={characters} onUpdate={setCharacters} />
            </div>
            <div className="flex justify-center gap-6">
               <button onClick={() => setStep(AppStep.DEFINE_SCENES)} className="px-10 py-4 bg-white/5 rounded-2xl font-bold uppercase tracking-widest">Back</button>
               <button onClick={handleGoToProduction} className="px-12 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-500/20">Enter Production <i className="fa-solid fa-film ml-2"></i></button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
              <div>
                <h2 className="text-5xl font-black text-white tracking-tighter uppercase">Director's <span className="text-blue-500">Board</span></h2>
                <div className="flex gap-6 mt-4">
                  <button onClick={() => setStep(AppStep.RESOURCES)} className="text-[10px] font-black text-blue-500 uppercase tracking-widest flex items-center gap-2 transition-colors hover:text-blue-400"><i className="fa-solid fa-users"></i> Edit Cast</button>
                  <button onClick={window.print} className="text-[10px] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-2 transition-colors hover:text-emerald-400"><i className="fa-solid fa-file-pdf"></i> PDF Storyboard</button>
                </div>
              </div>
            </div>
            <div className="space-y-6">
              {segments.map((seg, idx) => (
                <StoryboardCard key={seg.id} segment={seg} characters={characters} onUpdate={(updated) => updateSegment(idx, updated)} onProcess={() => handleProcessVisuals(seg.id)} />
              ))}
            </div>
          </div>
        )}

        {step === AppStep.FRAME_DEV && activeSegment && (
          <div className="animate-in fade-in duration-500 max-w-5xl mx-auto py-12 space-y-12">
             <div className="bg-slate-900/80 p-8 rounded-[3rem] border border-white/10 flex justify-between items-center shadow-2xl backdrop-blur-md">
                <div>
                  <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-1">{activeSegment.sectionTitle}</h2>
                  <p className="text-xl text-slate-400 italic font-serif">"{activeSegment.lyrics}"</p>
                </div>
                <button onClick={() => setStep(AppStep.PRODUCTION)} className="px-8 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-lg shadow-blue-500/20"><i className="fa-solid fa-check mr-2"></i> Accept Visuals</button>
             </div>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-10">
                <div className="space-y-4">
                   <div className="flex justify-between items-center px-4"><span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Start Shot</span>{isGeneratingFrames && <i className="fa-solid fa-circle-notch animate-spin text-blue-500"></i>}</div>
                   <div className="aspect-video bg-black rounded-[2rem] overflow-hidden border border-white/5 relative shadow-2xl">
                      {activeSegment.firstFrame ? <img src={activeSegment.firstFrame} className="w-full h-full object-cover animate-in fade-in duration-1000" /> : <div className="w-full h-full flex items-center justify-center text-slate-700 animate-pulse uppercase font-black tracking-widest">Rendering...</div>}
                   </div>
                </div>
                <div className="space-y-4">
                   <div className="flex justify-between items-center px-4"><span className="text-[10px] font-black text-indigo-500 uppercase tracking-widest">Peak Motion</span>{isGeneratingFrames && <i className="fa-solid fa-circle-notch animate-spin text-indigo-500"></i>}</div>
                   <div className="aspect-video bg-black rounded-[2rem] overflow-hidden border border-white/5 relative shadow-2xl">
                      {activeSegment.lastFrame ? <img src={activeSegment.lastFrame} className="w-full h-full object-cover animate-in fade-in duration-1000" /> : <div className="w-full h-full flex items-center justify-center text-slate-700 animate-pulse uppercase font-black tracking-widest">Rendering...</div>}
                   </div>
                </div>
             </div>
          </div>
        )}
      </main>

      <input type="file" ref={imageInputRef} onChange={handleImageUpload} accept="image/*" multiple className="hidden" />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { StoryboardSegment, Character } from '../types';
import MermaidChart from './MermaidChart';
import { generateDiagram } from '../services/geminiService';

interface StoryboardCardProps {
  segment: StoryboardSegment;
  characters: Character[];
  onUpdate: (updated: StoryboardSegment) => void;
  onRemove?: () => void;
  onProcess?: () => void;
}

const StoryboardCard: React.FC<StoryboardCardProps> = ({ segment, characters, onUpdate, onRemove, onProcess }) => {
  const [isGeneratingDiagram, setIsGeneratingDiagram] = useState(false);

  const handleChange = (field: keyof StoryboardSegment, value: string) => {
    onUpdate({ ...segment, [field]: value });
  };

  const combinedText = useMemo(() => {
    return (segment.visuals + ' ' + segment.cameraWork + ' ' + segment.lightingMood).toLowerCase();
  }, [segment.visuals, segment.cameraWork, segment.lightingMood]);

  const handleBuildDiagram = async () => {
    setIsGeneratingDiagram(true);
    try {
      const diagram = await generateDiagram(segment);
      onUpdate({ ...segment, mermaidDiagram: diagram });
    } catch (err) { console.error(err); } finally { setIsGeneratingDiagram(false); }
  };

  const insertCharacter = (field: keyof StoryboardSegment, name: string) => {
    const currentValue = (segment[field] as string) || '';
    const newValue = currentValue.endsWith(' ') || currentValue === '' ? currentValue + name : currentValue + ' ' + name;
    handleChange(field, newValue);
  };

  const CharacterShortcuts = ({ field }: { field: keyof StoryboardSegment }) => {
    if (!characters || characters.length === 0) return null;
    return (
      <div className="flex gap-1 overflow-x-auto max-w-[200px] no-scrollbar">
        {characters.map(c => (
          <button key={c.id} onClick={() => insertCharacter(field, c.name)} className={`text-[8px] border px-2 py-0.5 rounded uppercase font-bold tracking-tighter transition-all ${combinedText.includes(c.name.toLowerCase()) ? 'bg-blue-600/30 border-blue-400 text-blue-300' : 'bg-slate-900 border-slate-700 text-slate-500'}`}>
            {c.name}
          </button>
        ))}
      </div>
    );
  };

  return (
    <div className="group bg-slate-800/40 border border-slate-700/50 rounded-3xl overflow-hidden hover:border-blue-500/30 transition-all backdrop-blur-sm shadow-2xl mb-8">
      <div className="flex flex-col lg:flex-row">
        {/* Visual Preview Panel */}
        <div className="w-full lg:w-1/3 p-6 bg-slate-900/60 border-b lg:border-b-0 lg:border-r border-slate-700/50 flex flex-col justify-between space-y-6">
           <div>
              <div className="flex justify-between items-center mb-4">
                 <span className="text-blue-500 text-[10px] font-black uppercase tracking-[0.3em]">{segment.sectionTitle}</span>
                 {onRemove && <button onClick={onRemove} className="text-slate-600 hover:text-red-400"><i className="fa-solid fa-trash-can text-xs"></i></button>}
              </div>
              <p className="text-lg font-serif italic text-slate-300 mb-6">"{segment.lyrics}"</p>
           </div>

           <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                 <div className="aspect-video bg-black rounded-xl overflow-hidden relative border border-white/5">
                    {segment.firstFrame ? <img src={segment.firstFrame} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-[8px] text-slate-800 uppercase font-black">Frame A</div>}
                    <span className="absolute bottom-2 left-2 px-2 py-0.5 bg-black/60 rounded text-[7px] font-black uppercase text-blue-400">Start</span>
                 </div>
                 <div className="aspect-video bg-black rounded-xl overflow-hidden relative border border-white/5">
                    {segment.lastFrame ? <img src={segment.lastFrame} className="w-full h-full object-cover" /> : <div className="w-full h-full flex items-center justify-center text-[8px] text-slate-800 uppercase font-black">Frame B</div>}
                    <span className="absolute bottom-2 left-2 px-2 py-0.5 bg-black/60 rounded text-[7px] font-black uppercase text-indigo-400">Peak</span>
                 </div>
              </div>
              {onProcess && (
                <button onClick={onProcess} className={`w-full py-4 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border ${segment.firstFrame ? 'bg-slate-800 border-slate-700 text-slate-400 hover:text-white' : 'bg-blue-600 border-blue-500 text-white shadow-xl shadow-blue-500/20'}`}>
                  <i className={`fa-solid ${segment.firstFrame ? 'fa-rotate' : 'fa-wand-magic-sparkles'} mr-2`}></i>
                  {segment.firstFrame ? 'Regenerate Suite' : 'Process Visuals'}
                </button>
              )}
           </div>
        </div>

        {/* Content & Logic Panel */}
        <div className="w-full lg:w-2/3 p-8 grid grid-cols-1 md:grid-cols-2 gap-10">
           <div className="space-y-6">
              <div>
                 <div className="flex justify-between items-center mb-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Visual Narrative</label><CharacterShortcuts field="visuals" /></div>
                 <textarea value={segment.visuals} onChange={(e) => handleChange('visuals', e.target.value)} className="w-full bg-slate-900/50 border border-slate-700/50 rounded-2xl p-4 text-sm text-slate-200 focus:border-blue-500/50 outline-none h-40 resize-none shadow-inner" placeholder="AI-generated description..." />
              </div>
              <div className="grid grid-cols-1 gap-6">
                <div>
                   <div className="flex justify-between items-center mb-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Camera Dynamics</label><CharacterShortcuts field="cameraWork" /></div>
                   <textarea value={segment.cameraWork} onChange={(e) => handleChange('cameraWork', e.target.value)} rows={3} className="w-full bg-slate-900/50 border border-slate-700/50 rounded-xl p-4 text-xs text-slate-400 focus:border-blue-500/50 outline-none resize-none" placeholder="Lens, movement..." />
                </div>
                <div>
                   <div className="flex justify-between items-center mb-2"><label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Atmosphere</label><CharacterShortcuts field="lightingMood" /></div>
                   <textarea value={segment.lightingMood} onChange={(e) => handleChange('lightingMood', e.target.value)} rows={3} className="w-full bg-slate-900/50 border border-slate-700/50 rounded-xl p-4 text-xs text-slate-400 focus:border-blue-500/50 outline-none resize-none" placeholder="Lighting, colors..." />
                </div>
              </div>
           </div>

           <div className="space-y-4">
              <div className="flex justify-between items-center">
                 <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Architectural Map</label>
                 <button onClick={handleBuildDiagram} disabled={isGeneratingDiagram || !segment.visuals} className="text-[9px] font-black text-blue-400 hover:text-blue-300 uppercase tracking-widest flex items-center gap-2">
                    {isGeneratingDiagram ? <i className="fa-solid fa-spinner animate-spin"></i> : <i className="fa-solid fa-bolt"></i>}
                    {segment.mermaidDiagram ? 'Sync Map' : 'Build Map'}
                 </button>
              </div>
              <div className="w-full h-[400px] bg-slate-900/50 border border-slate-700/50 rounded-[2rem] overflow-auto flex items-center justify-center p-4">
                 {segment.mermaidDiagram ? <MermaidChart chart={segment.mermaidDiagram} id={segment.id} /> : <span className="text-[10px] text-slate-700 uppercase font-black">Awaiting logic sync</span>}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default StoryboardCard;

import React, { useState, useMemo, useRef } from 'react';
import { generateSceneContent, generateFrame } from './services/geminiService';
import { AppStep, StoryboardSegment, StoryboardProject, Character } from './types';
import StoryboardCard from './components/StoryboardCard';
import CharacterManager from './components/CharacterManager';

const App: React.FC = () => {
  const [rawText, setRawText] = useState('');
  const [narrativeSeed, setNarrativeSeed] = useState('');
  const [characters, setCharacters] = useState<Character[]>([]);
  const [step, setStep] = useState<AppStep>(AppStep.PASTE_LYRICS);
  const [sceneMarkers, setSceneMarkers] = useState<number[]>([]);
  const [segments, setSegments] = useState<StoryboardSegment[]>([]);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const imageInputRef = useRef<HTMLInputElement>(null);
  const [activeCharId, setActiveCharId] = useState<string | null>(null);
  const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
  const [isGeneratingFrames, setIsGeneratingFrames] = useState(false);

  const lines = useMemo(() => rawText.split('\n').map(l => l.trim()).filter(l => l), [rawText]);

  const toggleMarker = (index: number) => {
    setSceneMarkers(prev => 
      prev.includes(index) ? prev.filter(i => i !== index) : [...prev, index].sort((a, b) => a - b)
    );
  };

  const handleCreateDrafts = async () => {
    setErrorMessage(null);
    const newSegments: StoryboardSegment[] = [];
    let currentLyrics: string[] = [];

    lines.forEach((line, idx) => {
      if (sceneMarkers.includes(idx) && currentLyrics.length > 0) {
        newSegments.push({
          id: `scene-${newSegments.length}`,
          sectionTitle: `Scene ${newSegments.length + 1}`,
          lyrics: currentLyrics.join('\n'),
          visuals: '',
          cameraWork: '',
          lightingMood: '',
          characters: []
        });
        currentLyrics = [];
      }
      currentLyrics.push(line);
    });

    if (currentLyrics.length > 0) {
      newSegments.push({
        id: `scene-${newSegments.length}`,
        sectionTitle: `Scene ${newSegments.length + 1}`,
        lyrics: currentLyrics.join('\n'),
        visuals: '',
        cameraWork: '',
        lightingMood: '',
        characters: []
      });
    }

    setSegments(newSegments);
    setStep(AppStep.RESOURCES);
  };

  const handleGoToProduction = async () => {
    setStep(AppStep.PRODUCTION);
    if (segments.some(s => !s.visuals)) {
      try {
        const populated = await Promise.all(segments.map(async (seg) => {
          if (seg.visuals) return seg;
          try {
            const aiData = await generateSceneContent(seg.lyrics, "Musical Video Storyboard", narrativeSeed, characters);
            return { ...seg, ...aiData };
          } catch (e) { return seg; }
        }));
        setSegments(populated);
      } catch (e) { console.error(e); }
    }
  };

  const handleProcessVisuals = async (sceneId: string) => {
    setActiveSceneId(sceneId);
    setErrorMessage(null);
    setStep(AppStep.FRAME_DEV);
    setIsGeneratingFrames(true);

    const segment = segments.find(s => s.id === sceneId);
    if (!segment) return;

    try {
      const [first, last] = await Promise.all([
        generateFrame(segment, characters, 'FIRST', narrativeSeed),
        generateFrame(segment, characters, 'LAST', narrativeSeed)
      ]);

      setSegments(prev => prev.map(s => 
        s.id === sceneId ? { ...s, firstFrame: first, lastFrame: last } : s
      ));
    } catch (err: any) {
      setErrorMessage(err.message.includes('QUOTA') ? "Limit reached. Wait a moment." : "Generation failed.");
    } finally {
      setIsGeneratingFrames(false);
    }
  };

  const updateSegment = (index: number, updated: StoryboardSegment) => {
    setSegments(prev => {
      const next = [...prev];
      next[index] = updated;
      return next;
    });
  };

  const saveProject = () => {
    const project: StoryboardProject = {
      rawText,
      narrativeSeed,
      sceneMarkers,
      segments,
      characters,
      step,
      version: "2.1.0"
    };
    const blob = new Blob([JSON.stringify(project, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `storyboard-bundle-${Date.now()}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleLoadClick = () => fileInputRef.current?.click();

  const loadProject = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const project = JSON.parse(event.target?.result as string) as StoryboardProject;
        setRawText(project.rawText || '');
        setNarrativeSeed(project.narrativeSeed || '');
        setSceneMarkers(project.sceneMarkers || []);
        setSegments(project.segments || []);
        setCharacters(project.characters || []);
        // Automatically send user to the Production tab upon successful upload
        setStep(AppStep.PRODUCTION);
      } catch (err) { alert("Invalid project file."); }
    };
    reader.readAsText(file);
    e.target.value = '';
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []) as File[];
    if (files.length === 0 || !activeCharId) return;
    files.forEach(file => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const dataUrl = event.target?.result as string;
        setCharacters(prev => prev.map(c => 
          c.id === activeCharId ? { ...c, images: [...(c.images || []), dataUrl].slice(0, 5) } : c
        ));
      };
      reader.readAsDataURL(file);
    });
    setActiveCharId(null);
    e.target.value = '';
  };

  const handlePrint = () => {
    window.print();
  };

  const activeSegment = segments.find(s => s.id === activeSceneId);

  return (
    <div className="min-h-screen bg-[#020617] text-slate-200">
      {/* GLOBAL PRINT LAYOUT - FORCING BLACK TEXT ON WHITE BG */}
      <div className="print-only text-black bg-white">
        <div className="border-b-4 border-black pb-8 mb-12 flex justify-between items-end">
          <div>
            <h1 className="text-6xl font-black uppercase tracking-tighter text-black">Production <span className="text-blue-600">Bundle</span></h1>
            <p className="text-lg font-bold text-gray-400 mt-2 uppercase tracking-widest">Master Storyboard • {new Date().toLocaleDateString()}</p>
          </div>
          <div className="text-right">
             <p className="text-sm font-black uppercase text-black">LyricLens AI Suite</p>
             <p className="text-xs text-gray-400">Reference: {narrativeSeed || 'Untitled'}</p>
          </div>
        </div>
        {segments.map((seg, idx) => (
          <div key={seg.id} className="storyboard-strip">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-12 h-12 bg-black text-white flex items-center justify-center font-black text-2xl rounded-lg">{idx + 1}</div>
              <h2 className="text-3xl font-black uppercase tracking-tight text-black">{seg.sectionTitle}</h2>
            </div>
            <div className="grid grid-cols-2 gap-6 mb-10">
              <div className="aspect-video bg-gray-50 border border-gray-100 rounded-xl overflow-hidden shadow-sm">
                {seg.firstFrame && <img src={seg.firstFrame} className="w-full h-full object-cover" alt="Start Frame" />}
              </div>
              <div className="aspect-video bg-gray-50 border border-gray-100 rounded-xl overflow-hidden shadow-sm">
                {seg.lastFrame && <img src={seg.lastFrame} className="w-full h-full object-cover" alt="Peak Frame" />}
              </div>
            </div>
            <div className="grid grid-cols-12 gap-10">
              <div className="col-span-4">
                <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-2 border-b border-gray-100 pb-1">Script Context</h4>
                <p className="text-sm font-serif italic text-gray-700 leading-relaxed bg-gray-50 p-4 rounded-xl border border-gray-100">"{seg.lyrics}"</p>
              </div>
              <div className="col-span-8 space-y-4">
                <div>
                   <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Visual Action</h4>
                   <p className="text-sm font-bold text-gray-900">{seg.visuals}</p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div>
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Camera</h4>
                    <p className="text-xs text-gray-600">{seg.cameraWork}</p>
                  </div>
                  <div>
                    <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-1">Atmosphere</h4>
                    <p className="text-xs text-gray-600">{seg.lightingMood}</p>
                  </div>
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      <header className="sticky top-0 z-50 bg-[#020617]/90 backdrop-blur-md border-b border-white/5 no-print px-6 py-3 flex justify-between items-center">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center shadow-lg shadow-blue-500/30 cursor-pointer" onClick={() => setStep(AppStep.PASTE_LYRICS)}>
            <i className="fa-solid fa-clapperboard text-white text-xs"></i>
          </div>
          <h1 className="text-md font-black tracking-tighter uppercase italic">LyricLens <span className="text-blue-500">Studio</span></h1>
        </div>
        <div className="flex items-center gap-4">
          <div className="hidden md:flex items-center gap-4 mr-4">
            {[AppStep.PASTE_LYRICS, AppStep.DEFINE_SCENES, AppStep.RESOURCES, AppStep.PRODUCTION].map((s) => (
              <div key={s} className={`text-[10px] font-bold uppercase tracking-widest cursor-pointer ${step === s ? 'text-blue-500 border-b-2 border-blue-500 pb-1' : 'text-slate-600'}`} onClick={() => setStep(s)}>{s.replace('_', ' ')}</div>
            ))}
          </div>
          <input type="file" ref={fileInputRef} onChange={loadProject} accept=".json" className="hidden" />
          <button onClick={handleLoadClick} title="Load Project Bundle" className="p-2 text-slate-400 hover:text-white transition-colors text-[10px] font-bold uppercase"><i className="fa-solid fa-folder-open"></i></button>
          <button onClick={saveProject} title="Save Project Bundle" className="p-2 text-blue-400 hover:text-white transition-colors text-[10px] font-bold uppercase"><i className="fa-solid fa-floppy-disk"></i></button>
        </div>
      </header>

      {errorMessage && (
        <div className="fixed top-14 left-0 right-0 z-[60] bg-red-600 p-2 text-center no-print">
           <p className="text-[10px] font-black text-white uppercase tracking-widest">{errorMessage}</p>
        </div>
      )}

      <main className="max-w-7xl mx-auto px-6 py-8 no-print">
        {step === AppStep.PASTE_LYRICS && (
          <div className="max-w-2xl mx-auto py-12 animate-in fade-in zoom-in-95 duration-500">
            <div className="text-center mb-10">
              <h2 className="text-5xl font-black text-white mb-4 tracking-tighter uppercase">Director's <span className="text-blue-500">Input</span></h2>
              <p className="text-slate-400 font-medium">Define your narrative core and production seed.</p>
            </div>
            <div className="space-y-8">
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Aesthetic Seed</label>
                <input type="text" value={narrativeSeed} onChange={(e) => setNarrativeSeed(e.target.value)} placeholder="e.g. Gritty 35mm film noir, neon highlights..." className="w-full p-4 bg-slate-900 border border-white/5 rounded-2xl focus:ring-1 focus:ring-blue-500/50 outline-none text-sm text-white" />
              </div>
              <div className="space-y-2">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Lyrics / Story Script</label>
                <textarea value={rawText} onChange={(e) => setRawText(e.target.value)} placeholder="Paste your song text here..." className="w-full h-80 p-8 bg-slate-900 border border-white/5 rounded-3xl focus:ring-1 focus:ring-blue-500/50 outline-none text-xl font-serif text-white resize-none shadow-inner" />
              </div>
              <button onClick={() => setStep(AppStep.DEFINE_SCENES)} disabled={!rawText.trim()} className="w-full py-5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-500/20">Next: Define Breaks <i className="fa-solid fa-arrow-right ml-2"></i></button>
            </div>
          </div>
        )}

        {step === AppStep.DEFINE_SCENES && (
          <div className="max-w-xl mx-auto py-12 animate-in fade-in duration-500">
            <div className="text-center mb-8">
              <h2 className="text-4xl font-black text-white mb-2 uppercase">Scene <span className="text-blue-500">Pacing</span></h2>
              <p className="text-sm text-slate-400">Click between lines to create scene breaks.</p>
            </div>
            <div className="bg-slate-900/50 p-6 rounded-[2.5rem] border border-white/5 space-y-1">
              {lines.map((line, idx) => (
                <React.Fragment key={idx}>
                  {idx > 0 && (
                    <button onClick={() => toggleMarker(idx)} className="w-full py-2 group relative">
                      <div className={`h-[2px] transition-all ${sceneMarkers.includes(idx) ? 'w-full bg-blue-500 shadow-[0_0_10px_rgba(59,130,246,0.5)]' : 'w-1/6 bg-white/5 group-hover:w-full group-hover:bg-slate-700'}`}></div>
                    </button>
                  )}
                  <div className={`text-center py-2 font-serif transition-all ${sceneMarkers.includes(idx) ? 'text-white font-black text-lg' : 'text-slate-400 text-sm'}`}>{line}</div>
                </React.Fragment>
              ))}
            </div>
            <div className="mt-10 flex gap-4">
              <button onClick={() => setStep(AppStep.PASTE_LYRICS)} className="flex-1 py-4 bg-white/5 rounded-2xl font-bold uppercase tracking-widest">Back</button>
              <button onClick={handleCreateDrafts} className="flex-[2] py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest">Next: Moodboard</button>
            </div>
          </div>
        )}

        {step === AppStep.RESOURCES && (
          <div className="max-w-4xl mx-auto py-8 animate-in fade-in duration-500">
            <div className="text-center mb-12">
               <h2 className="text-5xl font-black text-white mb-4 tracking-tighter uppercase">Visual <span className="text-blue-500">Anchors</span></h2>
               <p className="text-slate-400 font-medium">Define your cast and upload references for AI continuity.</p>
            </div>
            <div className="bg-slate-900/50 p-10 rounded-[3rem] border border-white/5 shadow-2xl mb-12">
               <CharacterManager characters={characters} onUpdate={setCharacters} />
            </div>
            <div className="flex justify-center gap-6">
               <button onClick={() => setStep(AppStep.DEFINE_SCENES)} className="px-10 py-4 bg-white/5 rounded-2xl font-bold uppercase tracking-widest">Back</button>
               <button onClick={handleGoToProduction} className="px-12 py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest shadow-xl shadow-blue-500/20">Enter Production <i className="fa-solid fa-film ml-2"></i></button>
            </div>
          </div>
        )}

        {step === AppStep.PRODUCTION && (
          <div className="animate-in fade-in duration-700">
            <div className="flex flex-col md:flex-row justify-between items-end gap-6 mb-12">
              <div>
                <h2 className="text-5xl font-black text-white tracking-tighter uppercase">Director's <span className="text-blue-500">Board</span></h2>
                <div className="flex gap-6 mt-4">
                  <button onClick={() => setStep(AppStep.RESOURCES)} className="text-[10px] font-black text-blue-500 uppercase tracking-widest flex items-center gap-2 transition-colors hover:text-blue-400"><i className="fa-solid fa-users"></i> Edit Cast</button>
                  <button onClick={handlePrint} className="text-[10px] font-black text-emerald-500 uppercase tracking-widest flex items-center gap-2 transition-colors hover:text-emerald-400"><i className="fa-solid fa-file-pdf"></i> PDF Storyboard</button>
                </div>
              </div>
            </div>
            <div className="space-y-6">
              {segments.map((seg, idx) => (
                <StoryboardCard key={seg.id} segment={seg} characters={characters} onUpdate={(updated) => updateSegment(idx, updated)} onProcess={() => handleProcessVisuals(seg.id)} />
              ))}
            </div>
          </div>
        )}

        {step === AppStep.FRAME_DEV && activeSegment && (
          <div className="animate-in fade-in duration-500 max-w-5xl mx-auto py-12 space-y-12">
             <div className="bg-slate-900/80 p-8 rounded-[3rem] border border-white/10 flex justify-between items-center shadow-2xl backdrop-blur-md">
                <div>
                  <h2 className="text-3xl font-black text-white uppercase tracking-tighter mb-1">{activeSegment.sectionTitle}</h2>
                  <p className="text-xl text-slate-400 italic font-serif">"{activeSegment.lyrics}"</p>
